INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12078, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12078, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物体从高处向低处移动，通常由于重力作用。", "primary_collocate": null, "pronunciation": "diào xià lái", "ipa": "tjɑʊ̯˥˩ ɕjɑ˥˩ laɪ̯˧˥", "syllable_count": 3, "sentences": [{"text": "它不会掉下来，因为有升力。", "target_word": "掉下来", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "当它飞到另一朵花时，花粉会掉下来。", "target_word": "掉下来", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "苹果从树上掉下来了。", "target_word": "掉下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书从桌子上掉下来，吓了我一跳。", "target_word": "掉下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小心，墙上的画会掉下来。", "target_word": "掉下来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "树叶一片一片地掉下来。", "target_word": "掉下来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他爬得太高，差点掉下来。", "target_word": "掉下来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "风太大，树上的果子掉下来了。", "target_word": "掉下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前这座山上常有石头掉下来。", "target_word": "掉下来", "complexity_tier": "T3", "furigana": "yǐ qián zhè zuò shān shàng cháng yǒu shí tou diào xià lái", "sentence_source": "generated"}, {"text": "杯子从他手里掉下来，碎了一地。", "target_word": "掉下来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "掉下来", "label": "基本形式"}, {"form": "掉下来了", "label": "完成体"}, {"form": "掉下来过", "label": "经历体"}, {"form": "掉下來", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物体因重力从高处落到低处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2efa2384-c1dd-4c37-a182-92a2f89de8d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12078, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飞起来", "is_correct": false, "explanation": "语义：升力正是让它飞起来的原因，“不会飞起来，因为有升力”前后矛盾。"}, {"text": "掉下来", "is_correct": true, "explanation": "正确：“不会掉下来”表示不下落，与后半句“因为有升力”的语境一致。"}, {"text": "跑下来", "is_correct": false, "explanation": "搭配：“跑”指人或动物在地面快速移动，不能用于描述在空中的东西。"}, {"text": "站起来", "is_correct": false, "explanation": "搭配：“站起来”指人或动物起身，句中的“它”在空中，不能说“站起来”。"}], "explanations": {"飞起来": "语义：升力正是让它飞起来的原因，“不会飞起来，因为有升力”前后矛盾。", "掉下来": "正确：“不会掉下来”表示不下落，与后半句“因为有升力”的语境一致。", "跑下来": "搭配：“跑”指人或动物在地面快速移动，不能用于描述在空中的东西。", "站起来": "搭配：“站起来”指人或动物起身，句中的“它”在空中，不能说“站起来”。"}, "sentence_index": 0, "correct_answer": "掉下来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他爬上树，把苹果一个一个掉下来，装进篮子里。", "explanation": "这里应该用〈摘下来〉。掉下来指无意中落下，不能用于人有意采摘苹果的动作。"}, {"text": "热气球从地面掉下来，慢慢飞上了天空。", "explanation": "〈掉下来〉只表示由高往低的移动，这里描述的是上升，前后方向矛盾。"}, {"text": "他小心地把箱子掉下来，然后放在地上。", "explanation": "这里应该用〈放下来〉。掉下来多指无意中落下，不能与“小心地”这类有意控制的动作搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12078, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沉下去", "is_correct": false, "explanation": "搭配：“沉”多用于水或其他液体中下降，不能用于人在高处的下坠。"}, {"text": "掉下来", "is_correct": true, "explanation": "正确：“差点掉下来”表示险些从高处跌落，与“爬得太高”的语境一致。"}, {"text": "飞下来", "is_correct": false, "explanation": "语义：句中的“爬”说明是人在攀爬，人不会飞，“飞下来”与之不符。"}, {"text": "升上去", "is_correct": false, "explanation": "语义：“差点”提示的是险些跌落的危险，“升上去”表示向上，与语境相反。"}], "explanations": {"沉下去": "搭配：“沉”多用于水或其他液体中下降，不能用于人在高处的下坠。", "掉下来": "正确：“差点掉下来”表示险些从高处跌落，与“爬得太高”的语境一致。", "飞下来": "语义：句中的“爬”说明是人在攀爬，人不会飞，“飞下来”与之不符。", "升上去": "语义：“差点”提示的是险些跌落的危险，“升上去”表示向上，与语境相反。"}, "sentence_index": 6, "correct_answer": "掉下来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天气热了，他把外套掉下来，挂在椅背上。", "explanation": "这里应该用〈脱下来〉。掉下来指无意落下，不能用于人主动脱去衣服的动作。"}, {"text": "他踩着凳子，把旧灯掉下来，然后换了一个新的。", "explanation": "这里应该用〈取下来〉。掉下来是不及物动词，不能带“把”字宾语；有意拿下东西应说取下来。"}, {"text": "杯子从地上掉下来，又被他举到了桌子上。", "explanation": "〈掉下来〉只表示由高往低的移动，这里杯子从低处被举到高处，方向与词义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "箱子放在架子边上，别把它掉下来。", "corrected_sentence": "箱子放在架子边上，别让它掉下来。", "error_description": "错误在于用了“把”字句：“掉下来”是不及物动词，不能带“把”的宾语，应说“别让它掉下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨太大，树上的叶子都被掉下来了。", "corrected_sentence": "雨太大，树上的叶子都掉下来了。", "error_description": "错误在于多加了“被”。“掉下来”是不及物动词，不能用于被动句，应说“叶子都掉下来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12081, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12081, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12081, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人或动物用脚快速移动，使身体前进。", "primary_collocate": null, "pronunciation": "pǎo", "ipa": "pʰɑʊ̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "听到哨声，运动员们一起向前跑，很快就冲过了终点线。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫听见响声，跑得很快，一下子就躲进了床底。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在操场上跑来跑去。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗看见我，高兴地向我跑过来。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上都在公园里跑一个小时。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快下雨了，大家都往家里跑。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只兔子跑得比狗还快。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跑了很久，现在很累。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别在教室里跑，会撞到人。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看见老师来了，马上跑开了。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跑了", "label": "体标"}, {"form": "跑着", "label": "体标"}, {"form": "跑过", "label": "体标"}, {"form": "跑跑", "label": "重叠"}], "register": "中性", "sense_fingerprint": "人或动物用脚快速移动前进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c22b99d-de53-433a-91c3-3cfd2942df23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12081, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "跑", "is_correct": true, "explanation": "跑（pǎo，第三声）：人或动物用脚快速移动，是本题的正确答案。"}, {"text": "泡", "is_correct": false, "explanation": "泡（pào，第四声）与 pǎo 声调不同，意思是把东西浸在水里。"}, {"text": "抛", "is_correct": false, "explanation": "抛（pāo，第一声）与 pǎo 声调不同，意思是把东西扔出去。"}, {"text": "饱", "is_correct": false, "explanation": "饱（bǎo，第三声）与 pǎo 声母不同（b 与 p），意思是吃足了。"}, {"text": "袍", "is_correct": false, "explanation": "袍（páo，第二声）与 pǎo 声调不同，意思是长衣服。"}], "explanations": {"跑": "跑（pǎo，第三声）：人或动物用脚快速移动，是本题的正确答案。", "泡": "泡（pào，第四声）与 pǎo 声调不同，意思是把东西浸在水里。", "抛": "抛（pāo，第一声）与 pǎo 声调不同，意思是把东西扔出去。", "饱": "饱（bǎo，第三声）与 pǎo 声母不同（b 与 p），意思是吃足了。", "袍": "袍（páo，第二声）与 pǎo 声调不同，意思是长衣服。"}, "sentence_index": null, "correct_answer": "跑"}, "level_3": {"options": [{"text": "跑", "is_correct": true, "explanation": "跑：运动员向前快速移动，才能很快冲过终点线。"}, {"text": "停", "is_correct": false, "explanation": "语义：运动员停下来，就冲不过终点线，与后半句矛盾。"}, {"text": "躺", "is_correct": false, "explanation": "搭配：“躺”指人或动物平卧，与向前运动的意思不符。"}, {"text": "蹲", "is_correct": false, "explanation": "语义：“蹲”指身体下坐，与向前奔跑的意思不符。"}], "explanations": {"跑": "跑：运动员向前快速移动，才能很快冲过终点线。", "停": "语义：运动员停下来，就冲不过终点线，与后半句矛盾。", "躺": "搭配：“躺”指人或动物平卧，与向前运动的意思不符。", "蹲": "语义：“蹲”指身体下坐，与向前奔跑的意思不符。"}, "sentence_index": 0, "correct_answer": "跑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拄着拐杖，慢慢跑过了马路。", "explanation": "这里应该用〈走〉。跑指快速用脚移动，拄着拐杖慢慢移动不能说跑。"}, {"text": "他把书跑到了桌子上。", "explanation": "这里应该用〈搬〉。搬动书本要用搬，跑只用于人或动物自己用脚快速移动，书不能自己跑到桌上。"}, {"text": "鸭子在湖里跑着，很快就到了对岸。", "explanation": "这里应该用〈游〉。鸭子在水里移动要用游，跑指用脚在地面快速移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12081, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "跑", "is_correct": true, "explanation": "跑（pǎo，第三声）：人或动物用脚快速移动，是本题的正确答案。"}, {"text": "炮", "is_correct": false, "explanation": "炮（pào，第四声）与 pǎo 声调不同，意思是大炮。"}, {"text": "保", "is_correct": false, "explanation": "保（bǎo，第三声）与 pǎo 声母不同（b 与 p），意思是保护。"}, {"text": "刨", "is_correct": false, "explanation": "刨（páo，第二声）与 pǎo 声调不同，意思是用刀具削平或挖掘。"}], "explanations": {"跑": "跑（pǎo，第三声）：人或动物用脚快速移动，是本题的正确答案。", "炮": "炮（pào，第四声）与 pǎo 声调不同，意思是大炮。", "保": "保（bǎo，第三声）与 pǎo 声母不同（b 与 p），意思是保护。", "刨": "刨（páo，第二声）与 pǎo 声调不同，意思是用刀具削平或挖掘。"}, "sentence_index": null, "correct_answer": "跑"}, "level_3": {"options": [{"text": "跑", "is_correct": true, "explanation": "跑：兔子跑得比狗还快，符合常识，也与句中的比较相合。"}, {"text": "飞", "is_correct": false, "explanation": "语义：兔子不会飞，“飞得比狗还快”与事实不符。"}, {"text": "游", "is_correct": false, "explanation": "语义：兔子一般不游泳，句中也没有水，“游得比狗还快”说不通。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写得快”说的是书写速度，只能用于会写字的人，不能用于兔子。"}], "explanations": {"跑": "跑：兔子跑得比狗还快，符合常识，也与句中的比较相合。", "飞": "语义：兔子不会飞，“飞得比狗还快”与事实不符。", "游": "语义：兔子一般不游泳，句中也没有水，“游得比狗还快”说不通。", "写": "搭配：“写得快”说的是书写速度，只能用于会写字的人，不能用于兔子。"}, "sentence_index": 6, "correct_answer": "跑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天跑自行车去上班，路上很累。", "explanation": "这里应该用〈骑〉。骑自行车要用骑，跑是用脚快速移动，不能带“自行车”作宾语。"}, {"text": "小鸟在天上跑，很快就到了山顶。", "explanation": "这里应该用〈飞〉。鸟在空中移动要用飞，跑是用脚在地面快速移动。"}, {"text": "他随手把客厅的灯跑掉了，屋里一下子黑了。", "explanation": "这里应该用〈关〉。关灯要用关，跑掉表示快速离开，不能表示关闭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12081, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到铃声，孩子们就进跑了教室。", "corrected_sentence": "听到铃声，孩子们就跑进了教室。", "error_description": "“跑进”是“跑”加方向补语“进”，应说“跑进了教室”，“进跑”的语序不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12081, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹跑特别快，每次比赛都能拿第一。", "corrected_sentence": "妹妹跑得特别快，每次比赛都能拿第一。", "error_description": "状态补语前要加“得”：应说“跑得特别快”，不能说“跑特别快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
