INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12083, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12083, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指液体或气体从物体表面或内部通过；也比喻时间等消逝。", "primary_collocate": null, "pronunciation": "liú guò", "ipa": "ljoʊ˧˥ kuo˥˩", "syllable_count": 2, "sentences": [{"text": "当飞机向前跑，空气从翅膀上下两边流过。", "target_word": "流过", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "所以飞机的形状要做得光滑，这样空气才能顺利流过，减少阻力。", "target_word": "流过", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工程师先做小模型，放在风洞里吹风，看空气怎么流过。", "target_word": "流过", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "当飞机跑得很快时，空气从翅膀上下流过。", "target_word": "流过", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "小河从学校旁边流过。", "target_word": "流过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长江流过很多城市，最后到海里。", "target_word": "流过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热水从管子里流过，房间就暖了。", "target_word": "流过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汗水从他的脸上流过。", "target_word": "流过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间从身边悄悄流过，孩子已经长大了。", "target_word": "流过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河流过我的家乡。", "target_word": "流过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流過", "label": "繁体"}, {"form": "流过了", "label": "体标"}], "register": "中性", "sense_fingerprint": "流过:液体或空气从表面或内部通过，也比喻时间消逝", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bff508bb-4dd4-4d17-9788-2be285a2506d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12083, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流过", "is_correct": true, "explanation": "“流过”表示气体从物体表面通过，与飞机向前运动时气流沿翅膀两侧流动的情景相合。"}, {"text": "聚集", "is_correct": false, "explanation": "语义：“聚集”指集中到一处，与气流沿翅膀两侧通过、向后流去的情景不符。"}, {"text": "停滞", "is_correct": false, "explanation": "语义：“停滞”指不再流动，与飞机向前运动、气流持续通过的情景相矛盾。"}, {"text": "挤压", "is_correct": false, "explanation": "搭配：“挤压”需要带受事宾语，不能直接说“空气从翅膀两边挤压”。"}], "explanations": {"流过": "“流过”表示气体从物体表面通过，与飞机向前运动时气流沿翅膀两侧流动的情景相合。", "聚集": "语义：“聚集”指集中到一处，与气流沿翅膀两侧通过、向后流去的情景不符。", "停滞": "语义：“停滞”指不再流动，与飞机向前运动、气流持续通过的情景相矛盾。", "挤压": "搭配：“挤压”需要带受事宾语，不能直接说“空气从翅膀两边挤压”。"}, "sentence_index": 0, "correct_answer": "流过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车流过隧道很快。", "explanation": "这里应该用〈通过〉。“流过”只用于液体、气体等流动的东西，车辆是固体，不能说“流过”隧道。"}, {"text": "他从门口流过，没有停下。", "explanation": "这里应该用〈走过〉。“流过”用于水、气等流动的东西，不能用来形容人走路。"}, {"text": "鸟从窗前流过。", "explanation": "这里应该用〈飞过〉。“流过”指液体或气体的流动，鸟是靠飞行经过的，不能用“流过”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12083, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流过", "is_correct": true, "explanation": "“流过”表示液体从管道内部通过，与热水在管中流动、房间变暖的因果相合。"}, {"text": "烧过", "is_correct": false, "explanation": "语义：“烧过”指物体被加热，热水不能“烧过”管子，与句中水流的情景不符。"}, {"text": "飘过", "is_correct": false, "explanation": "语义：“飘过”指轻物浮动移动，与热水在管子里流动的情景不符。"}, {"text": "挡住", "is_correct": false, "explanation": "配价：“挡住”需要带宾语表示被阻挡的对象，直接用在“从管子里”之后不成立。"}], "explanations": {"流过": "“流过”表示液体从管道内部通过，与热水在管中流动、房间变暖的因果相合。", "烧过": "语义：“烧过”指物体被加热，热水不能“烧过”管子，与句中水流的情景不符。", "飘过": "语义：“飘过”指轻物浮动移动，与热水在管子里流动的情景不符。", "挡住": "配价：“挡住”需要带宾语表示被阻挡的对象，直接用在“从管子里”之后不成立。"}, "sentence_index": 6, "correct_answer": "流过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路流过我的家乡。", "explanation": "这里应该用〈经过〉。路是固体，不能像水、气一样“流过”。"}, {"text": "这座大桥流过河面，连接两岸。", "explanation": "这里应该用〈跨过〉。桥梁是固定建筑，不能用“流过”描述它跨越河面。"}, {"text": "隧道流过大山。", "explanation": "这里应该用〈穿过〉。隧道是固体构造，“流过”只能用于液体或气体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12083, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条公路每天流过一座小桥。", "corrected_sentence": "这条小溪每天流过一座小桥。", "error_description": "错误在于主语：流过只用于液体、气体等流动的东西，公路是固体，不能说“流过”。应把主语换成“小溪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12083, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每天清晨，河水都从桥下流过了。", "corrected_sentence": "每天清晨，河水都从桥下流过。", "error_description": "错误在于“了”。“每天清晨”表示经常发生的习惯，与“流过了”表示已完成的一次性动作冲突，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
