INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12084, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指流动的空气，即气流。", "primary_collocate": null, "pronunciation": "kōng qì liú", "ipa": "kʰʊŋ˥ tɕʰi˥˩ lioʊ̯˧˥", "syllable_count": 3, "sentences": [{"text": "翅膀上方的空气流很快，飞机才能飞起来。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开风扇以后，房间里的空气流明显加快了。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山谷里的空气流很强，风筝飞得很高。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机飞行时，机翼周围有很快的空气流。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气流从窗户进来，房间里很凉快。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷空气流和热空气流碰到一起，就会下雨。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风洞里的空气流可以用机器控制。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟张开翅膀，利用向上的空气流飞得很高。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们用小旗子来看空气流的方向。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间没有窗户，没有空气流。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "流动的空气，气流", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c22b99d-de53-433a-91c3-3cfd2942df23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12084, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空气流", "is_correct": true, "explanation": "空气流：翅膀上方的空气流动很快，指的正是这股流动的空气。"}, {"text": "车流", "is_correct": false, "explanation": "语义：翅膀上面不会有车流，句子说不通。"}, {"text": "人流", "is_correct": false, "explanation": "语义：翅膀上面不会有人群在流动，句子说不通。"}, {"text": "电流", "is_correct": false, "explanation": "搭配：“电流”多与导线、电路搭配，不说翅膀上方的电流很快。"}], "explanations": {"空气流": "空气流：翅膀上方的空气流动很快，指的正是这股流动的空气。", "车流": "语义：翅膀上面不会有车流，句子说不通。", "人流": "语义：翅膀上面不会有人群在流动，句子说不通。", "电流": "搭配：“电流”多与导线、电路搭配，不说翅膀上方的电流很快。"}, "sentence_index": 0, "correct_answer": "空气流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他张开嘴，把窗外的空气流吃了下去。", "explanation": "这里应该用〈吸〉。吃是咽食物的动作，空气不能吃；吸入空气要说“吸”。"}, {"text": "屋里开着空气流，很凉快。", "explanation": "这里应该用〈空调〉。开的是设备，空气流是空气的流动，不能说开。"}, {"text": "我的衣服被空气流淋湿了。", "explanation": "这里应该用〈雨〉。淋湿衣服的是水，空气流没有水分，不能把衣服淋湿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12084, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空气流", "is_correct": true, "explanation": "空气流：风洞里的空气流动可以用机器控制，符合句意。"}, {"text": "水流", "is_correct": false, "explanation": "语义：风洞里是空气，不是水，“水流”与语境不符。"}, {"text": "河流", "is_correct": false, "explanation": "语义：风洞里不会有河流，句子说不通。"}, {"text": "洪流", "is_correct": false, "explanation": "搭配：“洪流”多指大水或潮水般的人群，不用于风洞里的气体流动。"}], "explanations": {"空气流": "空气流：风洞里的空气流动可以用机器控制，符合句意。", "水流": "语义：风洞里是空气，不是水，“水流”与语境不符。", "河流": "语义：风洞里不会有河流，句子说不通。", "洪流": "搭配：“洪流”多指大水或潮水般的人群，不用于风洞里的气体流动。"}, "sentence_index": 6, "correct_answer": "空气流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河里的空气流很急，船开得很慢。", "explanation": "这里应该用〈水流〉。河里流动的是水，不是空气，不能说空气流很急。"}, {"text": "伤口处空气流不止，需要马上包扎。", "explanation": "这里应该用〈血流〉。伤口流出的是血，不是空气。"}, {"text": "空气流从窗户照进来，房间很亮。", "explanation": "这里应该用〈阳光〉。光能照进来，空气流看不见也不发光，不能说照进来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗缝里吹进一股冷着空气流。", "corrected_sentence": "窗缝里吹进一股冷空气流。", "error_description": "错误：“冷着空气流”，“着”误加在修饰语“冷”之后，表示持续的“着”不能插在形容词和名词之间。正确：“冷空气流”，中间不加“着”，直接用“冷”修饰“空气流”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一条强烈的空气流吹散了烟雾。", "corrected_sentence": "一股强烈的空气流吹散了烟雾。", "error_description": "错误：“空气流”前的量词用“条”，“条”多用于河流、线条等细长事物；气流应用量词“股”。正确：“一股强烈的空气流”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
