INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12085, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物理学是研究物质、能量、力、运动以及它们之间相互关系的自然科学。", "primary_collocate": null, "pronunciation": "wù lǐ xué", "ipa": "u⁵¹ li²¹⁴ ɕɥe³⁵", "syllable_count": 3, "sentences": [{"text": "此时，半导体物理学的成熟为能源转型提供了关键支点。", "target_word": "物理学", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "物理学研究这些东西。", "target_word": "物理学", "complexity_tier": "T1", "sentence_source": "mined"}, {"text": "他大学时学的是物理学。", "target_word": "物理学", "complexity_tier": "T3", "furigana": "tā dà xué shí xué de shì wù lǐ xué", "sentence_source": "generated"}, {"text": "物理学是一门自然科学。", "target_word": "物理学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对物理学很感兴趣。", "target_word": "物理学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物理学课上，老师讲了力和运动。", "target_word": "物理学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥正在读物理学博士。", "target_word": "物理学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习物理学需要很好的数学。", "target_word": "物理学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱因斯坦对物理学有很大的贡献。", "target_word": "物理学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物理学研究光、热、声和电。", "target_word": "物理学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "物理学家", "label": "复合"}, {"form": "物理學", "label": "繁体"}], "register": "中性", "sense_fingerprint": "研究物质、能量、力和运动的自然科学学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5f59174-23ab-4b8b-9546-74dc82c078e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12085, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物理学", "is_correct": true, "explanation": "正确：物理学指研究物质与能量的学科，半导体的成熟正属于其研究成果，词性与语义都合适。"}, {"text": "生物学", "is_correct": false, "explanation": "语义：生物学研究生命现象，与半导体这类物质材料不相关，“半导体生物学”说不通。"}, {"text": "历史", "is_correct": false, "explanation": "搭配：“成熟”说技术或学科的发展，不说历史，“历史的成熟”搭配不当。"}, {"text": "艺术", "is_correct": false, "explanation": "语义：艺术与半导体技术无关，“半导体艺术的成熟”与句中能源转型的语境相矛盾。"}], "explanations": {"物理学": "正确：物理学指研究物质与能量的学科，半导体的成熟正属于其研究成果，词性与语义都合适。", "生物学": "语义：生物学研究生命现象，与半导体这类物质材料不相关，“半导体生物学”说不通。", "历史": "搭配：“成熟”说技术或学科的发展，不说历史，“历史的成熟”搭配不当。", "艺术": "语义：艺术与半导体技术无关，“半导体艺术的成熟”与句中能源转型的语境相矛盾。"}, "sentence_index": 0, "correct_answer": "物理学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他学了一只物理学。", "explanation": "这里应该用〈门〉。学科名词用“门”计量，“只”用于动物等，不用于学科。"}, {"text": "我妈妈是物理学，她在大学教书。", "explanation": "这里应该用〈物理学家〉。物理学指学科，指称人要说“物理学家”。"}, {"text": "他把物理学煮了一锅汤。", "explanation": "语义：物理学是学科，不是食物，不能被煮，只能用于可食用的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12085, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物理学", "is_correct": true, "explanation": "正确：“物理学博士”是常见组合，指物理学专业的博士学位。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球是运动项目，不是学科，“读篮球博士”说不通。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不是学科，不能用来修饰“博士”。"}, {"text": "学士", "is_correct": false, "explanation": "搭配：“博士”与“学士”都是学位，不能叠加修饰，“读学士博士”不通。"}], "explanations": {"物理学": "正确：“物理学博士”是常见组合，指物理学专业的博士学位。", "篮球": "语义：篮球是运动项目，不是学科，“读篮球博士”说不通。", "蛋糕": "语义：蛋糕不是学科，不能用来修饰“博士”。", "学士": "搭配：“博士”与“学士”都是学位，不能叠加修饰，“读学士博士”不通。"}, "sentence_index": 6, "correct_answer": "物理学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是化学变化，不是物理学变化。", "explanation": "这里应该用〈物理〉。“物理”作定语，指物理变化、物理性质；“物理学”是学科名称，不能修饰“变化”。"}, {"text": "工程师正在研制物理学，要花很多钱。", "explanation": "这里应该用〈研究〉。“研制”用于设备、产品，学问要说“研究”。"}, {"text": "这块石头的物理学很硬。", "explanation": "这里应该用〈性质〉。“物理学”是学科名称，不指石头的物理性质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12085, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "表弟大学时选了一个物理学。", "corrected_sentence": "表弟大学时选了一门物理学。", "error_description": "量词错误：学科名词“物理学”应用量词“门”，写成“一个”是错误形式，应改为“一门物理学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12085, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "表哥想学物理学家，将来当工程师。", "corrected_sentence": "表哥想学物理学，将来当工程师。", "error_description": "错误：“学”的对象应是学科“物理学”，“物理学家”指人，不能作“学”的宾语，应说“想学物理学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
