INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12087, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用科学知识设计和制造机器或结构的学科", "primary_collocate": null, "pronunciation": "gōng chéng xué", "ipa": "kʊŋ⁵⁵ ʈʂʰɤŋ³⁵ ɕɥe³⁵", "syllable_count": 3, "sentences": [{"text": "工程学帮助人们造飞机。", "target_word": "工程学", "complexity_tier": "T1", "sentence_source": "mined"}, {"text": "工程学教我们怎样设计机器。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢工程学，因为可以自己做机器。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程学课上，我们造了一座小桥。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学工程学的人会用科学知识造房子。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在大学学工程学，现在设计汽车。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程学需要数学，也需要动手做。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本工程学书里有很多机器的图。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要造高铁，需要很多懂工程学的人。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程学让人们造出更快的船。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工程學", "label": "繁体"}], "register": "中性", "sense_fingerprint": "工程学：用科学知识设计、制造机器和结构的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d47bea1-7ac4-4021-b5ba-f873b2971d0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12087, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工程学", "is_correct": true, "explanation": "工程学：用科学知识设计、制造机器和结构的学科，填入后“工程学帮助人们造飞机”符合语境。"}, {"text": "园艺学", "is_correct": false, "explanation": "语义：园艺学研究栽培植物，不能帮助人造飞机。"}, {"text": "医学", "is_correct": false, "explanation": "语义：医学研究治病，与造飞机无关。"}, {"text": "饭馆", "is_correct": false, "explanation": "搭配：“饭馆”不能作“帮助人造飞机”的主语。"}], "explanations": {"工程学": "工程学：用科学知识设计、制造机器和结构的学科，填入后“工程学帮助人们造飞机”符合语境。", "园艺学": "语义：园艺学研究栽培植物，不能帮助人造飞机。", "医学": "语义：医学研究治病，与造飞机无关。", "饭馆": "搭配：“饭馆”不能作“帮助人造飞机”的主语。"}, "sentence_index": 0, "correct_answer": "工程学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这项工程学要用两年才能完成。", "explanation": "这里应该用〈工程〉。工程指具体的建设项目，工程学是学科，不能指一项工程。"}, {"text": "他是一名工程学。", "explanation": "这里应该用〈工程师〉。工程学指学科，指人要说工程师。"}, {"text": "这座大楼的工程学很漂亮。", "explanation": "这里应该用〈建筑〉。工程学是学科，不能用来形容大楼的外观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12087, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工程学", "is_correct": true, "explanation": "工程学：用科学知识设计和制造机器的学科，填入后“工程学需要数学”符合语境。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌不需要数学，也不需要动手造机器，句子说不通。"}, {"text": "相声", "is_correct": false, "explanation": "语义：相声是曲艺，与“需要数学、需要动手做”的说法无关。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文学体裁，不需要数学，也谈不上动手做，句子说不通。"}], "explanations": {"工程学": "工程学：用科学知识设计和制造机器的学科，填入后“工程学需要数学”符合语境。", "诗歌": "语义：诗歌不需要数学，也不需要动手造机器，句子说不通。", "相声": "语义：相声是曲艺，与“需要数学、需要动手做”的说法无关。", "小说": "语义：小说是文学体裁，不需要数学，也谈不上动手做，句子说不通。"}, "sentence_index": 6, "correct_answer": "工程学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工程学有三百名工人。", "explanation": "这里应该用〈工厂〉。工程学是学科，不能指拥有工人的单位。"}, {"text": "这个工程学正在盖一座大楼。", "explanation": "这里应该用〈工程〉。工程学是学科，不会盖楼；盖楼的是一项工程。"}, {"text": "这家工程学下个月要搬到新大楼。", "explanation": "这里应该用〈公司〉。工程学是学科，不能搬家，指单位要说公司。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12087, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我哥哥在大学学的是一个工程学。", "corrected_sentence": "我哥哥在大学学的是一门工程学。", "error_description": "量词错误：学科用“门”，不用“个”。应说“一门工程学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12087, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹学工程学学很认真。", "corrected_sentence": "我妹妹学工程学学得很认真。", "error_description": "补语标记“得”漏掉。“学”的程度补语要用“学得很认真”，应说“学工程学学得很认真”，不能说“学工程学学很认真”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
