INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12088, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "制造；建造：～船｜～纸｜创～。", "primary_collocate": null, "pronunciation": "zào", "ipa": "tsɑʊ˥˩", "syllable_count": 1, "sentences": [{"text": "工程学帮助人们造飞机。", "target_word": "造", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "工人们正在河边造一座新桥。", "target_word": "造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂专门造汽车。", "target_word": "造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷用木头给我造了一间小房子。", "target_word": "造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的人用树皮造纸。", "target_word": "造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海边造了一条大船。", "target_word": "造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用沙子造城堡。", "target_word": "造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子打算造一条新路。", "target_word": "造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想造一种更安静的电动车。", "target_word": "造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要造一座新学校，让孩子们有地方读书。", "target_word": "造", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "造了", "label": "体标"}, {"form": "造过", "label": "体标"}, {"form": "制造", "label": "复合"}, {"form": "建造", "label": "复合"}], "register": "通用", "sense_fingerprint": "制造、建造出具体的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b79c64-687c-41da-88a3-fa2136641a60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12088, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "造", "is_correct": true, "explanation": "正确答案。zào，意思是制造、建造。"}, {"text": "早", "is_correct": false, "explanation": "zǎo（第三声）与 zào（第四声）声调不同，意思是早。"}, {"text": "糟", "is_correct": false, "explanation": "zāo（第一声）与 zào（第四声）声调不同，意思是糟糕。"}, {"text": "照", "is_correct": false, "explanation": "zhào 与 zào 声母不同（zh/z），意思是照亮或照片。"}, {"text": "在", "is_correct": false, "explanation": "zài 与 zào 韵母不同（ai/ao），意思是在。"}], "explanations": {"造": "正确答案。zào，意思是制造、建造。", "早": "zǎo（第三声）与 zào（第四声）声调不同，意思是早。", "糟": "zāo（第一声）与 zào（第四声）声调不同，意思是糟糕。", "照": "zhào 与 zào 声母不同（zh/z），意思是照亮或照片。", "在": "zài 与 zào 韵母不同（ai/ao），意思是在。"}, "sentence_index": null, "correct_answer": "造"}, "level_3": {"options": [{"text": "造", "is_correct": true, "explanation": "正确。“造”表示制造、建造，与“工程学帮助人们”的语境相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是发出歌声，不能用来指制作飞机，与“工程学”的语境矛盾。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”只用于食物或液体，不能说“煮飞机”。"}, {"text": "吹", "is_correct": false, "explanation": "搭配：“吹”表示用气流发声或送风，不能跟“飞机”组合。"}], "explanations": {"造": "正确。“造”表示制造、建造，与“工程学帮助人们”的语境相符。", "唱": "语义：“唱”是发出歌声，不能用来指制作飞机，与“工程学”的语境矛盾。", "煮": "搭配：“煮”只用于食物或液体，不能说“煮飞机”。", "吹": "搭配：“吹”表示用气流发声或送风，不能跟“飞机”组合。"}, "sentence_index": 0, "correct_answer": "造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在院子里造了一棵大树。", "explanation": "这里应该用〈种〉。种植树木要用“种”，“造”指制造、建造具体的东西。"}, {"text": "妈妈每天在厨房里造饭。", "explanation": "这里应该用〈做〉。“造”指制造、建造具体的东西，做饭要用“做”。"}, {"text": "妈妈每天晚上造毛衣。", "explanation": "这里应该用〈织〉。“造”指制造、建造，织毛衣要用“织”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12088, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "造", "is_correct": true, "explanation": "正确答案。zào，意思是制造、建造。"}, {"text": "到", "is_correct": false, "explanation": "dào（第四声）与 zào 声母不同（d/z），意思是到达。"}, {"text": "叫", "is_correct": false, "explanation": "jiào（第四声）与 zào 声母不同（j/z），意思是叫做。"}, {"text": "罩", "is_correct": false, "explanation": "zhào（第四声）与 zào 声母不同（zh/z），意思是罩子。"}, {"text": "告", "is_correct": false, "explanation": "gào（第四声）与 zào 声母不同（g/z），意思是告诉。"}], "explanations": {"造": "正确答案。zào，意思是制造、建造。", "到": "dào（第四声）与 zào 声母不同（d/z），意思是到达。", "叫": "jiào（第四声）与 zào 声母不同（j/z），意思是叫做。", "罩": "zhào（第四声）与 zào 声母不同（zh/z），意思是罩子。", "告": "gào（第四声）与 zào 声母不同（g/z），意思是告诉。"}, "sentence_index": null, "correct_answer": "造"}, "level_3": {"options": [{"text": "造", "is_correct": true, "explanation": "正确。“造城堡”指用沙子建造城堡，与“孩子们用沙子”的语境相符。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造新事物或方法，与孩子用沙子玩耍的语境不合。"}, {"text": "买", "is_correct": false, "explanation": "配价：“买”需要用钱交换，不能用沙子来买城堡。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃城堡”。"}], "explanations": {"造": "正确。“造城堡”指用沙子建造城堡，与“孩子们用沙子”的语境相符。", "发明": "语义：“发明”指创造新事物或方法，与孩子用沙子玩耍的语境不合。", "买": "配价：“买”需要用钱交换，不能用沙子来买城堡。", "吃": "搭配：“吃”的对象是食物，不能说“吃城堡”。"}, "sentence_index": 6, "correct_answer": "造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师让我们回家造作文。", "explanation": "这里应该用〈写〉。“造”用于制造、建造具体的东西，写作文要用“写”。"}, {"text": "我们学校每年造一场运动会。", "explanation": "这里应该用〈举办〉。“造”指制造、建造具体的东西，举办运动会要用“举办”。"}, {"text": "他们慢慢造了深厚的感情。", "explanation": "这里应该用〈培养〉。感情是慢慢养成的，“造”的对象是具体的东西，不能用于感情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12088, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想造了一间小房子。", "corrected_sentence": "我想造一间小房子。", "error_description": "体标错误：“想”表示意愿，后面的“造”不能带“了”。应说“我想造一间小房子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12088, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们造桥得很快。", "corrected_sentence": "工人们造桥造得很快。", "error_description": "V得结构错误：“造得很快”前要重复动词“造”，应说“造桥造得很快”，不能只说“造桥得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
