INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12089, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "阻止人或物的前进或视线。", "primary_collocate": null, "pronunciation": "dǎng zhù", "ipa": "tɑŋ˨˩˦ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "但是空气也会挡住飞机的路。", "target_word": "挡住", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这种挡住飞机的力叫“阻力”。", "target_word": "挡住", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "阻力是空气挡住飞机的力量。", "target_word": "挡住", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "前面的大树挡住了我的视线。", "target_word": "挡住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在门口，挡住了我的路。", "target_word": "挡住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个高个子挡住了我，我看不见舞台。", "target_word": "挡住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用手挡住脸，别让太阳晒到。", "target_word": "挡住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高高的墙挡住了风，院子里很安静。", "target_word": "挡住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "守门员伸出手，挡住了那个球。", "target_word": "挡住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你让一下，你挡住后面的人了。", "target_word": "挡住", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挡住了", "label": "体标"}, {"form": "挡着", "label": "体标"}, {"form": "挡不住", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "拦住人或物的前进，或遮住视线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c22b99d-de53-433a-91c3-3cfd2942df23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12089, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挡住", "is_correct": true, "explanation": "正确：“挡住”指拦住，空气阻挡飞机的运动，符合句意。"}, {"text": "修建", "is_correct": false, "explanation": "语义：空气不能修建道路，“修建”的主体应是人。"}, {"text": "观察", "is_correct": false, "explanation": "语义：空气没有意识，不会观察，观察需要有意识的主体。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”多用于地面、房间，不能说打扫“飞机的路”。"}], "explanations": {"挡住": "正确：“挡住”指拦住，空气阻挡飞机的运动，符合句意。", "修建": "语义：空气不能修建道路，“修建”的主体应是人。", "观察": "语义：空气没有意识，不会观察，观察需要有意识的主体。", "打扫": "搭配：“打扫”多用于地面、房间，不能说打扫“飞机的路”。"}, "sentence_index": 0, "correct_answer": "挡住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他挡住了长时间的疼痛，没有叫出声。", "explanation": "这里应该用〈忍受〉。挡住指用身体或物体拦住具体的人或物，疼痛只能忍受，不能被挡住。"}, {"text": "他挡住了那个问题，没有回答。", "explanation": "这里应该用〈回避〉。挡住针对能被拦住的人或物，问题不能被挡住；不回答问题要说“回避”。"}, {"text": "他挡住了那首歌，没有听完。", "explanation": "这里应该用〈关掉〉。挡住是拦住人或物，停止播放歌曲要说“关掉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12089, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挡住", "is_correct": true, "explanation": "正确：用手挡住脸，指用手遮挡，符合“别让太阳晒到”的语境。"}, {"text": "放", "is_correct": false, "explanation": "配价：“放”后要带处所或去向成分，“用手放脸”不成立，应说“放在脸上”。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：脸不能被讨论，“讨论”的对象应是问题或事情。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能和“脸”搭配，唱的对象是歌。"}], "explanations": {"挡住": "正确：用手挡住脸，指用手遮挡，符合“别让太阳晒到”的语境。", "放": "配价：“放”后要带处所或去向成分，“用手放脸”不成立，应说“放在脸上”。", "讨论": "语义：脸不能被讨论，“讨论”的对象应是问题或事情。", "唱": "搭配：“唱”不能和“脸”搭配，唱的对象是歌。"}, "sentence_index": 6, "correct_answer": "挡住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他挡住了这份责任。", "explanation": "这里应该用〈承担〉。挡住是拦住，责任要说“承担”。"}, {"text": "他挡住了自己的梦想。", "explanation": "这里应该用〈放弃〉。挡住针对能被拦住的人或物，梦想不能被挡住；放弃梦想要说“放弃”。"}, {"text": "他挡住了我的错误。", "explanation": "这里应该用〈原谅〉。挡住是拦住，错误要说“原谅”，不能说挡住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12089, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一堵墙挡住得了那辆汽车。", "corrected_sentence": "一堵墙挡住了那辆汽车。", "error_description": "错误：“挡住得了”，可能补语的“得”插在“住”之后、“了”之前，结构混乱。正确：“挡住了”，“了”直接放在“挡住”之后，不加“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12089, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没挡住了我的路。", "corrected_sentence": "他没挡住我的路。", "error_description": "错误：“没挡住了”，用“没”否定已发生的动作时，动词后不加“了”。正确：“没挡住”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
