INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12090, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "把热能、电能等转化为机械能的机器，是车辆、飞机等设备动力的来源。", "primary_collocate": null, "pronunciation": "fā dòng jī", "ipa": "fa˥ tʊŋ˥˩ tɕi˥", "syllable_count": 3, "sentences": [{"text": "发动机要有足够的力量，才能让飞机向前。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有发动机，飞机就会慢下来。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这辆车的发动机声音很大。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发动机坏了，汽车开不了。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在检查飞机的发动机。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆电动车没有汽油发动机。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发动机需要油才能工作。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打开车盖，看了看发动机。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台发动机是工厂新造的。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车前要先让发动机热一会儿。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "柴油发动机", "label": "复合"}, {"form": "汽油发动机", "label": "复合"}, {"form": "發動機", "label": "繁体"}], "register": "通用", "sense_fingerprint": "把热能电能转化为机械能的动力机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b79c64-687c-41da-88a3-fa2136641a60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12090, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发动机", "is_correct": true, "explanation": "发动机产生动力，正是能提供足够力量、让飞机向前的那个部件。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是坐在飞机上的人，不能“用力”让飞机向前。"}, {"text": "跑道", "is_correct": false, "explanation": "语义：跑道是供飞机起降的地面，本身不产生推动飞机的力量。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位是给人坐的地方，本身不产生推动飞机的力。"}], "explanations": {"发动机": "发动机产生动力，正是能提供足够力量、让飞机向前的那个部件。", "乘客": "语义：乘客是坐在飞机上的人，不能“用力”让飞机向前。", "跑道": "语义：跑道是供飞机起降的地面，本身不产生推动飞机的力量。", "座位": "语义：座位是给人坐的地方，本身不产生推动飞机的力。"}, "sentence_index": 0, "correct_answer": "发动机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台洗衣机的发动机坏了，要请人修。", "explanation": "这里应该用〈马达〉。洗衣机等家用电器的动力部件通常叫马达，发动机多指汽车、飞机等机器。"}, {"text": "这个搜索发动机很快。", "explanation": "这里应该用〈引擎〉。“搜索引擎”是固定说法，发动机指实体的动力机器，不用于搜索服务。"}, {"text": "这座水电站的发动机每年发很多电。", "explanation": "这里应该用〈发电机〉。发电机把机械能变成电能，发动机则把能量变成机械能，方向正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12090, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发动机", "is_correct": true, "explanation": "发动机靠燃料工作，“需要油”说的正是它的燃料，符合语境。"}, {"text": "电池", "is_correct": false, "explanation": "语义：电池靠化学能或电能供电，不靠油工作。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡靠电发光，本身不需要油。"}, {"text": "收音机", "is_correct": false, "explanation": "搭配：收音机是用电的，不说“需要油才能工作”。"}], "explanations": {"发动机": "发动机靠燃料工作，“需要油”说的正是它的燃料，符合语境。", "电池": "语义：电池靠化学能或电能供电，不靠油工作。", "灯泡": "语义：灯泡靠电发光，本身不需要油。", "收音机": "搭配：收音机是用电的，不说“需要油才能工作”。"}, "sentence_index": 6, "correct_answer": "发动机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑的发动机太吵了，要换一个。", "explanation": "这里应该用〈风扇〉。电脑的噪音和散热主要来自风扇，发动机指汽车、飞机等机器的动力部分，不用于电脑。"}, {"text": "他决定发动机进攻，明天出发。", "explanation": "这里应该用〈发动〉。“发动”是动词，如发动进攻；发动机是名词，不能代替动词。"}, {"text": "这台冰箱的发动机坏了，制冷很慢。", "explanation": "这里应该用〈压缩机〉。冰箱制冷靠压缩机，发动机指汽车、飞机等机器的动力部分，不用于冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12090, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一辆发动机。", "corrected_sentence": "我买了一台发动机。", "error_description": "量词错误：发动机是机器，量词应用“台”，不能用“辆”（“辆”用于车辆）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12090, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我哥哥发动机是新的。", "corrected_sentence": "我哥哥的发动机是新的。", "error_description": "“的”漏用：领属定语“我哥哥”后要加“的”，应说“我哥哥的发动机”，不能说“我哥哥发动机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12092, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12092, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12092, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "降低行动或进程的速度，使节奏放缓。", "primary_collocate": null, "pronunciation": "màn xià lái", "ipa": "man˥˩ ɕja˥˩ lai˧˥", "syllable_count": 3, "sentences": [{"text": "没有发动机，飞机就会慢下来。", "target_word": "慢下来", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "看到红灯，车子都慢下来了。", "target_word": "慢下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作太忙，我们都该慢下来休息一下。", "target_word": "慢下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上坡的时候，自行车慢下来了。", "target_word": "慢下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路很滑，开车的人都慢下来了。", "target_word": "慢下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快到站了，火车开始慢下来。", "target_word": "慢下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生活太快，我想慢下来，看看风景。", "target_word": "慢下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，你跑步的时候要慢下来，别太累。", "target_word": "慢下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑到最后，他累了，脚步慢下来了。", "target_word": "慢下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说得太快，学生请她慢下来。", "target_word": "慢下来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "慢下来了", "label": "体标"}, {"form": "慢了下来", "label": "体标"}], "register": "中性", "sense_fingerprint": "速度或节奏放缓·行动变慢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b79c64-687c-41da-88a3-fa2136641a60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12092, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "慢下来", "is_correct": true, "explanation": "没有动力，飞机会减速，正是“慢下来”的意思，与句意相合。"}, {"text": "快起来", "is_correct": false, "explanation": "语义：没有发动机，飞机不会加速，“快起来”与句意相反。"}, {"text": "飞起来", "is_correct": false, "explanation": "语义：没有发动机，飞机飞不起来，与句意矛盾。"}, {"text": "亮起来", "is_correct": false, "explanation": "语义：“亮起来”指变亮，与飞机的速度无关，与句意不合。"}], "explanations": {"慢下来": "没有动力，飞机会减速，正是“慢下来”的意思，与句意相合。", "快起来": "语义：没有发动机，飞机不会加速，“快起来”与句意相反。", "飞起来": "语义：没有发动机，飞机飞不起来，与句意矛盾。", "亮起来": "语义：“亮起来”指变亮，与飞机的速度无关，与句意不合。"}, "sentence_index": 0, "correct_answer": "慢下来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到噩耗后，她哭了很久，终于慢下来了。", "explanation": "这里应该用〈平静下来〉。慢下来指速度或节奏变慢，说情绪安定要用〈平静下来〉。"}, {"text": "吵闹的教室里，老师一喊，大家终于慢下来了。", "explanation": "这里应该用〈安静下来〉。慢下来说速度，声音停止、吵闹平息要用〈安静下来〉。"}, {"text": "这块铁烧得通红，要等它慢下来再碰。", "explanation": "这里应该用〈冷却下来〉。慢下来指速度变慢，不能用来说铁块降温；说温度降低可用“冷却下来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12092, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "慢下来", "is_correct": true, "explanation": "“慢下来”表示放慢生活节奏，与“生活太快”“看看风景”相合。"}, {"text": "快起来", "is_correct": false, "explanation": "语义：前文说生活太快，再“快起来”与“想看风景”的意思相反。"}, {"text": "忙起来", "is_correct": false, "explanation": "语义：忙起来就没有时间看风景，与句意矛盾。"}, {"text": "快下来", "is_correct": false, "explanation": "搭配：“快下来”指快速下来，不表示节奏放缓，不能和“生活”搭配。"}], "explanations": {"慢下来": "“慢下来”表示放慢生活节奏，与“生活太快”“看看风景”相合。", "快起来": "语义：前文说生活太快，再“快起来”与“想看风景”的意思相反。", "忙起来": "语义：忙起来就没有时间看风景，与句意矛盾。", "快下来": "搭配：“快下来”指快速下来，不表示节奏放缓，不能和“生活”搭配。"}, "sentence_index": 6, "correct_answer": "慢下来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨停后，天空的颜色终于慢下来了。", "explanation": "这里应该用〈变淡〉。慢下来指速度或节奏变慢，颜色的变化要说变淡，不能说慢下来。"}, {"text": "天气已经慢下来了，大家都换上了厚衣服。", "explanation": "这里应该用〈冷下来〉。慢下来说速度，说气温下降要用〈冷下来〉。"}, {"text": "他发烧了，体温终于慢下来了。", "explanation": "这里应该用〈降下来〉。慢下来指速度，说体温下降要用〈降下来〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12092, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路太滑，把车子要慢下来。", "corrected_sentence": "这条路太滑，车子要慢下来。", "error_description": "“慢下来”是不及物动词，指速度自己变慢，不能放进「把」字句；“把”需删去，应说“车子要慢下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12092, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他骑车下坡，车速被慢下来了。", "corrected_sentence": "他骑车下坡，车速慢下来了。", "error_description": "“慢下来”是不及物动词，指速度自己变慢，不能用「被」字句；“被”需删去，应说“车速慢下来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
