INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12095, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "乘坐飞机旅行或出行。", "primary_collocate": null, "pronunciation": "zuò fēi jī", "ipa": "tswo˥˩ feɪ˥ tɕi˥", "syllable_count": 3, "sentences": [{"text": "我们坐飞机去远方，又快又安全。", "target_word": "坐飞机", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "去北京太远，我们明天坐飞机去。", "target_word": "坐飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你坐飞机的时候怕不怕？", "target_word": "坐飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次坐飞机，有点儿紧张。", "target_word": "坐飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从上海到成都，坐飞机只要三个小时。", "target_word": "坐飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐飞机的时候，手机要关机。", "target_word": "坐飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷不喜欢坐飞机，他说坐火车更舒服。", "target_word": "坐飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐飞机回家过年。", "target_word": "坐飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理常常坐飞机去别的城市开会。", "target_word": "坐飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明坐飞机的时候，一直看着窗外。", "target_word": "坐飞机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "坐了飞机", "label": "体标"}, {"form": "坐过飞机", "label": "体标"}], "register": "中性", "sense_fingerprint": "乘飞机出行·交通方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b79c64-687c-41da-88a3-fa2136641a60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12095, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坐飞机", "is_correct": true, "explanation": "正确：乘飞机出行，符合“去远方，又快又安全”的语境。"}, {"text": "走路", "is_correct": false, "explanation": "语义：走路不快，与“又快”矛盾。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”不能表示去远方的交通方式。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”不是前往远方的方式，与“去远方”语义不合。"}], "explanations": {"坐飞机": "正确：乘飞机出行，符合“去远方，又快又安全”的语境。", "走路": "语义：走路不快，与“又快”矛盾。", "游泳": "搭配：“游泳”不能表示去远方的交通方式。", "吃饭": "语义：“吃饭”不是前往远方的方式，与“去远方”语义不合。"}, "sentence_index": 0, "correct_answer": "坐飞机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想当机长，所以先坐飞机练习。", "explanation": "这里应该用〈开〉。坐飞机指乘客乘机，练习驾驶飞机要说“开飞机”。"}, {"text": "这家工厂每天都坐飞机去外地。", "explanation": "这里应该用〈派人〉。工厂本身不能乘机，“坐飞机”的主语须是乘机的人，表示工厂派员出差要说“派人坐飞机”。"}, {"text": "这次考试我坐飞机通过了。", "explanation": "这里应该用〈顺利〉。“坐飞机”指乘机出行，不能表示通过考试；应说“顺利通过”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12095, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坐飞机", "is_correct": true, "explanation": "正确：与后半句“坐火车更舒服”构成乘坐方式的比较。"}, {"text": "坐火车", "is_correct": false, "explanation": "语义：“不喜欢坐火车”与后句“坐火车更舒服”自相矛盾。"}, {"text": "做饭", "is_correct": false, "explanation": "搭配：“做饭”与“坐火车更舒服”不能比较，构不成对比。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉不是交通方式，无法与“坐火车”比较舒适度。"}], "explanations": {"坐飞机": "正确：与后半句“坐火车更舒服”构成乘坐方式的比较。", "坐火车": "语义：“不喜欢坐火车”与后句“坐火车更舒服”自相矛盾。", "做饭": "搭配：“做饭”与“坐火车更舒服”不能比较，构不成对比。", "睡觉": "语义：睡觉不是交通方式，无法与“坐火车”比较舒适度。"}, "sentence_index": 6, "correct_answer": "坐飞机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆自行车昨天坐飞机去了上海。", "explanation": "这里应该用〈运〉。自行车是物品，不能乘机；“坐飞机”的主语只能是人，运送货物要说“用飞机运”。"}, {"text": "这一周的时间，一下子就坐飞机过去了。", "explanation": "这里应该用〈飞逝〉。“坐飞机”指乘机出行，形容时间很快过去要说“时光飞逝”。"}, {"text": "我们学校的老师都坐飞机学习汉语。", "explanation": "这里应该用〈上〉或〈去〉。“坐飞机”指乘机出行，不表示在飞机上学习的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12095, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我坐飞机时候，一直很紧张。", "corrected_sentence": "我坐飞机的时候，一直很紧张。", "error_description": "“坐飞机”后接表示时间的“时候”，中间须加结构助词“的”。错误形式“坐飞机时候”，正确形式“坐飞机的时候”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12095, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天我把坐飞机去北京。", "corrected_sentence": "今天我坐飞机去北京。", "error_description": "“坐飞机”是不及物的动宾短语，不能放进「把」字句处置；“把”需删去，应说“坐飞机去北京”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12097, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进入", "is_correct": true, "explanation": "反义：进入指由外到内，与离开的“从某处走开”方向相反，是此义的反义词。"}, {"text": "研究", "is_correct": false, "explanation": "研究是探求事理，与离开的动作没有相对关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步是悠闲地行走，与离开的动作不相对。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论是交换意见，与离开没有反义关系。"}], "correct_answer": "进入", "explanations": {"进入": "反义：进入指由外到内，与离开的“从某处走开”方向相反，是此义的反义词。", "研究": "研究是探求事理，与离开的动作没有相对关系。", "散步": "散步是悠闲地行走，与离开的动作不相对。", "讨论": "讨论是交换意见，与离开没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12097, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "留下", "is_correct": true, "explanation": "反义：留下指不再离去、继续停在原处，与离开的“走开”相对。"}, {"text": "修理", "is_correct": false, "explanation": "修理是使损坏的东西恢复正常，与离开没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌是发声演唱，与离开的动作不相对。"}, {"text": "生长", "is_correct": false, "explanation": "生长是植物或生物长大，与离开没有反义关系。"}], "correct_answer": "留下", "explanations": {"留下": "反义：留下指不再离去、继续停在原处，与离开的“走开”相对。", "修理": "修理是使损坏的东西恢复正常，与离开没有反义关系。", "唱歌": "唱歌是发声演唱，与离开的动作不相对。", "生长": "生长是植物或生物长大，与离开没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12097, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指人或事物从某处或某人身边走开，不再停留。", "primary_collocate": null, "pronunciation": "lí kāi", "ipa": "li˧˥ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "升力让飞机离开地面，飞上天空。", "target_word": "离开", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "火车八点离开北京。", "target_word": "离开", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他昨天离开了公司。", "target_word": "离开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟离开树，飞向远方。", "target_word": "离开", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子不想离开妈妈。", "target_word": "离开", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我离开家已经三年了。", "target_word": "离开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船慢慢离开了海边。", "target_word": "离开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你离开这个房间。", "target_word": "离开", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她离开座位，走到窗边。", "target_word": "离开", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "风筝离开了我的手，飞走了。", "target_word": "离开", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "离开了", "label": "体标（了）"}, {"form": "离开过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "人或事物从某处或某人身边走开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d46aa3-eeb1-4c0a-b496-7cdabfc5bb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12097, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "离开", "is_correct": true, "explanation": "“离开”指人或物从某处走开，正好说明升力让飞机脱离地面。"}, {"text": "接触", "is_correct": false, "explanation": "语义：接触指碰上、挨着，与句中“飞上天空”的意思不符。"}, {"text": "占领", "is_correct": false, "explanation": "搭配：占领用于阵地、领土，不用于飞机与地面的关系。"}, {"text": "落到", "is_correct": false, "explanation": "语义：落到地面是降下来，与“飞上天空”正相反。"}], "explanations": {"离开": "“离开”指人或物从某处走开，正好说明升力让飞机脱离地面。", "接触": "语义：接触指碰上、挨着，与句中“飞上天空”的意思不符。", "占领": "搭配：占领用于阵地、领土，不用于飞机与地面的关系。", "落到": "语义：落到地面是降下来，与“飞上天空”正相反。"}, "sentence_index": 0, "correct_answer": "离开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台冰箱离开墙三十厘米，散热很好。", "explanation": "这里应该用〈离〉。表示距离说“离墙三十厘米”，不说“离开墙三十厘米”；离开指人或物从某处走开，不表示距离。"}, {"text": "学校离开车站只有五分钟的路。", "explanation": "这里应该用〈离〉。表示距离说“离车站只有五分钟的路”，不说“离开车站”。"}, {"text": "我家离开湖边很近，夏天很凉快。", "explanation": "这里应该用〈离〉。表示距离说“离湖边很近”，不说“离开湖边很近”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12097, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "离开", "is_correct": true, "explanation": "“离开”指船从岸边驶开，与句中“慢慢”搭配自然。"}, {"text": "漂浮", "is_correct": false, "explanation": "配价：漂浮是不及物动词，不能直接带处所宾语，不能说漂浮了海边。"}, {"text": "辞别", "is_correct": false, "explanation": "语域：辞别书面色彩浓，多用于告别人或故乡，不用于船离岸的场景。"}, {"text": "停靠", "is_correct": false, "explanation": "配价：停靠要说“停靠在海边”，不能直接带海边作宾语。"}], "explanations": {"离开": "“离开”指船从岸边驶开，与句中“慢慢”搭配自然。", "漂浮": "配价：漂浮是不及物动词，不能直接带处所宾语，不能说漂浮了海边。", "辞别": "语域：辞别书面色彩浓，多用于告别人或故乡，不用于船离岸的场景。", "停靠": "配价：停靠要说“停靠在海边”，不能直接带海边作宾语。"}, "sentence_index": 6, "correct_answer": "离开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根柱子离开墙三米，很稳当。", "explanation": "这里应该用〈离〉。表示距离说“离墙三米”，离开只表示人或物从某处走开。"}, {"text": "超市离开地铁站很远，走路要二十分钟。", "explanation": "这里应该用〈离〉。表示距离说“离地铁站很远”，不说“离开地铁站很远”。"}, {"text": "这棵树离开路边太近，车不好转弯。", "explanation": "这里应该用〈离〉。表示距离说“离路边太近”，不说“离开路边太近”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12097, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他上周离开着实验室。", "corrected_sentence": "他上周离开了实验室。", "error_description": "“着”放错了：“着”表示动作持续的状态，“离开”是一次完成的动作，应说“离开了”，不说“离开着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12097, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从来没离开了这座小城。", "corrected_sentence": "她从来没离开过这座小城。", "error_description": "“从来没”后面要用“过”表示经历，不能用“了”；正确应为“离开过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
