INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12099, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "头顶广阔的空间，日月星辰所在的地方。", "primary_collocate": null, "pronunciation": "tiān kōng", "ipa": "tʰi̯ɛn˥ kʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "升力让飞机离开地面，飞上天空。", "target_word": "天空", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "天空是蓝色的，一朵云也没有。", "target_word": "天空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上天空中有很多星星。", "target_word": "天空", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一只鸟飞过天空。", "target_word": "天空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨前，天空变得很黑。", "target_word": "天空", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们抬头看着天空。", "target_word": "天空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的天空特别干净。", "target_word": "天空", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天空中飘着白云。", "target_word": "天空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳出来了，天空亮了。", "target_word": "天空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天空中挂着一个大月亮。", "target_word": "天空", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}], "register": "中性", "sense_fingerprint": "头顶广阔的空间，日月星辰所在之处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d46aa3-eeb1-4c0a-b496-7cdabfc5bb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12099, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天空", "is_correct": true, "explanation": "“天空”指头顶广阔的空间，是本词的正确答案。"}, {"text": "天宫", "is_correct": false, "explanation": "kōng 与 gōng 声母不同（k/g），天宫指神话中天上的宫殿或中国空间站，不是头顶的空间。"}, {"text": "天坑", "is_correct": false, "explanation": "kōng 与 kēng 韵母不同（-ong/-eng），天坑指地质上陷落形成的大洞，不是天空。"}, {"text": "挑空", "is_correct": false, "explanation": "tiān 与 tiāo 韵母不同（-an/-ao），挑空指建筑中上下贯通的空间，不指天空。"}], "explanations": {"天空": "“天空”指头顶广阔的空间，是本词的正确答案。", "天宫": "kōng 与 gōng 声母不同（k/g），天宫指神话中天上的宫殿或中国空间站，不是头顶的空间。", "天坑": "kōng 与 kēng 韵母不同（-ong/-eng），天坑指地质上陷落形成的大洞，不是天空。", "挑空": "tiān 与 tiāo 韵母不同（-an/-ao），挑空指建筑中上下贯通的空间，不指天空。"}, "sentence_index": null, "correct_answer": "天空"}, "level_3": {"options": [{"text": "天空", "is_correct": true, "explanation": "“天空”是飞机飞上去的地方，指头顶广阔的空间。"}, {"text": "地面", "is_correct": false, "explanation": "语义：句中已说“离开地面”，再说“飞上地面”自相矛盾。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：“飞上”指向高处，大海是平面，应说“飞向大海”。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，飞机不能飞上太阳，与句意不符。"}], "explanations": {"天空": "“天空”是飞机飞上去的地方，指头顶广阔的空间。", "地面": "语义：句中已说“离开地面”，再说“飞上地面”自相矛盾。", "大海": "搭配：“飞上”指向高处，大海是平面，应说“飞向大海”。", "太阳": "语义：太阳是天体，飞机不能飞上太阳，与句意不符。"}, "sentence_index": 0, "correct_answer": "天空"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只天空很蓝，鸟儿在里面飞。", "explanation": "量词错误：天空的量词是“片”，“只”用于动物，应说“这片天空”。"}, {"text": "这朵天空很美，云儿在里面飘。", "explanation": "量词错误：“朵”用于花、云等，不用来计量天空，应说“这片天空”。"}, {"text": "这里的天空很新鲜，我们多呼吸一下吧。", "explanation": "这里应该用〈空气〉。新鲜形容空气，天空是头顶的空间，不说天空新鲜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12099, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": true, "explanation": "“天空”是雨后变得干净的地方，指头顶广阔的空间。"}, {"text": "泥土", "is_correct": false, "explanation": "语义：泥土本身很脏，与“特别干净”相矛盾。"}, {"text": "雷声", "is_correct": false, "explanation": "搭配：“干净”不用来形容雷声，句中说的是天空的状态。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾本身就脏，与“特别干净”相矛盾。"}], "explanations": {"天空": "“天空”是雨后变得干净的地方，指头顶广阔的空间。", "泥土": "语义：泥土本身很脏，与“特别干净”相矛盾。", "雷声": "搭配：“干净”不用来形容雷声，句中说的是天空的状态。", "垃圾": "语义：垃圾本身就脏，与“特别干净”相矛盾。"}, "sentence_index": 6, "correct_answer": "天空"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天天空很甜，我们去爬山吧。", "explanation": "甜形容味道，天空没有味道，不能说天空很甜；形容天气好坏应说〈天气〉。"}, {"text": "一颗天空很亮，大家都抬头看着。", "explanation": "量词错误：“颗”用于星星、珠子等小圆的东西，天空要用“片”，不说“一颗天空”。"}, {"text": "雨后的天空很新鲜，我们去外面呼吸吧。", "explanation": "这里应该用〈空气〉。新鲜形容空气，天空是头顶的空间，不说天空新鲜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12099, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这朵天空很蓝。", "corrected_sentence": "这片天空很蓝。", "error_description": "量词错误：天空应用量词“片”，“朵”用于花、云等，应说“这片天空”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12099, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这朵天空中挂着一个大月亮。", "corrected_sentence": "这片天空中挂着一个大月亮。", "error_description": "量词错误：天空应用量词“片”，“朵”用于花、云等，应说“这片天空”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12101, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变快", "is_correct": true, "explanation": "正确：“变快”与“变慢”相对，指速度提高，构成反义关系。"}, {"text": "保持", "is_correct": false, "explanation": "与“变慢”不构成反义，“保持”指维持原状。"}, {"text": "停顿", "is_correct": false, "explanation": "与“变慢”不构成反义，“停顿”指暂时中断，不是速度的相对变化。"}, {"text": "持平", "is_correct": false, "explanation": "与“变慢”不构成反义，“持平”指保持相等或平稳，与速度变化无关。"}], "correct_answer": "变快", "explanations": {"变快": "正确：“变快”与“变慢”相对，指速度提高，构成反义关系。", "保持": "与“变慢”不构成反义，“保持”指维持原状。", "停顿": "与“变慢”不构成反义，“停顿”指暂时中断，不是速度的相对变化。", "持平": "与“变慢”不构成反义，“持平”指保持相等或平稳，与速度变化无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12101, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变快", "is_correct": true, "explanation": "正确：“变快”与“变慢”相对，指速度提高，构成反义关系。"}, {"text": "持续", "is_correct": false, "explanation": "与“变慢”不构成反义，“持续”指延续不断，与速度变化的方向无关。"}, {"text": "固定", "is_correct": false, "explanation": "与“变慢”不构成反义，“固定”指不变动，不是速度的相对变化。"}, {"text": "坚持", "is_correct": false, "explanation": "与“变慢”不构成反义，“坚持”指不放弃，与速度变化无关。"}], "correct_answer": "变快", "explanations": {"变快": "正确：“变快”与“变慢”相对，指速度提高，构成反义关系。", "持续": "与“变慢”不构成反义，“持续”指延续不断，与速度变化的方向无关。", "固定": "与“变慢”不构成反义，“固定”指不变动，不是速度的相对变化。", "坚持": "与“变慢”不构成反义，“坚持”指不放弃，与速度变化无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12101, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指速度或效率降低，变得缓慢。", "primary_collocate": null, "pronunciation": "biàn màn", "ipa": "pi̯ɛn˥˩ man˥˩", "syllable_count": 2, "sentences": [{"text": "如果推力不够，飞机就会变慢，甚至飞不动。", "target_word": "变慢", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "如果太冷或太干，分解就会变慢。", "target_word": "变慢", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "电脑里文件太多，运行速度就会变慢。", "target_word": "变慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上用网的人多，网速变慢了。", "target_word": "变慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气太冷，水果成熟的速度会变慢。", "target_word": "变慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我太累了，做事的速度变慢了。", "target_word": "变慢", "complexity_tier": "T3", "furigana": "wǒ tài lèi le, zuò shì de sù dù biàn màn le.", "sentence_source": "generated"}, {"text": "手机用了三年，反应变慢了。", "target_word": "变慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下大雨时，路上的车速会变慢。", "target_word": "变慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人老了，身体的新陈代谢会变慢。", "target_word": "变慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机器没有油，转动的速度会变慢。", "target_word": "变慢", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "变慢了", "label": "体标（了）"}, {"form": "变慢过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "运行速度、效率或进程降低而变得缓慢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c22b99d-de53-433a-91c3-3cfd2942df23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12101, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "变慢", "is_correct": true, "explanation": "正确：“变慢”指速度降低，与听到的 biàn màn 读音一致。"}, {"text": "变满", "is_correct": false, "explanation": "mǎn（第三声）与 màn（第四声）声调不同，“变满”指变得充满，意思不同。"}, {"text": "变淡", "is_correct": false, "explanation": "dàn（第四声）与 màn 声调相同，只差声母（d 与 m），“变淡”指颜色或味道变浅，意思不同。"}, {"text": "变烂", "is_correct": false, "explanation": "làn（第四声）与 màn 声调相同，只差声母（l 与 m），“变烂”指变得腐烂。"}], "explanations": {"变慢": "正确：“变慢”指速度降低，与听到的 biàn màn 读音一致。", "变满": "mǎn（第三声）与 màn（第四声）声调不同，“变满”指变得充满，意思不同。", "变淡": "dàn（第四声）与 màn 声调相同，只差声母（d 与 m），“变淡”指颜色或味道变浅，意思不同。", "变烂": "làn（第四声）与 màn 声调相同，只差声母（l 与 m），“变烂”指变得腐烂。"}, "sentence_index": null, "correct_answer": "变慢"}, "level_3": {"options": [{"text": "变慢", "is_correct": true, "explanation": "正确：推力不够时，飞机的速度会降低，“变慢”符合句意。"}, {"text": "变亮", "is_correct": false, "explanation": "搭配：“变亮”多用于光线、颜色，不能用来描述飞机因推力不足的变化。"}, {"text": "变宽", "is_correct": false, "explanation": "体貌：飞机的形状不会因推力不够而变宽，句中说的是运动状态。"}, {"text": "变软", "is_correct": false, "explanation": "搭配：“变软”多用于材料、物体的质地，不能用来形容飞机的速度。"}], "explanations": {"变慢": "正确：推力不够时，飞机的速度会降低，“变慢”符合句意。", "变亮": "搭配：“变亮”多用于光线、颜色，不能用来描述飞机因推力不足的变化。", "变宽": "体貌：飞机的形状不会因推力不够而变宽，句中说的是运动状态。", "变软": "搭配：“变软”多用于材料、物体的质地，不能用来形容飞机的速度。"}, "sentence_index": 0, "correct_answer": "变慢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的电费变慢了不少。", "explanation": "这里应该用〈降低〉。变慢指速度降低，电费减少要说“降低”。"}, {"text": "会议因为领导出差，变慢了一周。", "explanation": "这里应该用〈推迟〉。变慢说的是速度，会议时间往后推要说“推迟”。"}, {"text": "他的成绩变慢了一大截。", "explanation": "这里应该用〈下降〉。变慢指速度降低，成绩降低要说“下降”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12101, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变慢", "is_correct": true, "explanation": "正确：手机用了三年，反应会降低，“变慢了”符合句意。"}, {"text": "变甜", "is_correct": false, "explanation": "搭配：“变甜”用于味道，不能用来描述反应。"}, {"text": "变胖", "is_correct": false, "explanation": "体貌：反应不会变胖，“变胖”只用于人或物的外形。"}, {"text": "变厚", "is_correct": false, "explanation": "语义：反应没有厚薄之分，“变厚”不能描述手机的反应能力。"}], "explanations": {"变慢": "正确：手机用了三年，反应会降低，“变慢了”符合句意。", "变甜": "搭配：“变甜”用于味道，不能用来描述反应。", "变胖": "体貌：反应不会变胖，“变胖”只用于人或物的外形。", "变厚": "语义：反应没有厚薄之分，“变厚”不能描述手机的反应能力。"}, "sentence_index": 6, "correct_answer": "变慢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的处境变慢了，大家都替他着急。", "explanation": "这里应该用〈变差〉。变慢指速度降低，处境变坏要说“变差”。"}, {"text": "他的心情变慢了，大家都很担心。", "explanation": "这里应该用〈低落〉。变慢指速度降低，心情变消沉要说“低落”。"}, {"text": "他心里的压力变慢了。", "explanation": "这里应该用〈减轻〉。变慢是速度降低，压力变小要说“减轻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12101, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下雪以后，公交车的速度变慢着。", "corrected_sentence": "下雪以后，公交车的速度变慢了。", "error_description": "错误：“变慢着”，“着”表示状态的持续，而“变慢”已是完成的变化，应用表示变化已发生的“了”。正确：“变慢了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12101, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨停以后，路上的车速很变慢了。", "corrected_sentence": "雨停以后，路上的车速变慢了。", "error_description": "错误：“很变慢”，“很”用于修饰形容词或状态，不能修饰“变”这类表示变化的动词，应删去“很”。正确：“变慢了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12102, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗糙", "is_correct": true, "explanation": "粗糙与光滑意思相反，指表面凹凸不平、有毛刺。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软说质地软，与表面平不平无关，不是反义词。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮说光线或颜色亮，与表面光滑没有相反关系。"}, {"text": "干燥", "is_correct": false, "explanation": "干燥说不潮湿，与表面光滑没有相反关系。"}], "correct_answer": "粗糙", "explanations": {"粗糙": "粗糙与光滑意思相反，指表面凹凸不平、有毛刺。", "柔软": "柔软说质地软，与表面平不平无关，不是反义词。", "明亮": "明亮说光线或颜色亮，与表面光滑没有相反关系。", "干燥": "干燥说不潮湿，与表面光滑没有相反关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12102, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗糙", "is_correct": true, "explanation": "粗糙与光滑意思相反，指表面凹凸不平、有毛刺。"}, {"text": "陡峭", "is_correct": false, "explanation": "陡峭说坡面很斜，与表面光滑没有相反关系。"}, {"text": "厚重", "is_correct": false, "explanation": "厚重说分量大或内容深，不是光滑的反义词。"}, {"text": "迟钝", "is_correct": false, "explanation": "迟钝说反应慢，与表面光滑无关。"}], "correct_answer": "粗糙", "explanations": {"粗糙": "粗糙与光滑意思相反，指表面凹凸不平、有毛刺。", "陡峭": "陡峭说坡面很斜，与表面光滑没有相反关系。", "厚重": "厚重说分量大或内容深，不是光滑的反义词。", "迟钝": "迟钝说反应慢，与表面光滑无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12102, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容物体表面平整，没有凸起或毛刺，触感顺滑。", "primary_collocate": null, "pronunciation": "guāng huá", "ipa": "kwɑŋ˥ xwa˧˥", "syllable_count": 2, "sentences": [{"text": "所以飞机的形状要做得光滑，这样空气才能顺利流过，减少阻力。", "target_word": "光滑", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这块石头很光滑。", "target_word": "光滑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子的表面磨得很光滑。", "target_word": "光滑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的皮肤又白又光滑。", "target_word": "光滑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冰面光滑，走路要小心。", "target_word": "光滑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小河里的石头都很光滑。", "target_word": "光滑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "汽车外壳很光滑，水一流就掉。", "target_word": "光滑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张纸摸起来很光滑。", "target_word": "光滑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这块木板很光滑，手摸上去不会扎刺。", "target_word": "光滑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把盘子洗得又干净又光滑。", "target_word": "光滑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "光滑的", "label": "定语形式"}, {"form": "光滑了", "label": "体标（了）"}], "register": "中性", "sense_fingerprint": "物体表面平整没有凸起或毛刺，触感顺滑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d46aa3-eeb1-4c0a-b496-7cdabfc5bb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12102, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "光滑", "is_correct": true, "explanation": "光滑指表面平整、没有凸起，空气才能顺利流过。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：粗糙的表面有凸起，会增加阻力，与“减少阻力”相反。"}, {"text": "凹凸", "is_correct": false, "explanation": "语义：凹凸的表面会增加气流阻力，与“减少阻力”的目的相反。"}, {"text": "复杂", "is_correct": false, "explanation": "语义：形状复杂会阻碍气流，与“顺利流过”相反。"}], "explanations": {"光滑": "光滑指表面平整、没有凸起，空气才能顺利流过。", "粗糙": "语义：粗糙的表面有凸起，会增加阻力，与“减少阻力”相反。", "凹凸": "语义：凹凸的表面会增加气流阻力，与“减少阻力”的目的相反。", "复杂": "语义：形状复杂会阻碍气流，与“顺利流过”相反。"}, "sentence_index": 0, "correct_answer": "光滑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话很光滑，总能把难题绕过去。", "explanation": "这里应该用〈圆滑〉。光滑只说物体表面平，形容人说话巧妙、处事灵活要用圆滑。"}, {"text": "夜里的月光很光滑，照得满地都是。", "explanation": "这里应该用〈明亮〉。光滑形容物体表面，不用来形容光线，发亮的光要说明亮。"}, {"text": "他的前途很光滑，将来一定很好。", "explanation": "这里应该用〈光明〉。光滑形容物体表面平，不用来形容前途，前途美好要用光明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12102, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光滑", "is_correct": true, "explanation": "光滑指表面平，水才会一流就掉。"}, {"text": "粘稠", "is_correct": false, "explanation": "搭配：“粘稠”说液体的状态，不用来形容车壳表面。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：外壳潮湿，水会留在表面，与“水一流就掉”矛盾。"}, {"text": "毛糙", "is_correct": false, "explanation": "语义：表面毛糙会挂住水，与“水一流就掉”矛盾。"}], "explanations": {"光滑": "光滑指表面平，水才会一流就掉。", "粘稠": "搭配：“粘稠”说液体的状态，不用来形容车壳表面。", "潮湿": "语义：外壳潮湿，水会留在表面，与“水一流就掉”矛盾。", "毛糙": "语义：表面毛糙会挂住水，与“水一流就掉”矛盾。"}, "sentence_index": 6, "correct_answer": "光滑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这排座位摆得很光滑，一点都不乱。", "explanation": "这里应该用〈整齐〉。光滑形容物体表面平，不用来形容摆放的样子，排列有序要用整齐。"}, {"text": "这个道理讲得很光滑，大家一下就明白了。", "explanation": "这里应该用〈透彻〉。光滑形容物体表面平，不用来形容说理；道理讲得清楚透彻、一听就懂要用透彻。"}, {"text": "他的房间收拾得很光滑，一尘不染。", "explanation": "这里应该用〈整洁〉。光滑说物体表面平，房间收拾得干净利落要用整洁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把玻璃擦很光滑。", "corrected_sentence": "她把玻璃擦得很光滑。", "error_description": "补语要用“得”连接，“擦很光滑”漏了“得”，正确是“擦得很光滑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她摸到了光滑地桌面。", "corrected_sentence": "她摸到了光滑的桌面。", "error_description": "修饰名词要用“的”，不用“地”。正确是“光滑的桌面”，“地”用来修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12103, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "艰难", "is_correct": true, "explanation": "艰难与顺利意思相反，指事情进行时遇到阻碍、十分费力。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速说速度快，不表示有没有障碍，不是顺利的反义词。"}, {"text": "始终", "is_correct": false, "explanation": "始终说持续不变，与顺利的意思无关。"}, {"text": "悄悄", "is_correct": false, "explanation": "悄悄说不让别人知道，与顺利没有相反关系。"}], "correct_answer": "艰难", "explanations": {"艰难": "艰难与顺利意思相反，指事情进行时遇到阻碍、十分费力。", "迅速": "迅速说速度快，不表示有没有障碍，不是顺利的反义词。", "始终": "始终说持续不变，与顺利的意思无关。", "悄悄": "悄悄说不让别人知道，与顺利没有相反关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12103, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "艰难", "is_correct": true, "explanation": "艰难与顺利意思相反，指事情进行时遇到阻碍、十分费力。"}, {"text": "偶然", "is_correct": false, "explanation": "偶然指出于意外，与顺利没有相反关系。"}, {"text": "渐渐", "is_correct": false, "explanation": "渐渐指逐步变化，与顺利没有相反关系。"}, {"text": "忽然", "is_correct": false, "explanation": "忽然指突然发生，与顺利没有相反关系。"}], "correct_answer": "艰难", "explanations": {"艰难": "艰难与顺利意思相反，指事情进行时遇到阻碍、十分费力。", "偶然": "偶然指出于意外，与顺利没有相反关系。", "渐渐": "渐渐指逐步变化，与顺利没有相反关系。", "忽然": "忽然指突然发生，与顺利没有相反关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12103, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指事情进行得没有障碍或困难。", "primary_collocate": null, "pronunciation": "shùn lì", "ipa": "ʂu̯ən˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "所以飞机的形状要做得光滑，这样空气才能顺利流过，减少阻力。", "target_word": "顺利", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "我们的飞机顺利到达了北京。", "target_word": "顺利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他顺利通过了驾驶考试。", "target_word": "顺利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水顺利流过管子，没有堵住。", "target_word": "顺利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车顺利穿过了长长的山洞。", "target_word": "顺利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手术顺利完成，医生松了一口气。", "target_word": "顺利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他顺利找到了新工作，很高兴。", "target_word": "顺利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船顺利进了港口，大家都下船了。", "target_word": "顺利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子顺利出生了，全家都很开心。", "target_word": "顺利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们顺利把货物送到了客人家。", "target_word": "顺利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "顺顺利利", "label": "重叠"}], "register": "中性", "sense_fingerprint": "做事或动作进行时没有阻碍，如顺利完成、顺利到达", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d46aa3-eeb1-4c0a-b496-7cdabfc5bb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12103, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "顺利", "is_correct": true, "explanation": "顺利指空气流动没有阻碍，符合“减少阻力”的要求。"}, {"text": "勉强", "is_correct": false, "explanation": "语义：“勉强”表示费力才做到，与“减少阻力”的目的相反。"}, {"text": "反复", "is_correct": false, "explanation": "搭配：“反复”说多次重复，不能修饰一次流过的动作。"}, {"text": "猛烈", "is_correct": false, "explanation": "语义：“猛烈”说力度大，与“减少阻力”的要求不符。"}], "explanations": {"顺利": "顺利指空气流动没有阻碍，符合“减少阻力”的要求。", "勉强": "语义：“勉强”表示费力才做到，与“减少阻力”的目的相反。", "反复": "搭配：“反复”说多次重复，不能修饰一次流过的动作。", "猛烈": "语义：“猛烈”说力度大，与“减少阻力”的要求不符。"}, "sentence_index": 0, "correct_answer": "顺利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条马路很顺利，车子开得很快。", "explanation": "这里应该用〈顺畅〉。顺利说事情的进展没有阻碍，道路、交通、水流要用顺畅。"}, {"text": "这个孩子很顺利，什么事都听父母的。", "explanation": "这里应该用〈顺从〉。顺利说事情进行，不用来形容人对别人的态度，听从别人要用顺从。"}, {"text": "他的心情很顺利，今天特别开心。", "explanation": "这里应该用〈顺心〉。顺利只用于事情进展，形容心情、感受要用顺心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12103, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "顺利", "is_correct": true, "explanation": "顺利指找工作的过程没有障碍，与“很高兴”一致。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒劳，与“很高兴”矛盾。"}, {"text": "再三", "is_correct": false, "explanation": "搭配：“再三”说多次重复，不能与一次性的“找到”搭配。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”说持续，不与“找到”这种一次性结果搭配。"}], "explanations": {"顺利": "顺利指找工作的过程没有障碍，与“很高兴”一致。", "白白": "语义：“白白”表示徒劳，与“很高兴”矛盾。", "再三": "搭配：“再三”说多次重复，不能与一次性的“找到”搭配。", "一直": "搭配：“一直”说持续，不与“找到”这种一次性结果搭配。"}, "sentence_index": 6, "correct_answer": "顺利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把剪刀用起来很顺利，裁布很省力。", "explanation": "这里应该用〈顺手〉。顺利说事情进行没有障碍，形容工具用起来好用要用顺手。"}, {"text": "这几天他的胃口很顺利，每顿都吃得很多。", "explanation": "这里应该用〈旺盛〉。顺利说事情进展，不用来形容胃口，食欲好要用旺盛。"}, {"text": "这件衣服穿起来很顺利，腰身也正好。", "explanation": "这里应该用〈合身〉。顺利说事情进展，形容衣服尺寸合适要用合身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12103, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次搬家进行很顺利。", "corrected_sentence": "这次搬家进行得很顺利。", "error_description": "补语要用“得”连接，“进行很顺利”漏了“得”，正确是“进行得很顺利”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12103, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批货顺利得运到了港口。", "corrected_sentence": "这批货顺利地运到了港口。", "error_description": "修饰动词要用“地”，“得”用于引出补语。正确是“顺利地运到”，“顺利得运到”用错了“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
