INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12104, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12104, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "引擎是一种将某种能量（如燃料、电力）转化为机械动力的装置，通常用于驱动车辆、机器或设备。", "primary_collocate": null, "pronunciation": "yǐn qíng", "ipa": "in˨˩˦ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "引擎的作用就是产生向前的推力，帮助飞机克服阻力。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这辆车的引擎声音很大。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架飞机有四台引擎。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机打开车盖，检查引擎。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天车的引擎不容易发动。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "引擎坏了，船停在海上不动了。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车引擎需要用汽油才能工作。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台引擎很新，跑得又快又稳。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他修好了摩托车的引擎。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火箭的引擎一启动，就冒出大火。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "引擎盖", "label": "复合"}], "register": "中性", "sense_fingerprint": "把能量变成动力的机械装置，如汽车、飞机的引擎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d46aa3-eeb1-4c0a-b496-7cdabfc5bb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12104, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引擎", "is_correct": true, "explanation": "引擎是产生动力的装置，与“产生向前的推力”的作用相符。"}, {"text": "方向盘", "is_correct": false, "explanation": "语义：方向盘只用来控制车辆的方向，不产生推力，不能说它的作用是产生向前的推力。"}, {"text": "油箱", "is_correct": false, "explanation": "语义：油箱只用来储存燃料，本身不产生推力，句子所说的作用不符。"}, {"text": "座椅", "is_correct": false, "explanation": "搭配：“产生推力”的主语必须是动力装置，座椅没有这样的功能，不能与之搭配。"}], "explanations": {"引擎": "引擎是产生动力的装置，与“产生向前的推力”的作用相符。", "方向盘": "语义：方向盘只用来控制车辆的方向，不产生推力，不能说它的作用是产生向前的推力。", "油箱": "语义：油箱只用来储存燃料，本身不产生推力，句子所说的作用不符。", "座椅": "搭配：“产生推力”的主语必须是动力装置，座椅没有这样的功能，不能与之搭配。"}, "sentence_index": 0, "correct_answer": "引擎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们公司买了一辆引擎。", "explanation": "这里应该用〈台〉。引擎的量词是“台”，“辆”用于汽车、自行车等车辆，不能用来数引擎。"}, {"text": "这把雨伞的引擎很结实。", "explanation": "这里不能用〈引擎〉。雨伞没有动力装置，不能说它有引擎。"}, {"text": "这张桌子的引擎很结实。", "explanation": "这里不能用〈引擎〉。桌子没有动力装置，不能说它有引擎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12104, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引擎", "is_correct": true, "explanation": "引擎靠燃料工作，与句中的“汽油”和“工作”相符。"}, {"text": "轮胎", "is_correct": false, "explanation": "语义：轮胎不靠汽油工作，句中的燃料与它无关。"}, {"text": "车灯", "is_correct": false, "explanation": "语义：车灯多靠电力工作，不需要汽油，与句意不符。"}, {"text": "后视镜", "is_correct": false, "explanation": "搭配：后视镜不说“工作”，与“需要用汽油才能工作”不搭配。"}], "explanations": {"引擎": "引擎靠燃料工作，与句中的“汽油”和“工作”相符。", "轮胎": "语义：轮胎不靠汽油工作，句中的燃料与它无关。", "车灯": "语义：车灯多靠电力工作，不需要汽油，与句意不符。", "后视镜": "搭配：后视镜不说“工作”，与“需要用汽油才能工作”不搭配。"}, "sentence_index": 6, "correct_answer": "引擎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把菜刀的引擎很锋利。", "explanation": "这里的〈引擎〉指汽车、飞机、船等的动力装置，菜刀是手工器具，没有这类部件，不能这样说。"}, {"text": "这本字典的引擎有五百多页。", "explanation": "这里的〈引擎〉指机械的动力装置，字典是书，没有这类部件，不能说它有几页。"}, {"text": "我的旧手机换了一台新引擎。", "explanation": "这里的〈引擎〉指车辆、飞机等的动力装置，手机没有这个部件，不能说给它换引擎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆引擎需要定期保养。", "corrected_sentence": "这台引擎需要定期保养。", "error_description": "量词错误：引擎的量词是“台”，“辆”用于车辆。正确说法是“这台引擎”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于把引擎修了好。", "corrected_sentence": "他终于把引擎修好了。", "error_description": "补语错误：结果补语“好”应紧跟动词，应说“修好”，不能说“修了好”。正确说法是“把引擎修好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12106, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
