INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12106, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "向前推动物体或事物前进的力量。", "primary_collocate": null, "pronunciation": "tuī lì", "ipa": "tʰu̯eɪ˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "引擎的作用就是产生向前的推力，帮助飞机克服阻力。", "target_word": "推力", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "飞行时，工程师要让升力、阻力、推力和重力这四个力保持平衡。", "target_word": "推力", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "如果推力不够，飞机就会变慢，甚至飞不动。", "target_word": "推力", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "火箭需要很大的推力才能飞上天空。", "target_word": "推力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台发动机的推力很大。", "target_word": "推力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船的推力来自后面的螺旋桨。", "target_word": "推力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "发动机停了，飞机没有推力了。", "target_word": "推力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师正在测试新火箭的推力。", "target_word": "推力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机起飞时，发动机的推力要特别大。", "target_word": "推力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "推力越大，火箭飞得越快。", "target_word": "推力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "股", "label": "量词"}, {"form": "反推力", "label": "复合"}], "register": "中性", "sense_fingerprint": "发动机等产生的向前推动物体前进的力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffb67340-e1c4-4776-99da-c6f147023945') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12106, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "推力", "is_correct": true, "explanation": "正确答案：推力（tuī lì），指推动物体前进的力。"}, {"text": "推理", "is_correct": false, "explanation": "推理（tuī lǐ）与推力的第二音节声调不同（第三声与第四声），意思是根据已知推断结论。"}, {"text": "对立", "is_correct": false, "explanation": "对立（duì lì）与推力的声母不同（d 与 t），声调也不同（第四声），意思是互相抵触。"}, {"text": "脱力", "is_correct": false, "explanation": "脱力（tuō lì）与推力的韵母不同（uo 与 ui），第一音节声调相同，意思是失去力气。"}, {"text": "体力", "is_correct": false, "explanation": "体力（tǐ lì）与推力的韵母不同（ǐ 与 uī），声调也不同（第三声），意思是身体的力气。"}], "explanations": {"推力": "正确答案：推力（tuī lì），指推动物体前进的力。", "推理": "推理（tuī lǐ）与推力的第二音节声调不同（第三声与第四声），意思是根据已知推断结论。", "对立": "对立（duì lì）与推力的声母不同（d 与 t），声调也不同（第四声），意思是互相抵触。", "脱力": "脱力（tuō lì）与推力的韵母不同（uo 与 ui），第一音节声调相同，意思是失去力气。", "体力": "体力（tǐ lì）与推力的韵母不同（ǐ 与 uī），声调也不同（第三声），意思是身体的力气。"}, "sentence_index": null, "correct_answer": "推力"}, "level_3": {"options": [{"text": "推力", "is_correct": true, "explanation": "正确：推力是引擎产生的向前推动飞机的力，与“产生向前的”相符。"}, {"text": "阻力", "is_correct": false, "explanation": "语义：阻力是阻碍前进的力，与“向前”的作用相反，且与后文“克服阻力”重复。"}, {"text": "重力", "is_correct": false, "explanation": "语义：重力是地球对物体的吸引力，方向向下，不能说“产生向前的重力”。"}, {"text": "体力", "is_correct": false, "explanation": "搭配：“体力”指人或动物的力气，不用来说引擎产生力。"}], "explanations": {"推力": "正确：推力是引擎产生的向前推动飞机的力，与“产生向前的”相符。", "阻力": "语义：阻力是阻碍前进的力，与“向前”的作用相反，且与后文“克服阻力”重复。", "重力": "语义：重力是地球对物体的吸引力，方向向下，不能说“产生向前的重力”。", "体力": "搭配：“体力”指人或动物的力气，不用来说引擎产生力。"}, "sentence_index": 0, "correct_answer": "推力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的推力很强，能解决很难的数学问题。", "explanation": "这里应该用〈能力〉。推力指推动物体前进的力，不能用来说人解决问题的本领。"}, {"text": "这根绳子的推力很大，能把车拉过来。", "explanation": "这里应该用〈拉力〉。推力指向前推动物体的力，把车拉过来用的是拉力，不能说推力。"}, {"text": "空气的推力很大，车跑不快。", "explanation": "这里应该用〈阻力〉。推力指推动物体前进的力，阻碍车前进的是阻力，不能说推力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12106, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "推力", "is_correct": true, "explanation": "正确答案：推力（tuī lì），指推动物体前进的力。"}, {"text": "腿力", "is_correct": false, "explanation": "腿力（tuǐ lì）与推力的第一音节声调不同（第三声与第一声），意思是腿的力气。"}, {"text": "拖力", "is_correct": false, "explanation": "拖力（tuō lì）与推力的韵母不同（uo 与 ui），第一音节声调相同，意思是拖拉时的拉力。"}, {"text": "推理", "is_correct": false, "explanation": "推理（tuī lǐ）与推力的第二音节声调不同（第三声与第四声），意思是根据已知推断结论。"}], "explanations": {"推力": "正确答案：推力（tuī lì），指推动物体前进的力。", "腿力": "腿力（tuǐ lì）与推力的第一音节声调不同（第三声与第一声），意思是腿的力气。", "拖力": "拖力（tuō lì）与推力的韵母不同（uo 与 ui），第一音节声调相同，意思是拖拉时的拉力。", "推理": "推理（tuī lǐ）与推力的第二音节声调不同（第三声与第四声），意思是根据已知推断结论。"}, "sentence_index": null, "correct_answer": "推力"}, "level_3": {"options": [{"text": "推力", "is_correct": true, "explanation": "正确：发动机停了，飞机就没有推动它前进的力，与句意相符。"}, {"text": "重量", "is_correct": false, "explanation": "语义：飞机的重量不会因发动机停了而消失，“没有重量了”说不通。"}, {"text": "温度", "is_correct": false, "explanation": "语义：物体都有温度，“没有温度了”说不通，与发动机的状态无关。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”指人或动物的重量，不用来说飞机。"}], "explanations": {"推力": "正确：发动机停了，飞机就没有推动它前进的力，与句意相符。", "重量": "语义：飞机的重量不会因发动机停了而消失，“没有重量了”说不通。", "温度": "语义：物体都有温度，“没有温度了”说不通，与发动机的状态无关。", "体重": "搭配：“体重”指人或动物的重量，不用来说飞机。"}, "sentence_index": 6, "correct_answer": "推力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的推力越来越快，一分钟就跑了一公里。", "explanation": "这里应该用〈速度〉。“越来越快”说的是速度，推力只说大小，不能说快慢。"}, {"text": "月亮对海水有推力，所以海水会涨落。", "explanation": "这里应该用〈引力〉。推力指向前推动物体的力，月亮吸引海水使其涨落的是引力，不能说推力。"}, {"text": "老师对学生很有推力，大家都很喜欢他。", "explanation": "这里应该用〈耐心〉。推力指推动物体的力，不能用来形容人的品质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台发动机能产生一台很大的推力。", "corrected_sentence": "这台发动机能产生一股很大的推力。", "error_description": "量词错误：推力应用量词“股”，不能用“台”（“台”用于机器等）。正确说法是“一股很大的推力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新火箭的推力比旧的大的多。", "corrected_sentence": "新火箭的推力比旧的大得多。", "error_description": "补语标记错误：程度补语应用“得”连接，不能用“的”。正确说法是“比旧的大得多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
