INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12109, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物体由于地球的吸引而受到的向下的力。", "primary_collocate": null, "pronunciation": "zhòng lì", "ipa": "ʈʂʊŋ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "飞行时，工程师要让升力、阻力、推力和重力这四个力保持平衡。", "target_word": "重力", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "苹果落下来，是因为有重力。", "target_word": "重力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在月球上，重力比地球上小。", "target_word": "重力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太空里几乎没有重力，东西会飘起来。", "target_word": "重力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "重力把所有东西都往下拉。", "target_word": "重力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跳起来以后，重力会让人回到地面。", "target_word": "重力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水往低处流，是重力的作用。", "target_word": "重力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宇航员在空间站里感觉不到重力。", "target_word": "重力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "重力让雨水落到地上。", "target_word": "重力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地球的重力比月球的大得多。", "target_word": "重力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "重力场", "label": "复合"}, {"form": "重力加速度", "label": "复合"}], "register": "中性", "sense_fingerprint": "地球吸引物体而产生的向下的力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffb67340-e1c4-4776-99da-c6f147023945') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12109, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "重力", "is_correct": true, "explanation": "正确：指地球对物体的吸引力。"}, {"text": "中立", "is_correct": false, "explanation": "zhōng（第一声）与 zhòng（第四声）声调不同，意思是中立，不偏向任何一方。"}, {"text": "正例", "is_correct": false, "explanation": "zhèng 与 zhòng 韵母不同（eng 与 ong），意思是正面的例子。"}, {"text": "正立", "is_correct": false, "explanation": "zhèng 与 zhòng 韵母不同（eng 与 ong），意思是端正地竖立。"}], "explanations": {"重力": "正确：指地球对物体的吸引力。", "中立": "zhōng（第一声）与 zhòng（第四声）声调不同，意思是中立，不偏向任何一方。", "正例": "zhèng 与 zhòng 韵母不同（eng 与 ong），意思是正面的例子。", "正立": "zhèng 与 zhòng 韵母不同（eng 与 ong），意思是端正地竖立。"}, "sentence_index": null, "correct_answer": "重力"}, "level_3": {"options": [{"text": "重力", "is_correct": true, "explanation": "正确：重力是地球吸引物体产生的向下的力，与升力、阻力、推力并列，符合“这四个力”。"}, {"text": "速度", "is_correct": false, "explanation": "语义：速度是运动的快慢，不是力，不能和升力、阻力、推力并列为“这四个力”。"}, {"text": "能量", "is_correct": false, "explanation": "语义：能量不是力，不能算作“这四个力”之一。"}, {"text": "质量", "is_correct": false, "explanation": "语义：质量是物体所含物质的多少，不是力，不能算作“这四个力”之一。"}], "explanations": {"重力": "正确：重力是地球吸引物体产生的向下的力，与升力、阻力、推力并列，符合“这四个力”。", "速度": "语义：速度是运动的快慢，不是力，不能和升力、阻力、推力并列为“这四个力”。", "能量": "语义：能量不是力，不能算作“这四个力”之一。", "质量": "语义：质量是物体所含物质的多少，不是力，不能算作“这四个力”之一。"}, "sentence_index": 0, "correct_answer": "重力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这箱子的重力有二十公斤。", "explanation": "这里应该用〈重量〉。重力是地球吸引物体的力，单位是牛顿；说东西有几公斤重，要用重量。"}, {"text": "这块磁铁的重力很强，能吸住铁钉。", "explanation": "这里应该用〈磁力〉。重力只指地球对物体的吸引，磁铁吸住铁钉要用磁力。"}, {"text": "逆风飞行时，风对飞机的重力很大，飞机很难前进。", "explanation": "这里应该用〈阻力〉。阻力是阻碍物体运动的力，风阻碍飞机前进要说阻力；重力只指地球对物体的吸引。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12109, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重力", "is_correct": true, "explanation": "正确：水往低处流是地球吸引的结果，即重力的作用。"}, {"text": "磁力", "is_correct": false, "explanation": "语义：磁力只吸引铁等磁性物质，不能让水往低处流。"}, {"text": "方法", "is_correct": false, "explanation": "搭配：“……的作用”前面要是能产生效果的力或因素，“方法”不能这样用来解释水流。"}, {"text": "浮力", "is_correct": false, "explanation": "语义：浮力是向上的力，不能用来解释水往低处流。"}], "explanations": {"重力": "正确：水往低处流是地球吸引的结果，即重力的作用。", "磁力": "语义：磁力只吸引铁等磁性物质，不能让水往低处流。", "方法": "搭配：“……的作用”前面要是能产生效果的力或因素，“方法”不能这样用来解释水流。", "浮力": "语义：浮力是向上的力，不能用来解释水往低处流。"}, "sentence_index": 6, "correct_answer": "重力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个人的重力在肚子附近，所以他很难站稳。", "explanation": "这里应该用〈重心〉。重心是物体重量集中的位置，重力是一种力，不能说它在哪个部位。"}, {"text": "气球里的重力很大，把它撑破了。", "explanation": "这里应该用〈压力〉。气球内部的气体挤压气球壁，是压力，不是重力。"}, {"text": "鞋底的重力很大，所以不容易滑倒。", "explanation": "这里应该用〈摩擦力〉。鞋底防滑靠的是与地面之间的摩擦力，重力不是这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12109, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "石头松手以后，会因为一只重力落下来。", "corrected_sentence": "石头松手以后，会因为重力落下来。", "error_description": "量词错误：“重力”是抽象的力，不能用量词“只”（“只”多用于动物、手等）。应去掉“一只”，直接说“因为重力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12109, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "月球的重力比地球的小的多。", "corrected_sentence": "月球的重力比地球的小得多。", "error_description": "补语标记错误：程度补语应用“得”连接，不能用“的”。正确说法是“比地球的小得多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
