INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12110, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "维持稳定，不倾斜或不失去控制。", "primary_collocate": null, "pronunciation": "bǎo chí píng héng", "ipa": "pɑʊ̯˨˩ ʈʂʰɻ̩˧˥ pʰiŋ˧˥ xɤŋ˧˥", "syllable_count": 4, "sentences": [{"text": "飞行时，工程师要让升力、阻力、推力和重力这四个力保持平衡。", "target_word": "保持平衡", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "工作和生活要保持平衡，身体才会好。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生态系统里，动物和植物要保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每月的收入和花费总是保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天平两边一样重，所以能保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭要荤素搭配，让营养保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家要让经济和环境保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习和休息保持平衡，成绩才会提高。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船上的货放得不均匀，船不能保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要让收入和支出保持平衡，不能总是亏钱。", "target_word": "保持平衡", "complexity_tier": "T3", "furigana": "gōngsī yào ràng shōurù hé zhīchū bǎochí píng héng, bù néng zǒngshì kuīqián", "sentence_source": "generated"}], "morphological_forms": [{"form": "保持着平衡", "label": "体标"}], "register": "中性", "sense_fingerprint": "让事物或力量维持稳定、不倾斜、不失控", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffb67340-e1c4-4776-99da-c6f147023945') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12110, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保持平衡", "is_correct": true, "explanation": "正确：要让这四个力稳定、不失衡，应说“保持平衡”。"}, {"text": "分开", "is_correct": false, "explanation": "语义：力分开了就不能保持平衡，与句子的意思相反。"}, {"text": "消失", "is_correct": false, "explanation": "语义：力消失了就谈不上保持平衡，与“让……保持”不符。"}, {"text": "断开", "is_correct": false, "explanation": "搭配：“断开”多用于线、连接，不能用来说“让四个力断开”。"}], "explanations": {"保持平衡": "正确：要让这四个力稳定、不失衡，应说“保持平衡”。", "分开": "语义：力分开了就不能保持平衡，与句子的意思相反。", "消失": "语义：力消失了就谈不上保持平衡，与“让……保持”不符。", "断开": "搭配：“断开”多用于线、连接，不能用来说“让四个力断开”。"}, "sentence_index": 0, "correct_answer": "保持平衡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "开车时，他要和前车保持平衡，不能靠得太近。", "explanation": "这里应该用〈保持距离〉。保持平衡指维持稳定、不倾斜；与前车之间的间隔要说保持距离。"}, {"text": "毕业以后，我们要保持平衡，经常通信。", "explanation": "这里应该用〈保持联系〉。保持平衡指维持稳定、不倾斜；朋友之间的往来要说保持联系。"}, {"text": "图书馆里，大家要保持平衡，不要说话。", "explanation": "这里应该用〈保持安静〉。保持平衡指维持稳定、不倾斜；要求别人不出声要说保持安静。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12110, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保持平衡", "is_correct": true, "explanation": "正确：国家要让经济和环境稳定、不失衡，应说“保持平衡”。"}, {"text": "失衡", "is_correct": false, "explanation": "语义：“失衡”与“保持平衡”意思相反，国家不会让经济和环境失衡。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：国家要让两者保持平衡，就不能去破坏它们，意思正好相反。"}, {"text": "污染", "is_correct": false, "explanation": "语义：国家要让环境保持平衡，不能让环境受到污染，这里意思不符。"}], "explanations": {"保持平衡": "正确：国家要让经济和环境稳定、不失衡，应说“保持平衡”。", "失衡": "语义：“失衡”与“保持平衡”意思相反，国家不会让经济和环境失衡。", "破坏": "语义：国家要让两者保持平衡，就不能去破坏它们，意思正好相反。", "污染": "语义：国家要让环境保持平衡，不能让环境受到污染，这里意思不符。"}, "sentence_index": 6, "correct_answer": "保持平衡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这批文物要保持平衡，不能随便修改。", "explanation": "这里应该用〈保持原样〉。保持平衡指维持稳定、不倾斜；文物维持原来的样子要说保持原样。"}, {"text": "这碗汤要保持平衡，才好喝。", "explanation": "这里应该用〈保持温热〉。保持平衡指维持稳定、不倾斜；汤的温度要说保持温热。"}, {"text": "老师一直保持平衡，耐心地讲解题目。", "explanation": "这里应该用〈保持耐心〉。保持平衡指维持稳定、不倾斜；待人的态度要说保持耐心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个人在船上要保持平衡的，不要乱动。", "corrected_sentence": "这两个人在船上要保持平衡，不要乱动。", "error_description": "多加了“的”：“保持平衡”是动词短语，后面不能直接加“的”，应删去“的”，即“要保持平衡，不要乱动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司一直保持平衡着，所以没有亏钱。", "corrected_sentence": "公司一直保持平衡，所以没有亏钱。", "error_description": "“着”多加在了“平衡”后面：“着”应紧跟动词，“平衡”后面不能加“着”；这句应说“公司一直保持平衡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12111, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "太大", "is_correct": true, "explanation": "太大与太小意思相反，指超过所需，是反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮指外貌好看，与尺寸的大小没有反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "高兴指心情愉快，与尺寸的大小无关。"}, {"text": "湿润", "is_correct": false, "explanation": "湿润指含有适度的水分，与尺寸的大小无关。"}], "correct_answer": "太大", "explanations": {"太大": "太大与太小意思相反，指超过所需，是反义关系。", "漂亮": "漂亮指外貌好看，与尺寸的大小没有反义关系。", "高兴": "高兴指心情愉快，与尺寸的大小无关。", "湿润": "湿润指含有适度的水分，与尺寸的大小无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12111, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过大", "is_correct": true, "explanation": "过大与太小意思相反，指超过需要，是反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "干净指没有污垢，与尺寸的大小无关。"}, {"text": "温暖", "is_correct": false, "explanation": "温暖指温度适宜，与尺寸的大小无关。"}, {"text": "灿烂", "is_correct": false, "explanation": "灿烂指光彩耀眼，与尺寸的大小无关。"}], "correct_answer": "过大", "explanations": {"过大": "过大与太小意思相反，指超过需要，是反义关系。", "干净": "干净指没有污垢，与尺寸的大小无关。", "温暖": "温暖指温度适宜，与尺寸的大小无关。", "灿烂": "灿烂指光彩耀眼，与尺寸的大小无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12111, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示程度低于所需，指事物尺寸、数量、程度等达不到标准或预期。", "primary_collocate": null, "pronunciation": "tài xiǎo", "ipa": "tʰaɪ̯˥˩ ɕi̯ɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "如果升力太大，飞机会上升；如果升力太小，飞机会下降。", "target_word": "太小", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "微生物太小了，眼睛根本看不见，它们生活在土壤和水中。", "target_word": "太小", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "这件衣服太小，我穿不下。", "target_word": "太小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间太小，放不下三张床。", "target_word": "太小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋太小了，孩子穿着脚疼。", "target_word": "太小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "声音太小，后面的人听不见。", "target_word": "太小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个杯子太小，装不下一升水。", "target_word": "太小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他年纪太小，还不能一个人坐车。", "target_word": "太小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "字太小了，爷爷看不清。", "target_word": "太小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子太小，坐不下八个人。", "target_word": "太小", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "太小了", "label": "带语气助词"}, {"form": "不太小", "label": "否定式"}], "register": "中性", "sense_fingerprint": "尺寸、数量或程度小于需要，达不到要求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c22b99d-de53-433a-91c3-3cfd2942df23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12111, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "太小", "is_correct": true, "explanation": "正确：升力不足时飞机才会下降，“太小”表示升力低于所需。"}, {"text": "太大", "is_correct": false, "explanation": "语义：前一分句已说升力太大，后一分句若也用“太大”，飞机会下降的结论与逻辑矛盾。"}, {"text": "太慢", "is_correct": false, "explanation": "搭配：“慢”说的是速度，不能用来形容升力。"}, {"text": "太甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能用来形容升力。"}], "explanations": {"太小": "正确：升力不足时飞机才会下降，“太小”表示升力低于所需。", "太大": "语义：前一分句已说升力太大，后一分句若也用“太大”，飞机会下降的结论与逻辑矛盾。", "太慢": "搭配：“慢”说的是速度，不能用来形容升力。", "太甜": "搭配：“甜”形容味道，不能用来形容升力。"}, "sentence_index": 0, "correct_answer": "太小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子太小，正好能放下三张床。", "explanation": "这里应该用〈够大〉。“太小”表示达不到需要，与“正好能放下”矛盾。"}, {"text": "这件衣服太小，正好合身。", "explanation": "这里应该用〈合身〉。“太小”表示尺寸达不到要求，与“正好合身”矛盾。"}, {"text": "声音太小，大家都听得清楚。", "explanation": "这里应该用〈够响〉。“太小”表示声音达不到需要，与“大家都听得清楚”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12111, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "太小", "is_correct": true, "explanation": "正确：杯子的容量不够，所以装不下一升水。"}, {"text": "太轻", "is_correct": false, "explanation": "语义：杯子的轻重与能否装下一升水无关，这里不能用“太轻”。"}, {"text": "太热", "is_correct": false, "explanation": "搭配：“热”说的是温度，不能用来形容杯子的容量。"}, {"text": "太长", "is_correct": false, "explanation": "体貌：“长”描述外形的长度，与容量的语境不符。"}], "explanations": {"太小": "正确：杯子的容量不够，所以装不下一升水。", "太轻": "语义：杯子的轻重与能否装下一升水无关，这里不能用“太轻”。", "太热": "搭配：“热”说的是温度，不能用来形容杯子的容量。", "太长": "体貌：“长”描述外形的长度，与容量的语境不符。"}, "sentence_index": 6, "correct_answer": "太小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子太小，坐八个人正好。", "explanation": "这里应该用〈宽大〉。“太小”表示达不到需要，与“坐八个人正好”矛盾。"}, {"text": "这间教室太小，学生们坐得特别宽松。", "explanation": "这里应该用〈宽敞〉。“太小”与“坐得特别宽松”矛盾。"}, {"text": "这个包太小，正好装下一台笔记本电脑。", "explanation": "这里应该用〈够大〉。“太小”与“正好装下”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12111, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个箱子太太小，装不下这些书。", "corrected_sentence": "这个箱子太小，装不下这些书。", "error_description": "错误形式是“太太小”，正确形式是“太小”。多写了一个“太”，“太”修饰形容词只能用一次，不能重叠。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12111, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器的零件很太小，装不进去。", "corrected_sentence": "这台机器的零件太小，装不进去。", "error_description": "错误形式是在“太小”前面加“很”，正确形式是“太小”。“太”和“很”都表示程度，不能叠用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
