INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12113, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "表示数量、程度、能力等方面未能达到应有的标准或期望。", "primary_collocate": null, "pronunciation": "bú gòu", "ipa": "pu˧˥ kou̯˥˩", "syllable_count": 2, "sentences": [{"text": "如果推力不够，飞机就会变慢，甚至飞不动。", "target_word": "不够", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这个月的钱不够，我不能买新手机。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的椅子不够，有三个人没座位。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语水平不够，听不懂新闻。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间不够，我们明天再做吧。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜不够吃，再点一个汤吧。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服不够大，我穿着有点小。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的水不够热，我想再烧一下。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你睡得不够多，所以上课没精神。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得不够快，没有拿到第一名。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数量、程度或能力没有达到应有的标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffb67340-e1c4-4776-99da-c6f147023945') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12113, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不够", "is_correct": true, "explanation": "正确答案，表示数量或程度没有达到应有的标准。"}, {"text": "步骤", "is_correct": false, "explanation": "声母不同：zhòu 与 gòu 的声母分别是 zh 和 g，意思是步骤。"}, {"text": "布告", "is_correct": false, "explanation": "韵母不同：gào 与 gòu 的韵母分别是 ao 和 ou，意思是布告。"}, {"text": "补购", "is_correct": false, "explanation": "声调不同：bǔ（第三声）与 bú（第二声）声调不同，意思是补充购买。"}], "explanations": {"不够": "正确答案，表示数量或程度没有达到应有的标准。", "步骤": "声母不同：zhòu 与 gòu 的声母分别是 zh 和 g，意思是步骤。", "布告": "韵母不同：gào 与 gòu 的韵母分别是 ao 和 ou，意思是布告。", "补购": "声调不同：bǔ（第三声）与 bú（第二声）声调不同，意思是补充购买。"}, "sentence_index": null, "correct_answer": "不够"}, "level_3": {"options": [{"text": "不够", "is_correct": true, "explanation": "正确答案。推力达不到要求，所以飞机才会变慢、飞不动。"}, {"text": "够", "is_correct": false, "explanation": "语义：“够”表示推力足够，与后文“变慢、飞不动”的因果矛盾。"}, {"text": "增加", "is_correct": false, "explanation": "配价：“增加”一般要说明增加的对象，这里用“推力增加”无法表达推力不足。"}, {"text": "变大", "is_correct": false, "explanation": "语义：推力变大应使飞机更快，与“变慢”“飞不动”矛盾。"}], "explanations": {"不够": "正确答案。推力达不到要求，所以飞机才会变慢、飞不动。", "够": "语义：“够”表示推力足够，与后文“变慢、飞不动”的因果矛盾。", "增加": "配价：“增加”一般要说明增加的对象，这里用“推力增加”无法表达推力不足。", "变大": "语义：推力变大应使飞机更快，与“变慢”“飞不动”矛盾。"}, "sentence_index": 0, "correct_answer": "不够"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间不够暖和，我一进门就觉得热得受不了。", "explanation": "这里应该用〈过热〉。“不够”表示未达到需要的标准，这里说的是温度超过了需要，应该用“过热”。"}, {"text": "这碗汤不够咸，我喝了一口就皱起了眉头。", "explanation": "这里应该用〈过咸〉。“不够咸”表示咸味未达到需要，这里说的是太咸，应该用“过咸”。"}, {"text": "这盘饺子不够吃，我们每人都吃撑了。", "explanation": "这里应该用〈太多〉。“不够”表示数量没有达到需要，这里说的是数量超过了需要，应该用“太多”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12113, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不够", "is_correct": true, "explanation": "正确答案。衣服的尺寸没有达到要求，所以我穿着有点小。"}, {"text": "够", "is_correct": false, "explanation": "语义：“够”表示衣服足够大，与后文“我穿着有点小”矛盾。"}, {"text": "合身", "is_correct": false, "explanation": "语义：“合身”表示大小正合适，与后文“有点小”矛盾。"}, {"text": "显得", "is_correct": false, "explanation": "体貌：“显得”表示外观给人的印象，与“我穿着有点小”的实际感受不符。"}], "explanations": {"不够": "正确答案。衣服的尺寸没有达到要求，所以我穿着有点小。", "够": "语义：“够”表示衣服足够大，与后文“我穿着有点小”矛盾。", "合身": "语义：“合身”表示大小正合适，与后文“有点小”矛盾。", "显得": "体貌：“显得”表示外观给人的印象，与“我穿着有点小”的实际感受不符。"}, "sentence_index": 6, "correct_answer": "不够"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子不够凉快，我们开了空调，还是冷得直打哆嗦。", "explanation": "这里应该用〈过冷〉。“不够凉快”表示温度未达到需要，这里说的是太冷，应该用“过冷”。"}, {"text": "这份工作的压力不够大，我每天加班到深夜，累得不行。", "explanation": "这里应该用〈过重〉。“不够大”表示未达到需要，这里说的是压力超过了需要，应该用“过重”。"}, {"text": "这杯茶不够浓，喝一口就觉得苦得发涩。", "explanation": "这里应该用〈过浓〉。“不够浓”表示浓度未达到需要，这里说的是太浓，应该用“过浓”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12113, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些椅子不够得，我们再搬几把来吧。", "corrected_sentence": "这些椅子不够，我们再搬几把来吧。", "error_description": "多加了“得”：“不够”后不能直接接“得”，应删去“得”，即“这些椅子不够，我们再搬几把来吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12113, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件外套不够长的，穿起来不暖和。", "corrected_sentence": "这件外套不够长，穿起来不暖和。", "error_description": "多加了“的”：“不够长”后直接加“的”，句子成了未完成的名词短语，应说“这件外套不够长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
