INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12117, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示借助或使用某物来完成某个动作。", "primary_collocate": null, "pronunciation": "yòng dào", "ipa": "jʊŋ˥˩ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "现代飞机设计要用到很多工程计算和风洞实验。", "target_word": "用到", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "做蛋糕要用到鸡蛋、面粉和糖。", "target_word": "用到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修自行车要用到几件小工具。", "target_word": "用到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写文章时，你会用到词典吗？", "target_word": "用到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把伞我带了，可是一次也没用到。", "target_word": "用到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以后工作中一定能用到这些知识。", "target_word": "用到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的数学课用到了尺子和笔。", "target_word": "用到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "画画用到的颜色很多。", "target_word": "用到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个工具很少用到，放在箱子里吧。", "target_word": "用到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做这个实验要用到很多水。", "target_word": "用到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "用到了", "label": "体标"}, {"form": "用不到", "label": "否定"}], "register": "中性", "sense_fingerprint": "用到：做某事时需要借助、使用某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '328de6f8-a753-46b2-9f72-d875f758cd08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12117, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用到", "is_correct": true, "explanation": "正确：“用到”表示设计时需要借助很多工程计算和实验，与句意相符。"}, {"text": "生产", "is_correct": false, "explanation": "搭配：“生产”的对象是产品，不能说生产工程计算。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：“演奏”的对象是乐曲，不能说演奏工程计算。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”是不及物动词，不能带“很多工程计算和风洞实验”做宾语。"}], "explanations": {"用到": "正确：“用到”表示设计时需要借助很多工程计算和实验，与句意相符。", "生产": "搭配：“生产”的对象是产品，不能说生产工程计算。", "演奏": "搭配：“演奏”的对象是乐曲，不能说演奏工程计算。", "睡觉": "配价：“睡觉”是不及物动词，不能带“很多工程计算和风洞实验”做宾语。"}, "sentence_index": 0, "correct_answer": "用到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用到了游泳，一个暑假就会了。", "explanation": "这里应该用〈学会〉。用到指借助某物办事，技能要用学会。"}, {"text": "我用到了明天的比赛。", "explanation": "这里应该用〈参加〉。用到指借助具体的物件，比赛要用参加。"}, {"text": "这件事我用到你的帮助。", "explanation": "这里应该用〈需要〉。用到指借助具体的物件，“帮助”这类要求要用需要。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf7ac19-460f-4443-8fa5-9a9ea809f07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12117, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用到", "is_correct": true, "explanation": "正确：“用到”表示今天的数学课上用了尺子和笔，与句意相符。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”表示吞下，不能指课上用了文具。"}, {"text": "穿上", "is_correct": false, "explanation": "搭配：“穿上”的对象是衣物，不能说穿尺子和笔。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能带“尺子和笔”做宾语。"}], "explanations": {"用到": "正确：“用到”表示今天的数学课上用了尺子和笔，与句意相符。", "吃掉": "语义：“吃掉”表示吞下，不能指课上用了文具。", "穿上": "搭配：“穿上”的对象是衣物，不能说穿尺子和笔。", "游泳": "配价：“游泳”是不及物动词，不能带“尺子和笔”做宾语。"}, "sentence_index": 6, "correct_answer": "用到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们应该用到这个机会练口语。", "explanation": "这里应该用〈利用〉。用到指借助具体的物件，机会要用利用。"}, {"text": "这位老师很会用到讲课。", "explanation": "这里应该用〈讲〉。用到的宾语应是事物，不能直接接动作短语“讲课”，应说“很会讲课”。"}, {"text": "这次活动充分用到了大家的作用。", "explanation": "这里应该用〈发挥〉。作用、优势要用发挥，不能说用到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf7ac19-460f-4443-8fa5-9a9ea809f07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12117, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学习数学时经常把用到计算器。", "corrected_sentence": "我们学习数学时经常用到计算器。", "error_description": "“把”误加：“用到”后面直接带宾语，不能用“把”引出；多出的“把”应删去，应说“经常用到计算器”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf7ac19-460f-4443-8fa5-9a9ea809f07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12117, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "做饭的时候，我们用到着一袋面粉。", "corrected_sentence": "做饭的时候，我们用到了一袋面粉。", "error_description": "体标错误：「用到」表示一次性完成的动作，后面应用完成体「了」，不能用表示持续状态的「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf7ac19-460f-4443-8fa5-9a9ea809f07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
