INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12120, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "风洞是一种实验设备，通过人工制造可控气流，模拟物体（如飞机、汽车）在空气中运动时的受力情况，用于空气动力学研究。", "primary_collocate": null, "pronunciation": "fēng dòng", "ipa": "fɤŋ˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "现代飞机设计要用到很多工程计算和风洞实验。", "target_word": "风洞", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "工程师先做小模型，放在风洞里吹风，看空气怎么流过。", "target_word": "风洞", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "材料科学的进步使得复合材料得以广泛应用，不仅减轻了结构重量，还增强了疲劳耐久性；计算流体动力学（CFD）的发展则使工程师能够在虚拟风洞中模拟极端工况下的气动性能，从而在原型制造前完成多轮迭代。", "target_word": "风洞", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工程师把飞机模型放进风洞里做测试。", "target_word": "风洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座风洞可以吹出很快的风。", "target_word": "风洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新车要先在风洞里试验，看风的阻力有多大。", "target_word": "风洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用风洞研究火箭的形状。", "target_word": "风洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风洞实验证明，这个设计能减少阻力。", "target_word": "风洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的实验室里有一个小风洞。", "target_word": "风洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做完这次风洞测试，他们修改了机翼的样子。", "target_word": "风洞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一座风洞", "label": "量词"}, {"form": "一个风洞", "label": "量词"}, {"form": "风洞实验", "label": "复合"}, {"form": "風洞", "label": "繁体"}], "register": "科技", "sense_fingerprint": "空气动力学实验设备，人工造风，测试飞机、汽车等的受力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2add0e14-7aad-4c53-8a62-eca53035b254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12120, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风洞", "is_correct": true, "explanation": "风洞是人工造风的空气动力学实验设备，与句中“飞机设计、工程计算”的语境相符。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：饭馆是吃饭的地方，与飞机设计的工程计算无关，不能说“饭馆实验”。"}, {"text": "游泳池", "is_correct": false, "explanation": "搭配：“实验”前多接学科或设备名称，不说“游泳池实验”。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场供体育活动使用，不是飞机设计所用的实验场所。"}], "explanations": {"风洞": "风洞是人工造风的空气动力学实验设备，与句中“飞机设计、工程计算”的语境相符。", "饭馆": "语义：饭馆是吃饭的地方，与飞机设计的工程计算无关，不能说“饭馆实验”。", "游泳池": "搭配：“实验”前多接学科或设备名称，不说“游泳池实验”。", "操场": "语义：操场供体育活动使用，不是飞机设计所用的实验场所。"}, "sentence_index": 0, "correct_answer": "风洞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "司机开车穿过山里的风洞，路很长。", "explanation": "这里应该用〈隧道〉。隧道是供车辆通行的通道，风洞是人工造风的实验设备，不能穿过。"}, {"text": "这栋大楼的空调风洞要定期清洗。", "explanation": "这里应该用〈风道〉。风道是建筑中输送空气的管道，风洞专指做空气动力学实验的设备。"}, {"text": "厂房的风洞里冒出黑烟。", "explanation": "这里应该用〈烟囱〉。烟囱是排烟的竖管，风洞是做空气动力学实验的设备，不会冒出黑烟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6aa91466-dc51-4c64-a00f-5d786ecfea41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风洞", "is_correct": true, "explanation": "风洞是能模拟气流的实验设备，用它研究火箭的形状符合句意。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱记录菜的做法，无法用来研究火箭的形状。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单列出可点的菜品，与研究火箭的形状毫无关系。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，不用于这类科学研究的表述。"}], "explanations": {"风洞": "风洞是能模拟气流的实验设备，用它研究火箭的形状符合句意。", "食谱": "语义：食谱记录菜的做法，无法用来研究火箭的形状。", "菜单": "语义：菜单列出可点的菜品，与研究火箭的形状毫无关系。", "玩意儿": "语域：“玩意儿”是口语说法，不用于这类科学研究的表述。"}, "sentence_index": 6, "correct_answer": "风洞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学校新买了一只风洞。", "explanation": "这里应该用〈座〉。“只”用于动物或成对物品中的一个，风洞是大型设备，应说“一座风洞”。"}, {"text": "实验室里放着一张风洞。", "explanation": "这里应该用〈座〉。“张”用于平面物品，风洞是立体的大型设备，应说“一座风洞”。"}, {"text": "工厂的车间里有一把风洞。", "explanation": "这里应该用〈座〉。“把”用于有柄的物品，风洞不能用“把”，应说“一座风洞”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6aa91466-dc51-4c64-a00f-5d786ecfea41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们实验室有一条风洞。", "corrected_sentence": "我们实验室有一座风洞。", "error_description": "量词错误：“风洞”是大型设备，应配量词“座”，不用“条”（“条”用于河、路、长条形物品等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6aa91466-dc51-4c64-a00f-5d786ecfea41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校里有两座风洞们。", "corrected_sentence": "学校里有两座风洞。", "error_description": "“们”错误：“们”只用于指人的名词之后，“风洞”是事物，不能加“们”表示复数；应直接说“两座风洞”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6aa91466-dc51-4c64-a00f-5d786ecfea41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
