INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12124, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "表示某种状态或动作持续到某一时间点才结束，相当于英文的''until''。", "primary_collocate": null, "pronunciation": "zhí dào", "ipa": "ʈʂɨ˧˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这个过程会重复很多次，直到飞机飞得又快又稳又安全。", "target_word": "直到", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "我一直看书，直到妈妈叫我吃饭。", "target_word": "直到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一直聊天，直到天都黑了。", "target_word": "直到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直到昨天，我才知道这件事。", "target_word": "直到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不停地练习，直到唱得很好听。", "target_word": "直到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭了很久，直到妈妈回来才安静。", "target_word": "直到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会在这里等你，直到你来。", "target_word": "直到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直到下课，他都没有说一句话。", "target_word": "直到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了又讲，直到大家都听懂了。", "target_word": "直到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨一直下，直到晚上才停。", "target_word": "直到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "直到：动作或状态持续到某一时间点或结果才结束", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '328de6f8-a753-46b2-9f72-d875f758cd08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12124, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "直到", "is_correct": true, "explanation": "直到：zhí（第二声）dào，表示持续到某一时间点才结束，是正确答案。"}, {"text": "知道", "is_correct": false, "explanation": "zhī（第一声）与 zhí（第二声）声调不同，意思是知道，不是直到。"}, {"text": "迟到", "is_correct": false, "explanation": "chí 与 zhí 声母不同（ch/zh），意思是迟到。"}, {"text": "指导", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，dǎo（第三声）与 dào（第四声）也不同，意思是指导。"}, {"text": "执导", "is_correct": false, "explanation": "dǎo（第三声）与 dào（第四声）声调不同，意思是执导（导演影片）。"}], "explanations": {"直到": "直到：zhí（第二声）dào，表示持续到某一时间点才结束，是正确答案。", "知道": "zhī（第一声）与 zhí（第二声）声调不同，意思是知道，不是直到。", "迟到": "chí 与 zhí 声母不同（ch/zh），意思是迟到。", "指导": "zhǐ（第三声）与 zhí（第二声）声调不同，dǎo（第三声）与 dào（第四声）也不同，意思是指导。", "执导": "dǎo（第三声）与 dào（第四声）声调不同，意思是执导（导演影片）。"}, "sentence_index": null, "correct_answer": "直到"}, "level_3": {"options": [{"text": "直到", "is_correct": true, "explanation": "直到：表示这个过程持续到飞机飞得又快又稳又安全为止，符合句意。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，但“重复很多次”并不是因为飞机飞得安全，句意不通。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：“虽然”引出让步，前面的重复过程与后面的安全之间没有让步关系。"}, {"text": "以致", "is_correct": false, "explanation": "语域：“以致”是书面语，多用来引出不好的结果，与“飞得又快又稳又安全”不符。"}], "explanations": {"直到": "直到：表示这个过程持续到飞机飞得又快又稳又安全为止，符合句意。", "因为": "语义：“因为”表示原因，但“重复很多次”并不是因为飞机飞得安全，句意不通。", "虽然": "语义：“虽然”引出让步，前面的重复过程与后面的安全之间没有让步关系。", "以致": "语域：“以致”是书面语，多用来引出不好的结果，与“飞得又快又稳又安全”不符。"}, "sentence_index": 0, "correct_answer": "直到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚进门，直到说了一句话。", "explanation": "这里应该用〈才〉。直到表示前面的动作或状态持续到某一点，“刚进门”是瞬间动作，不能持续。"}, {"text": "我们走了两个小时才直到学校。", "explanation": "这里应该用〈到〉。直到是连词，表示持续到某个时间点，不能作动词表示到达，所以不能说“直到学校”。"}, {"text": "我们直到去学校，不绕路。", "explanation": "这里应该用〈直接〉。直到表示持续到某时间点，不表示径直前往。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf7ac19-460f-4443-8fa5-9a9ea809f07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12124, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "直到", "is_correct": true, "explanation": "直到：zhí（第二声）dào，表示持续到某一时间点才结束，是正确答案。"}, {"text": "吃到", "is_correct": false, "explanation": "chī（第一声）与 zhí（第二声）声母不同（ch/zh），声调也不同，意思是吃到。"}, {"text": "实到", "is_correct": false, "explanation": "shí（第二声）与 zhí 声母不同（sh/zh），意思是实际到场，常说“实到人数”。"}, {"text": "制导", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）声调不同，dǎo 与 dào 也不同，意思是制导。"}, {"text": "只到", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是只到（达）。"}], "explanations": {"直到": "直到：zhí（第二声）dào，表示持续到某一时间点才结束，是正确答案。", "吃到": "chī（第一声）与 zhí（第二声）声母不同（ch/zh），声调也不同，意思是吃到。", "实到": "shí（第二声）与 zhí 声母不同（sh/zh），意思是实际到场，常说“实到人数”。", "制导": "zhì（第四声）与 zhí（第二声）声调不同，dǎo 与 dào 也不同，意思是制导。", "只到": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是只到（达）。"}, "sentence_index": null, "correct_answer": "直到"}, "level_3": {"options": [{"text": "直到", "is_correct": true, "explanation": "直到：表示等待一直持续到你来，符合句意。"}, {"text": "以免", "is_correct": false, "explanation": "语域：“以免”是书面语，表示为了避免不好的结果，与“等你来”的语境不符。"}, {"text": "尽管", "is_correct": false, "explanation": "语义：“尽管”引出让步，与“等你来”之间没有让步关系。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，“你来”不是“我等你”的结果，句意不通。"}], "explanations": {"直到": "直到：表示等待一直持续到你来，符合句意。", "以免": "语域：“以免”是书面语，表示为了避免不好的结果，与“等你来”的语境不符。", "尽管": "语义：“尽管”引出让步，与“等你来”之间没有让步关系。", "所以": "语义：“所以”表示因果，“你来”不是“我等你”的结果，句意不通。"}, "sentence_index": 6, "correct_answer": "直到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小猫一跳，直到碰倒了花瓶。", "explanation": "这里应该用〈于是〉。直到表示前面的动作持续到某一时间点，“一跳”是瞬间动作，不能持续。"}, {"text": "妈妈直到在门口等我回来。", "explanation": "这里应该用〈一直〉。直到是连词，要接在持续动作之后表示终点，不能代替“一直”描述持续的状态。"}, {"text": "他竟然直到考试作弊了。", "explanation": "这里应该用〈竟然〉。直到表示持续到某个时间点，不表示出乎意料的语气，这里要用竟然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf7ac19-460f-4443-8fa5-9a9ea809f07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他直到打游戏，直到妈妈来叫他才停下。", "corrected_sentence": "他一直打游戏，直到妈妈来叫他才停下。", "error_description": "词语误用：「打游戏」这类持续的动作要用「一直」表示持续，不能用「直到」；「直到」只能引出时间终点，应改为「他一直打游戏」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf7ac19-460f-4443-8fa5-9a9ea809f07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他读书读到很晚，天黑直到才回家。", "corrected_sentence": "他读书读到很晚，直到天黑才回家。", "error_description": "语序错误：「直到」应放在时间词「天黑」之前，说「直到天黑才回家」，不能说「天黑直到」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf7ac19-460f-4443-8fa5-9a9ea809f07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12127, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "运输", "is_correct": false, "explanation": "运输：指把货物从一地运到另一地，与“造”没有反义关系。"}, {"text": "拆", "is_correct": true, "explanation": "拆：与“造”相对，指把造好的东西拆开、拆散，与“造出”意思相反。"}, {"text": "驾驶", "is_correct": false, "explanation": "驾驶：指操纵车、船等交通工具，与“造”不构成反义。"}, {"text": "修理", "is_correct": false, "explanation": "修理：指使坏的东西恢复原状，与“造”不构成反义。"}], "correct_answer": "拆", "explanations": {"运输": "运输：指把货物从一地运到另一地，与“造”没有反义关系。", "拆": "拆：与“造”相对，指把造好的东西拆开、拆散，与“造出”意思相反。", "驾驶": "驾驶：指操纵车、船等交通工具，与“造”不构成反义。", "修理": "修理：指使坏的东西恢复原状，与“造”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf7ac19-460f-4443-8fa5-9a9ea809f07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12127, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "欣赏", "is_correct": false, "explanation": "欣赏：指喜爱地观看、品味，与“造”没有反义关系。"}, {"text": "拆解", "is_correct": true, "explanation": "拆解：与“造”相对，指把成品拆开分解，与“造出”意思相反。"}, {"text": "发送", "is_correct": false, "explanation": "发送：指把信息或物品送出去，与“造”没有反义关系。"}, {"text": "参观", "is_correct": false, "explanation": "参观：指到某处观看，与“造”没有反义关系。"}], "correct_answer": "拆解", "explanations": {"欣赏": "欣赏：指喜爱地观看、品味，与“造”没有反义关系。", "拆解": "拆解：与“造”相对，指把成品拆开分解，与“造出”意思相反。", "发送": "发送：指把信息或物品送出去，与“造”没有反义关系。", "参观": "参观：指到某处观看，与“造”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf7ac19-460f-4443-8fa5-9a9ea809f07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12127, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过创造、生产或努力而产生出某种事物。", "primary_collocate": null, "pronunciation": "zào chū", "ipa": "tsɑʊ˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "懂了这些规律，我们就能造出更好的飞机。", "target_word": "造出", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "工人们造出了一辆新汽车。", "target_word": "造出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用木头造出一张小桌子。", "target_word": "造出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司造出了很快的火车。", "target_word": "造出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们造出了一个小机器人。", "target_word": "造出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家想造出更安全的飞机。", "target_word": "造出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷用旧木板造出一个鸟窝。", "target_word": "造出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用三年时间造出这条船。", "target_word": "造出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我也想造出自己的电脑。", "target_word": "造出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂造出的新手机很便宜。", "target_word": "造出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "造出了", "label": "完成体"}, {"form": "造出过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "造出：通过制造或创造使某物产生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '328de6f8-a753-46b2-9f72-d875f758cd08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12127, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "造出", "is_correct": true, "explanation": "造出（zào chū）：正确答案，指通过制作、创造而产生某种事物。"}, {"text": "照出", "is_correct": false, "explanation": "zhào（第四声）与 zào 声母不同（zh/z），意思是光线照射而显现出来。"}, {"text": "早出", "is_correct": false, "explanation": "zǎo（第三声）与 zào（第四声）声调不同，意思是早早出去。"}, {"text": "道出", "is_correct": false, "explanation": "dào 与 zào 声母不同（d/z），意思是用语言说出、表达出来。"}, {"text": "导出", "is_correct": false, "explanation": "dǎo 与 zào 声母和声调都不同，意思是引导出去，或导出数据。"}], "explanations": {"造出": "造出（zào chū）：正确答案，指通过制作、创造而产生某种事物。", "照出": "zhào（第四声）与 zào 声母不同（zh/z），意思是光线照射而显现出来。", "早出": "zǎo（第三声）与 zào（第四声）声调不同，意思是早早出去。", "道出": "dào 与 zào 声母不同（d/z），意思是用语言说出、表达出来。", "导出": "dǎo 与 zào 声母和声调都不同，意思是引导出去，或导出数据。"}, "sentence_index": null, "correct_answer": "造出"}, "level_3": {"options": [{"text": "摘取", "is_correct": false, "explanation": "搭配：“摘取”只用于果实、花朵等可摘之物，不能说“摘取更好的飞机”。"}, {"text": "造出", "is_correct": true, "explanation": "造出：通过制作、创造产生更好的飞机，符合句意。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”不能以制造物为宾语，不能说“吃掉更好的飞机”。"}, {"text": "唱出", "is_correct": false, "explanation": "语义：“唱出”指用声音表达，与制作飞机无关，句意不通。"}], "explanations": {"摘取": "搭配：“摘取”只用于果实、花朵等可摘之物，不能说“摘取更好的飞机”。", "造出": "造出：通过制作、创造产生更好的飞机，符合句意。", "吃掉": "搭配：“吃掉”不能以制造物为宾语，不能说“吃掉更好的飞机”。", "唱出": "语义：“唱出”指用声音表达，与制作飞机无关，句意不通。"}, "sentence_index": 0, "correct_answer": "造出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块地每年造出很多粮食。", "explanation": "这里应该用〈产出〉。造出指人工制作出物品，土地每年的粮食产量要用产出。"}, {"text": "这件事造出了很大的影响。", "explanation": "这里应该用〈造成〉。造出用于能制作的实物，影响、损失等抽象结果要用造成。"}, {"text": "听完这首歌，我心里造出了一阵感动。", "explanation": "这里应该用〈产生〉。造出指人工制作具体物品，“感动”这类心理感受要用产生，不能说造出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf7ac19-460f-4443-8fa5-9a9ea809f07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12127, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "造出", "is_correct": true, "explanation": "造出（zào chū）：正确答案，指通过制作、创造而产生某种事物。"}, {"text": "凿出", "is_correct": false, "explanation": "záo（第二声）与 zào（第四声）声调不同，意思是用凿子凿出。"}, {"text": "奏出", "is_correct": false, "explanation": "zòu 与 zào 韵母不同（ou/ao），意思是演奏出（乐曲）。"}, {"text": "找出", "is_correct": false, "explanation": "zhǎo 与 zào 声母和声调都不同，意思是寻找并找到。"}], "explanations": {"造出": "造出（zào chū）：正确答案，指通过制作、创造而产生某种事物。", "凿出": "záo（第二声）与 zào（第四声）声调不同，意思是用凿子凿出。", "奏出": "zòu 与 zào 韵母不同（ou/ao），意思是演奏出（乐曲）。", "找出": "zhǎo 与 zào 声母和声调都不同，意思是寻找并找到。"}, "sentence_index": null, "correct_answer": "造出"}, "level_3": {"options": [{"text": "啃", "is_correct": false, "explanation": "搭配：“啃”指咬食物，不能说“啃出一个鸟窝”。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洁，不指用材料做出物件，句意不通。"}, {"text": "造出", "is_correct": true, "explanation": "造出：通过用旧木板制作，做出一个鸟窝，符合句意。"}, {"text": "吞掉", "is_correct": false, "explanation": "搭配：“吞掉”只用于可吞之物，不能说“吞掉一个鸟窝”。"}], "explanations": {"啃": "搭配：“啃”指咬食物，不能说“啃出一个鸟窝”。", "洗": "语义：“洗”指清洁，不指用材料做出物件，句意不通。", "造出": "造出：通过用旧木板制作，做出一个鸟窝，符合句意。", "吞掉": "搭配：“吞掉”只用于可吞之物，不能说“吞掉一个鸟窝”。"}, "sentence_index": 6, "correct_answer": "造出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春天到了，田野里造出了一片绿色。", "explanation": "这里应该用〈显出〉。造出指人通过制作或创造产生某物，绿色是自然显现的，不能说造出。"}, {"text": "太阳升起后，天空造出了一道彩虹。", "explanation": "这里应该用〈出现〉。彩虹是自然现象，不是人工制作或努力产生的，要用出现。"}, {"text": "深夜里，远处造出了一阵雷声。", "explanation": "这里应该用〈传来〉。雷声是自然发出的，不能说造出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf7ac19-460f-4443-8fa5-9a9ea809f07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12127, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于造出过一台能走路的机器人。", "corrected_sentence": "他终于造出了一台能走路的机器人。", "error_description": "体标错误：这里表示终于完成的一次结果，应用完成体「造出了」；「造出过」是经历体，表示曾经做过，与「终于」表示完成的语气不搭。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf7ac19-460f-4443-8fa5-9a9ea809f07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12127, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂去年造出着一百万部新手机。", "corrected_sentence": "这家工厂去年造出了一百万部新手机。", "error_description": "体标错误：「造出」表示一次性完成的动作，应用完成体「了」，不能用表示持续状态的「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf7ac19-460f-4443-8fa5-9a9ea809f07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
