INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12130, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12130, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物运行或行为必须遵循的规律、规则或原理。", "primary_collocate": null, "pronunciation": "fǎ zé", "ipa": "fa˨˩˦ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "在现代航空工程的精密体系中，飞行器的设计本质上是物理法则的艺术化应用，尤其是空气动力学原理在其中占据了核心地位。", "target_word": "法则", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "由此观之，航空工程不仅是技术的集合体，更是人类对自然法则深刻理解的外化表现。", "target_word": "法则", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "万物都要遵守自然法则。", "target_word": "法则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们科学的基本法则。", "target_word": "法则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "供求关系决定价格，这是市场最基本的法则。", "target_word": "法则", "complexity_tier": "T3", "furigana": "gōngqiú guānxì juédìng jiàgé, zhè shì shìchǎng zuì jīběn de fǎzé", "sentence_source": "generated"}, {"text": "生存法则很简单：适应环境才能活下去。", "target_word": "法则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子要学会遵守游戏法则。", "target_word": "法则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛顿发现了物体运动的法则。", "target_word": "法则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意有自己的法则，不能乱来。", "target_word": "法则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这条法则写在本子上。", "target_word": "法则", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条法则", "label": "量词"}, {"form": "自然法则", "label": "复合"}, {"form": "法則", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物运行或行为必须遵循的规律、规则、原理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ba539e2-997b-4cf4-8bc9-f8e1b6a4200e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12130, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "法则", "is_correct": true, "explanation": "正确。“物理法则”指物理世界中的规律，与句中的空气动力学原理语境相符。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱是烹饪用的菜式说明，与“物理”层面的艺术化应用无关。"}, {"text": "情感", "is_correct": false, "explanation": "语义：情感属于心理体验，不是可以用物理规律来描述的对象。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“物理”修饰的是物理学中的规律或现象，“颜色”不能与“物理”构成搭配。"}], "explanations": {"法则": "正确。“物理法则”指物理世界中的规律，与句中的空气动力学原理语境相符。", "食谱": "语义：食谱是烹饪用的菜式说明，与“物理”层面的艺术化应用无关。", "情感": "语义：情感属于心理体验，不是可以用物理规律来描述的对象。", "颜色": "搭配：“物理”修饰的是物理学中的规律或现象，“颜色”不能与“物理”构成搭配。"}, "sentence_index": 0, "correct_answer": "法则"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在台上唱起了法则。", "explanation": "这里应该用〈歌〉。“唱”的对象是歌曲，法则是抽象的规律，不能唱。"}, {"text": "我把法则放进了书包。", "explanation": "这里应该用〈课本〉。法则是抽象的规律，不能像课本那样放进书包。"}, {"text": "这幅画的法则很鲜艳。", "explanation": "这里应该用〈颜色〉。“鲜艳”形容颜色，法则是抽象的规律，不能用来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法则", "is_correct": true, "explanation": "正确。“遵守游戏法则”指遵守游戏的规则，符合句意。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是实物，不能被“遵守”。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“遵守”的宾语应是规则或约定，“热情”不能被遵守。"}, {"text": "乐趣", "is_correct": false, "explanation": "搭配：“遵守”后接规则，“乐趣”是感受，不能说“遵守乐趣”。"}], "explanations": {"法则": "正确。“遵守游戏法则”指遵守游戏的规则，符合句意。", "玩具": "语义：玩具是实物，不能被“遵守”。", "热情": "搭配：“遵守”的宾语应是规则或约定，“热情”不能被遵守。", "乐趣": "搭配：“遵守”后接规则，“乐趣”是感受，不能说“遵守乐趣”。"}, "sentence_index": 6, "correct_answer": "法则"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他饿了，想吃点法则。", "explanation": "这里应该用〈东西〉。“吃”的对象是食物，法则是抽象的规律，不能吃。"}, {"text": "我们每年在法则播种。", "explanation": "这里应该用〈春天〉。“在春天播种”表示季节，法则不是时间。"}, {"text": "这艘船在法则上航行。", "explanation": "这里应该用〈大海〉。船在大海上航行，法则是抽象规则，不是可以航行的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们必须遵守这只法则。", "corrected_sentence": "我们必须遵守这条法则。", "error_description": "量词错误：“法则”应使用量词“条”，不能用“只”。“只”多用于动物或成对物品中的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很快就掌握过这条法则。", "corrected_sentence": "他很快就掌握了这条法则。", "error_description": "体标错误：“很快就”表示事情已经完成，应用“了”，不能用“过”（“过”表示曾经经历的动作）。应说“他很快就掌握了这条法则”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12131, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
