INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12134, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用强力把别人的地方或东西夺过来，使自己拥有。", "primary_collocate": null, "pronunciation": "zhàn jù", "ipa": "tʂan˥˩ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "在那场突袭中，敌军趁着夜色迅速占据了制高点，并掌握了整个战场的主动权。", "target_word": "占据", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "敌人占据了山上的村子。", "target_word": "占据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "军队很快占据了这座城市。", "target_word": "占据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们占据了河边的一块地。", "target_word": "占据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坏人占据了老人的房子。", "target_word": "占据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支队伍占据了高地。", "target_word": "占据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外国军队曾经占据这个岛。", "target_word": "占据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们想占据那座桥。", "target_word": "占据", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "敌人占据了我们的山头，我们要夺回来。", "target_word": "占据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些人占据了工厂，不让工人进去。", "target_word": "占据", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "占据了", "label": "体标"}, {"form": "占据着", "label": "体标"}, {"form": "占据过", "label": "体标"}], "register": "书面", "sense_fingerprint": "用强力夺取别人的地方或东西并据为己有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 4 words above tier T2 (max 3): 趁着 (Zipf 3.64), 夜色 (Zipf 3.43), 制高点 (Zipf 3.33), 主动权 (Zipf 3.16)']::text[], '7ba539e2-997b-4cf4-8bc9-f8e1b6a4200e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12134, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "设计", "is_correct": false, "explanation": "搭配：「设计」指规划绘制，不能用来表示夺取「制高点」。"}, {"text": "占据", "is_correct": true, "explanation": "正确：「占据」指用强力夺取并据为己有，句中敌军夺取「制高点」，与句义相符。"}, {"text": "检测", "is_correct": false, "explanation": "语义：「检测」指检查测定，与夺取「制高点」的军事行动无关。"}, {"text": "撤销", "is_correct": false, "explanation": "语义：「撤销」指取消，与句中敌军迅速行动、掌握主动权的语境相反。"}], "explanations": {"设计": "搭配：「设计」指规划绘制，不能用来表示夺取「制高点」。", "占据": "正确：「占据」指用强力夺取并据为己有，句中敌军夺取「制高点」，与句义相符。", "检测": "语义：「检测」指检查测定，与夺取「制高点」的军事行动无关。", "撤销": "语义：「撤销」指取消，与句中敌军迅速行动、掌握主动权的语境相反。"}, "sentence_index": 0, "correct_answer": "占据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "居民们占据了免费的体检服务。", "explanation": "这里应该用〈享有〉。「占据」指用强力把别人的地方或东西夺过来，享受服务这类权利应说「享有」。"}, {"text": "农民在田里占据了小麦。", "explanation": "这里应该用〈种植〉。「占据」指用强力夺取，种地、栽种庄稼应说「种植」。"}, {"text": "我爸爸去年占据了一辆新车。", "explanation": "这里应该用〈购买〉。「占据」指用强力夺取，正常付钱买车应说「购买」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12134, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推销", "is_correct": false, "explanation": "语义：「推销」指卖东西，军队不会对岛屿进行推销，句义不通。"}, {"text": "占据", "is_correct": true, "explanation": "正确：「占据」指强行夺取并拥有，与「外国军队」「曾经」的语境相符。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：「欣赏」指赞美观赏，与外国军队对岛屿的强行行动不符。"}, {"text": "吸引", "is_correct": false, "explanation": "搭配：「吸引」的对象多是注意力或人，不能说「吸引这个岛」。"}], "explanations": {"推销": "语义：「推销」指卖东西，军队不会对岛屿进行推销，句义不通。", "占据": "正确：「占据」指强行夺取并拥有，与「外国军队」「曾经」的语境相符。", "欣赏": "语义：「欣赏」指赞美观赏，与外国军队对岛屿的强行行动不符。", "吸引": "搭配：「吸引」的对象多是注意力或人，不能说「吸引这个岛」。"}, "sentence_index": 6, "correct_answer": "占据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他占据了这次比赛，还拿到了奖牌。", "explanation": "这里应该用〈参加〉。「占据」指用强力夺取别人的地方或东西，参加比赛不能说「占据」。"}, {"text": "他占据了三本书，还得按时还。", "explanation": "这里应该用〈借阅〉。「占据」指用强力夺取，借书阅读后要归还，应说「借阅」。"}, {"text": "他认真占据了老师的问题。", "explanation": "这里应该用〈回答〉。「占据」指用强力夺取，回答问题不能说「占据」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们一进城就把广场占据。", "corrected_sentence": "他们一进城就把广场占据了。", "error_description": "错误形式：「把广场占据」后缺少「了」。正确形式：「把广场占据了」。原因：「把」字句中动词后要带「了」或其他补充成分，动作才算完成，句子才完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "敌人占据在那座小镇。", "corrected_sentence": "敌人占据了那座小镇。", "error_description": "错误形式：「占据」后用了「在」。正确形式：「占据了」。原因：「占据」是及物动词，后面应用「了」表示完成；「在」不能接在动词后面，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
