INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12137, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机翼是飞机两侧用来产生升力、保持飞行的部件。", "primary_collocate": null, "pronunciation": "jī yì", "ipa": "tɕi˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "当一架飞机在大气层中穿行时，其机翼与气流之间的相互作用决定了飞行的基本可行性。", "target_word": "机翼", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这一过程的核心在于升力的生成机制——机翼上表面的气流因曲率较大而流速加快，导致压力降低；相比之下，下表面的气流流速较慢，压力相对较高。", "target_word": "机翼", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "然而，仅依赖伯努利原理并不足以完全描述复杂的真实流动现象，因此现代空气动力学更倾向于结合牛顿第三定律进行综合分析：机翼通过攻角向下偏转气流，气流则以相等且反向的力推动机翼上升，从而产生升力。", "target_word": "机翼", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "飞机在不同飞行阶段（如起飞、巡航、降落）所面临的气动挑战各异，要求机翼形态（如襟翼与缝翼的展开）能够动态适应。", "target_word": "机翼", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "飞机的机翼能产生升力。", "target_word": "机翼", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "机翼的形状影响飞机的升力。", "target_word": "机翼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师正在检查机翼上的零件。", "target_word": "机翼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这架飞机的机翼下方挂着两台发动机。", "target_word": "机翼", "complexity_tier": "T3", "furigana": "zhè jià fēi jī de jī yì xià fāng guà zhe liǎng tái fā dòng jī。", "sentence_source": "generated"}, {"text": "飞行员把襟翼放下，机翼的升力变大了。", "target_word": "机翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风洞实验测试了新型机翼的性能。", "target_word": "机翼", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一对机翼", "label": "量词"}, {"form": "主机翼", "label": "复合"}], "register": "书面", "sense_fingerprint": "飞机两侧产生升力的部件，空气动力学语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ea6797-318b-42b7-a7d7-5ecd5fb5d5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12137, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "机翼", "is_correct": true, "explanation": "正确答案：机翼 jī yì，指飞机两侧产生升力的部件。"}, {"text": "记忆", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，意思是记住并能回想起的能力。"}, {"text": "机遇", "is_correct": false, "explanation": "第二个音节 yù 与 yì 的韵母不同（ü 对 i），意思是可以把握的好时机。"}, {"text": "机制", "is_correct": false, "explanation": "第二个音节 zhì 与 yì 的声母不同（zh 对零声母），意思是事物内部的运作方式。"}, {"text": "饥饿", "is_correct": false, "explanation": "第二个音节 è 与 yì 的韵母不同（e 对 i），意思是肚子空了、想吃东西的状态。"}, {"text": "奇异", "is_correct": false, "explanation": "第一个音节 qí（第二声）与 jī（第一声）声调不同，意思是奇特、与众不同。"}], "explanations": {"机翼": "正确答案：机翼 jī yì，指飞机两侧产生升力的部件。", "记忆": "jì（第四声）与 jī（第一声）声调不同，意思是记住并能回想起的能力。", "机遇": "第二个音节 yù 与 yì 的韵母不同（ü 对 i），意思是可以把握的好时机。", "机制": "第二个音节 zhì 与 yì 的声母不同（zh 对零声母），意思是事物内部的运作方式。", "饥饿": "第二个音节 è 与 yì 的韵母不同（e 对 i），意思是肚子空了、想吃东西的状态。", "奇异": "第一个音节 qí（第二声）与 jī（第一声）声调不同，意思是奇特、与众不同。"}, "sentence_index": null, "correct_answer": "机翼"}, "level_3": {"options": [{"text": "机翼", "is_correct": true, "explanation": "正确：机翼是飞机两侧产生升力的部件，与气流相互作用，决定飞行的可行性。"}, {"text": "车轮", "is_correct": false, "explanation": "语义：车轮属于陆上车辆，与在大气层中穿行的飞机无关。"}, {"text": "羽毛", "is_correct": false, "explanation": "语义：羽毛是鸟类的体表结构，飞机没有羽毛。"}, {"text": "齿轮", "is_correct": false, "explanation": "语义：齿轮是机械传动部件，不在大气中与气流作用，也不决定飞机能否飞行。"}], "explanations": {"机翼": "正确：机翼是飞机两侧产生升力的部件，与气流相互作用，决定飞行的可行性。", "车轮": "语义：车轮属于陆上车辆，与在大气层中穿行的飞机无关。", "羽毛": "语义：羽毛是鸟类的体表结构，飞机没有羽毛。", "齿轮": "语义：齿轮是机械传动部件，不在大气中与气流作用，也不决定飞机能否飞行。"}, "sentence_index": 0, "correct_answer": "机翼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小鸟张开机翼飞走了。", "explanation": "这里应该用〈翅膀〉。机翼专指飞机两侧的部件，鸟类的翅膀要说“翅膀”。"}, {"text": "这架直升机的机翼飞快地转动，带起一阵大风。", "explanation": "这里应该用〈旋翼〉。直升机的旋翼绕轴转动，机翼是固定在机身两侧的翼面，不会转动。"}, {"text": "工程师修好了一把机翼。", "explanation": "这里应该用〈个〉或〈对〉。“把”用于有柄的器具，机翼不用“把”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12137, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "机翼", "is_correct": true, "explanation": "正确答案：机翼 jī yì，指飞机两侧产生升力的部件。"}, {"text": "机器", "is_correct": false, "explanation": "第二个音节 qì 与 yì 的声母不同（q 对零声母），意思是利用能量做功的装置。"}, {"text": "西翼", "is_correct": false, "explanation": "第一个音节 xī 与 jī 的声母不同（x 对 j），意思是建筑或机构的西侧部分。"}, {"text": "极易", "is_correct": false, "explanation": "第一个音节 jí（第二声）与 jī（第一声）声调不同，意思是非常容易。"}, {"text": "技艺", "is_correct": false, "explanation": "第一个音节 jì（第四声）与 jī（第一声）声调不同，意思是技术和本领。"}], "explanations": {"机翼": "正确答案：机翼 jī yì，指飞机两侧产生升力的部件。", "机器": "第二个音节 qì 与 yì 的声母不同（q 对零声母），意思是利用能量做功的装置。", "西翼": "第一个音节 xī 与 jī 的声母不同（x 对 j），意思是建筑或机构的西侧部分。", "极易": "第一个音节 jí（第二声）与 jī（第一声）声调不同，意思是非常容易。", "技艺": "第一个音节 jì（第四声）与 jī（第一声）声调不同，意思是技术和本领。"}, "sentence_index": null, "correct_answer": "机翼"}, "level_3": {"options": [{"text": "机翼", "is_correct": true, "explanation": "正确：机翼是飞机上的部件，工程师检查的是机翼上的零件。"}, {"text": "树", "is_correct": false, "explanation": "语义：树上没有需要工程师检查的零件，句中指的是飞机部件。"}, {"text": "硬币", "is_correct": false, "explanation": "语义：硬币上不会有需要工程师检查的零件，与语境不合。"}, {"text": "病人", "is_correct": false, "explanation": "搭配：“检查”可以用于病人（检查身体），但“病人上的零件”不成立，零件应指机器部件。"}], "explanations": {"机翼": "正确：机翼是飞机上的部件，工程师检查的是机翼上的零件。", "树": "语义：树上没有需要工程师检查的零件，句中指的是飞机部件。", "硬币": "语义：硬币上不会有需要工程师检查的零件，与语境不合。", "病人": "搭配：“检查”可以用于病人（检查身体），但“病人上的零件”不成立，零件应指机器部件。"}, "sentence_index": 6, "correct_answer": "机翼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "风力发电机的机翼在风中慢慢转动。", "explanation": "这里应该用〈叶片〉。风力发电机的旋转部件叫叶片，机翼专指飞机的部件。"}, {"text": "无人机的机翼飞快地转动。", "explanation": "这里应该用〈螺旋桨〉。螺旋桨绕轴转动，机翼是固定在机身两侧的翼面，不会转动。"}, {"text": "工人把一扇机翼搬进了车间。", "explanation": "这里应该用〈个〉或〈对〉。“扇”用于门窗，机翼不能用“扇”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12137, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "检修人员在机场检查了这架飞机的两只机翼。", "corrected_sentence": "检修人员在机场检查了这架飞机的两个机翼。", "error_description": "量词错误：机翼应用“个”或“对”计量，正确说法是“两个机翼”。“只”多用于动物或成对的器官（如“两只翅膀”），学习者常把它套用到机翼上。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12137, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工程师在车间里把机翼检查着一遍。", "corrected_sentence": "工程师在车间里把机翼检查了一遍。", "error_description": "体标错误：动量补语“一遍”前的动词应使用完成体“了”，“着”表示持续，不能与“一遍”搭配，应说“把机翼检查了一遍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12138, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12138, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12138, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "流动的空气，通常指风或呼吸时进出的气体。", "primary_collocate": null, "pronunciation": "qì liú", "ipa": "tɕʰi˥˩ liou˧˥", "syllable_count": 2, "sentences": [{"text": "风车作为中世纪最具象征性的技术装置，通过叶片捕捉气流动能，驱动磨坊碾磨谷物或抽排沼泽积水。", "target_word": "气流", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "当一架飞机在大气层中穿行时，其机翼与气流之间的相互作用决定了飞行的基本可行性。", "target_word": "气流", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这一过程的核心在于升力的生成机制——机翼上表面的气流因曲率较大而流速加快，导致压力降低；相比之下，下表面的气流流速较慢，压力相对较高。", "target_word": "气流", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种压力差垂直于气流方向，形成向上的净力，即升力。", "target_word": "气流", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "然而，仅依赖伯努利原理并不足以完全描述复杂的真实流动现象，因此现代空气动力学更倾向于结合牛顿第三定律进行综合分析：机翼通过攻角向下偏转气流，气流则以相等且反向的力推动机翼上升，从而产生升力。", "target_word": "气流", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "此外，主动流动控制技术，如边界层吸入或合成射流，正在被探索用于实时调节气流分离，进一步延展飞行包线。", "target_word": "气流", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "一股气流从门缝里吹进来。", "target_word": "气流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机遇到气流，上下摇了起来。", "target_word": "气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山谷里的气流把风筝送上了天。", "target_word": "气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吸气时，气流从鼻子进入身体。", "target_word": "气流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股气流", "label": "量词"}, {"form": "上升气流", "label": "复合"}], "register": "中性", "sense_fingerprint": "流动的空气，如风或呼吸的气体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5f59174-23ab-4b8b-9546-74dc82c078e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12138, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "气流", "is_correct": true, "explanation": "正确：气流 qì liú，意思是流动的空气。"}, {"text": "细流", "is_correct": false, "explanation": "细流 xìliú 的声母 x 与 q 不同，声调相同（第四声），意思是细小的水流。"}, {"text": "激流", "is_correct": false, "explanation": "激流 jīliú 的声母 j 与 q 不同，声调也变为第一声，意思是急速的水流。"}, {"text": "溪流", "is_correct": false, "explanation": "溪流 xīliú 的声母 x 与 q 不同，声调变为第一声，意思是小河。"}], "explanations": {"气流": "正确：气流 qì liú，意思是流动的空气。", "细流": "细流 xìliú 的声母 x 与 q 不同，声调相同（第四声），意思是细小的水流。", "激流": "激流 jīliú 的声母 j 与 q 不同，声调也变为第一声，意思是急速的水流。", "溪流": "溪流 xīliú 的声母 x 与 q 不同，声调变为第一声，意思是小河。"}, "sentence_index": null, "correct_answer": "气流"}, "level_3": {"options": [{"text": "气流", "is_correct": true, "explanation": "正确：“气流”指流动的空气，风车叶片借此获取动能。"}, {"text": "水流", "is_correct": false, "explanation": "语义：风车靠风转动，应当捕捉的是气流，不是水流。"}, {"text": "人流", "is_correct": false, "explanation": "语义：“人流”指人群的移动，与叶片捕捉风的动能无关。"}, {"text": "声浪", "is_correct": false, "explanation": "搭配：叶片靠风的流动转动，不能“捕捉”声浪的动能。"}], "explanations": {"气流": "正确：“气流”指流动的空气，风车叶片借此获取动能。", "水流": "语义：风车靠风转动，应当捕捉的是气流，不是水流。", "人流": "语义：“人流”指人群的移动，与叶片捕捉风的动能无关。", "声浪": "搭配：叶片靠风的流动转动，不能“捕捉”声浪的动能。"}, "sentence_index": 0, "correct_answer": "气流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋里的气流很闷，人都喘不过气。", "explanation": "这里应该用〈空气〉。“闷”形容空气不流通；气流指流动的空气，流动时不能说闷。"}, {"text": "电线里有气流通过。", "explanation": "这里应该用〈电流〉。电线里通过的是电流；气流指流动的空气，不在电线里通过。"}, {"text": "屋外传来一阵奇怪的气流。", "explanation": "这里应该用〈声音〉。“传来”的是声音；气流是流动的空气，不用来表示“传来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12138, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "气流", "is_correct": true, "explanation": "正确：气流 qì liú，意思是流动的空气。"}, {"text": "逆流", "is_correct": false, "explanation": "逆流 nìliú 的声母 n 与 q 不同，声调相同，意思是向上游流动。"}, {"text": "底流", "is_correct": false, "explanation": "底流 dǐliú 的声母 d 与 q 不同，声调变为第三声，意思是水底的暗流。"}, {"text": "溢流", "is_correct": false, "explanation": "溢流 yìliú 的声母 y 与 q 不同，声调相同，意思是满出来向下流。"}], "explanations": {"气流": "正确：气流 qì liú，意思是流动的空气。", "逆流": "逆流 nìliú 的声母 n 与 q 不同，声调相同，意思是向上游流动。", "底流": "底流 dǐliú 的声母 d 与 q 不同，声调变为第三声，意思是水底的暗流。", "溢流": "溢流 yìliú 的声母 y 与 q 不同，声调相同，意思是满出来向下流。"}, "sentence_index": null, "correct_answer": "气流"}, "level_3": {"options": [{"text": "气流", "is_correct": true, "explanation": "正确：“一股气流”是从门缝吹进来的流动空气，量词“股”搭配自然。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“吹”进来的是风或气体，水不能被“吹”进门缝。"}, {"text": "怒气", "is_correct": false, "explanation": "语义：“怒气”是情绪，不能从门缝里被吹进来。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性情，不是可以从门缝吹进来的东西。"}], "explanations": {"气流": "正确：“一股气流”是从门缝吹进来的流动空气，量词“股”搭配自然。", "水": "搭配：“吹”进来的是风或气体，水不能被“吹”进门缝。", "怒气": "语义：“怒气”是情绪，不能从门缝里被吹进来。", "脾气": "语义：“脾气”指性情，不是可以从门缝吹进来的东西。"}, "sentence_index": 6, "correct_answer": "气流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河里的气流很急。", "explanation": "这里应该用〈水流〉。河里流动的是水，气流指空气的流动，不能说“河里的气流”。"}, {"text": "他心里憋着一股气流。", "explanation": "这里应该用〈怒气〉。“憋着一股气”指压在心里的情绪；气流只指流动的空气，不能用于情绪。"}, {"text": "气流在血管里很快地流动。", "explanation": "这里应该用〈血流〉。血管里流动的是血液，气流指空气的流动，不能在血管中流动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "午后，一颗凉爽的气流从窗口吹进来。", "corrected_sentence": "午后，一股凉爽的气流从窗口吹进来。", "error_description": "错误形式：“一颗凉爽的气流”。正确形式：“一股凉爽的气流”。“气流”要用量词“股”，不能用“颗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几股气流们从门缝里吹进来。", "corrected_sentence": "几股气流从门缝里吹进来。", "error_description": "错误：“们”只用于人或拟人化的人称，不能接在“气流”后表示复数，应去掉“们”，说“几股气流”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
