INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12144, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12144, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "曲率是几何学中描述曲线或曲面弯曲程度的一个度量，数值越大表示弯曲得越厉害。", "primary_collocate": null, "pronunciation": "qū lǜ", "ipa": "tɕʰy˥ ly˥˩", "syllable_count": 2, "sentences": [{"text": "这一过程的核心在于升力的生成机制——机翼上表面的气流因曲率较大而流速加快，导致压力降低；相比之下，下表面的气流流速较慢，压力相对较高。", "target_word": "曲率", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "曲率越大，弯得越厉害。", "target_word": "曲率", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条曲线的曲率很小。", "target_word": "曲率", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "圆的曲率处处都一样。", "target_word": "曲率", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "直线的曲率等于零。", "target_word": "曲率", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "机翼上表面的曲率比较大。", "target_word": "曲率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "数学家计算了这个曲面的曲率。", "target_word": "曲率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "半径越小，圆的曲率就越大。", "target_word": "曲率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公路设计要考虑弯道的曲率。", "target_word": "曲率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "曲率的数值越大，曲线越弯。", "target_word": "曲率", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "曲率半径", "label": "复合"}, {"form": "平均曲率", "label": "复合"}], "register": "书面", "sense_fingerprint": "几何学中衡量曲线或曲面弯曲程度的数值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ea6797-318b-42b7-a7d7-5ecd5fb5d5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12144, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "曲率", "is_correct": true, "explanation": "正确。“曲率”指曲线或曲面的弯曲程度，与“上表面弯曲大，因而流速快”的因果关系相符。"}, {"text": "色彩", "is_correct": false, "explanation": "搭配：“较大”多用于程度或数量，不用来形容色彩的大小，而且色彩与气流流速无关。"}, {"text": "音量", "is_correct": false, "explanation": "语义：气流流速与声音大小无关，“因音量较大而流速加快”不成立。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道的浓淡与气流速度无关，不能解释上表面流速加快的原因。"}], "explanations": {"曲率": "正确。“曲率”指曲线或曲面的弯曲程度，与“上表面弯曲大，因而流速快”的因果关系相符。", "色彩": "搭配：“较大”多用于程度或数量，不用来形容色彩的大小，而且色彩与气流流速无关。", "音量": "语义：气流流速与声音大小无关，“因音量较大而流速加快”不成立。", "味道": "语义：味道的浓淡与气流速度无关，不能解释上表面流速加快的原因。"}, "sentence_index": 0, "correct_answer": "曲率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段弧线的曲率有十米。", "explanation": "这里应该用〈弧长〉。曲率描述弯曲程度，单位为每米（1/米），本身不是长度，不能说有多长。"}, {"text": "这个曲面的曲率是三十度。", "explanation": "这里应该用〈角度〉。曲率是数值，不用度数来表示。"}, {"text": "这个圆的曲率是三厘米。", "explanation": "这里应该用〈半径〉。半径是长度，以厘米计量；圆的曲率是半径的倒数，单位为每米，不能用厘米计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12144, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "曲率", "is_correct": true, "explanation": "正确。“计算”的对象是几何量，曲率是曲面弯曲程度的数值，可以计算。"}, {"text": "体温", "is_correct": false, "explanation": "语义：曲面没有体温，数学家不会去计算体温，这一搭配在几何语境中不成立。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“计算”通常用于数值量，颜色不能计算，不说“计算颜色”。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：曲面没有心跳，“计算了这个曲面的心跳”不合逻辑。"}], "explanations": {"曲率": "正确。“计算”的对象是几何量，曲率是曲面弯曲程度的数值，可以计算。", "体温": "语义：曲面没有体温，数学家不会去计算体温，这一搭配在几何语境中不成立。", "颜色": "搭配：“计算”通常用于数值量，颜色不能计算，不说“计算颜色”。", "心跳": "语义：曲面没有心跳，“计算了这个曲面的心跳”不合逻辑。"}, "sentence_index": 6, "correct_answer": "曲率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的曲率是每小时六十公里。", "explanation": "这里应该用〈速率〉。速率表示单位时间内的路程，曲率不表示速度。"}, {"text": "这段路的曲率很陡。", "explanation": "这里应该用〈坡度〉。陡形容坡度或路面的倾斜，曲率是弯曲程度的数值，不能说陡。"}, {"text": "这杯水的曲率很高。", "explanation": "这里应该用〈温度〉。曲率只描述曲线或曲面的弯曲程度，不能用来形容一杯水；水的冷热应说温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个曲面有两条曲率。", "corrected_sentence": "这个曲面有两种曲率。", "error_description": "量词错误：“曲率”是抽象的数值，应该用“种”，不能用“条”。“条”用于线状事物，应改为“这个曲面有两种曲率”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条曲线的曲率越来小。", "corrected_sentence": "这条曲线的曲率越来越小。", "error_description": "程度结构残缺：“越来越”需要两个“越”，应说“越来越小”，不能说“越来小”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12145, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "较小", "is_correct": true, "explanation": "正确。“较小”与“较大”相对，表示程度或数量低于一般或低于对比对象。"}, {"text": "清澈", "is_correct": false, "explanation": "“清澈”形容水或眼神透明，与“较大”的程度或数量义无对应关系。"}, {"text": "温和", "is_correct": false, "explanation": "“温和”形容性情或气候平缓，与“较大”没有相对关系。"}, {"text": "迟缓", "is_correct": false, "explanation": "“迟缓”形容速度慢，与“较大”的程度义不构成反义。"}], "correct_answer": "较小", "explanations": {"较小": "正确。“较小”与“较大”相对，表示程度或数量低于一般或低于对比对象。", "清澈": "“清澈”形容水或眼神透明，与“较大”的程度或数量义无对应关系。", "温和": "“温和”形容性情或气候平缓，与“较大”没有相对关系。", "迟缓": "“迟缓”形容速度慢，与“较大”的程度义不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12145, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "较小", "is_correct": true, "explanation": "正确。“较小”与“较大”相对，表示程度或数量低于一般或对比对象。"}, {"text": "轻松", "is_correct": false, "explanation": "“轻松”形容心情或做事不费力，与“较大”没有相对关系。"}, {"text": "冷淡", "is_correct": false, "explanation": "“冷淡”形容态度，与“较大”的程度义不构成反义。"}, {"text": "干燥", "is_correct": false, "explanation": "“干燥”形容含水少，与“较大”没有相对关系。"}], "correct_answer": "较小", "explanations": {"较小": "正确。“较小”与“较大”相对，表示程度或数量低于一般或对比对象。", "轻松": "“轻松”形容心情或做事不费力，与“较大”没有相对关系。", "冷淡": "“冷淡”形容态度，与“较大”的程度义不构成反义。", "干燥": "“干燥”形容含水少，与“较大”没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12145, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "属性词。用在比较中，表示程度或数量超过一般或超过对比对象。", "primary_collocate": null, "pronunciation": "jiào dà", "ipa": "tɕjɑʊ˥˩ tɑ˥˩", "syllable_count": 2, "sentences": [{"text": "这件衣服的尺寸较大，我穿不了。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家超市的面积较大，东西也很多。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的难度较大，很多人没做完。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的声音较大，后面的人也听得到。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的体积较大，不好停。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年夏天的雨量较大。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市这几年的变化较大。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的压力较大，晚上睡不好。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天风力较大，请大家注意安全。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的水量较大，不能游泳。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "較大", "label": "繁体"}], "register": "中性", "sense_fingerprint": "属性词，表示程度或数量超过一般，如“难度较大”“压力较大”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ea6797-318b-42b7-a7d7-5ecd5fb5d5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12145, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "较大", "is_correct": true, "explanation": "正确。“尺寸较大”表示尺寸超过一般，所以“我穿不了”。"}, {"text": "较甜", "is_correct": false, "explanation": "语义：尺寸不能用甜淡来形容。"}, {"text": "较慢", "is_correct": false, "explanation": "搭配：“尺寸”不说快慢，“较慢”与“尺寸”不搭配。"}, {"text": "较暖", "is_correct": false, "explanation": "语义：尺寸没有冷暖之分，“较暖”与句子语义不符。"}], "explanations": {"较大": "正确。“尺寸较大”表示尺寸超过一般，所以“我穿不了”。", "较甜": "语义：尺寸不能用甜淡来形容。", "较慢": "搭配：“尺寸”不说快慢，“较慢”与“尺寸”不搭配。", "较暖": "语义：尺寸没有冷暖之分，“较暖”与句子语义不符。"}, "sentence_index": 0, "correct_answer": "较大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的颜色较大，我不太喜欢。", "explanation": "这里应该用〈较深〉。颜色的深浅用“深、浅”，“较大”不用来形容颜色。"}, {"text": "这个人的性格较大，常常发脾气。", "explanation": "这里应该用〈较强〉。性格的强弱用“强、弱”描述，“较大”不说性格。"}, {"text": "这块布的质地较大，摸起来很硬。", "explanation": "这里应该用〈较硬〉。质地的软硬用“硬、软”描述，“较大”不说质地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12145, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "较大", "is_correct": true, "explanation": "正确。“变化较大”表示变化的程度超过一般。"}, {"text": "较咸", "is_correct": false, "explanation": "语义：变化不能用咸淡来形容。"}, {"text": "较烫", "is_correct": false, "explanation": "语义：变化没有冷热之分，与句子语义不符。"}, {"text": "较硬", "is_correct": false, "explanation": "搭配：“变化”不说软硬，“较硬”与“变化”不搭配。"}], "explanations": {"较大": "正确。“变化较大”表示变化的程度超过一般。", "较咸": "语义：变化不能用咸淡来形容。", "较烫": "语义：变化没有冷热之分，与句子语义不符。", "较硬": "搭配：“变化”不说软硬，“较硬”与“变化”不搭配。"}, "sentence_index": 6, "correct_answer": "较大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的节奏较大，听起来很快。", "explanation": "这里应该用〈较快〉。节奏的快慢用“快、慢”描述，“较大”不说节奏。"}, {"text": "他的眼神较大，看着很凶。", "explanation": "这里应该用〈较凶〉。眼神用“凶、和”描述，“较大”不说眼神。"}, {"text": "这个盒子的温度较大，摸起来很烫。", "explanation": "这里应该用〈较高〉。温度的高低用“高、低”描述，“较大”不用来形容温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12145, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛的难度很较大，选手们都很紧张。", "corrected_sentence": "这次比赛的难度较大，选手们都很紧张。", "error_description": "程度词重复：“较”已表示程度，不能再与“很”并用。应删去“很”，说“难度较大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12145, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市较大地降雨量，要注意防洪。", "corrected_sentence": "这个城市较大的降雨量，要注意防洪。", "error_description": "结构助词错误：“较大”修饰名词“降雨量”，应用结构助词“的”，说“较大的降雨量”；“地”多用于修饰动词，此处误用，不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
