INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12146, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "流体在单位时间内流过的距离。", "primary_collocate": null, "pronunciation": "liú sù", "ipa": "ljoʊ˧˥ su˥˩", "syllable_count": 2, "sentences": [{"text": "这一过程的核心在于升力的生成机制——机翼上表面的气流因曲率较大而速度加快，导致压力降低；相比之下，下表面的气流流速较慢，压力相对较高。", "target_word": "流速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河道变窄后，水的流速会加快。", "target_word": "流速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河夏天的流速比冬天快。", "target_word": "流速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用仪器测量水管里水的流速。", "target_word": "流速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管子越细，水的流速越大。", "target_word": "流速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "血液的流速变慢时，容易形成血栓。", "target_word": "流速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水库放水时，下游的流速会发生变化。", "target_word": "流速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验中，我们记录了不同位置的流速。", "target_word": "流速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "流速太大，小船很难靠岸。", "target_word": "流速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们算出这根管子里的流速。", "target_word": "流速", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "物理或工程术语，指流体单位时间内流过的距离，如“测量流速”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ea6797-318b-42b7-a7d7-5ecd5fb5d5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12146, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流速", "is_correct": true, "explanation": "正确：“流速”指流体流动的快慢，下表面气流“流速较慢”与上表面气流“速度加快”形成对比。"}, {"text": "流量", "is_correct": false, "explanation": "语义：“流量”指单位时间流过的体积或数量，不表示快慢，不能说“较慢”。"}, {"text": "密度", "is_correct": false, "explanation": "搭配：“密度”说疏密，不能与“较慢”搭配。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”说冷热，不能说气流“较慢”。"}], "explanations": {"流速": "正确：“流速”指流体流动的快慢，下表面气流“流速较慢”与上表面气流“速度加快”形成对比。", "流量": "语义：“流量”指单位时间流过的体积或数量，不表示快慢，不能说“较慢”。", "密度": "搭配：“密度”说疏密，不能与“较慢”搭配。", "温度": "搭配：“温度”说冷热，不能说气流“较慢”。"}, "sentence_index": 0, "correct_answer": "流速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆赛车的流速达到了每小时三百公里。", "explanation": "这里应该用〈速度〉。流速只指水、气体等流体流动的快慢，赛车的快慢要用速度。"}, {"text": "这条水管每秒的流速是十升。", "explanation": "这里应该用〈流量〉。流速说的是流动的快慢，每秒流过多少体积要用流量。"}, {"text": "这家工厂的生产流速安排得很合理。", "explanation": "这里应该用〈流程〉。流速只用于流体的流动快慢，生产的工序和步骤要用流程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12146, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流速", "is_correct": true, "explanation": "正确：水库放水后，下游水的流速会随之改变，“流速”指流动的快慢。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人或事物存在的岁数，下游不能有年龄随放水而变化。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”说人或动物的身体重量，不能用于河段。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：“学费”不能作为“下游”的属性发生变化。"}], "explanations": {"流速": "正确：水库放水后，下游水的流速会随之改变，“流速”指流动的快慢。", "年龄": "语义：“年龄”指人或事物存在的岁数，下游不能有年龄随放水而变化。", "体重": "体貌：“体重”说人或动物的身体重量，不能用于河段。", "学费": "搭配：“学费”不能作为“下游”的属性发生变化。"}, "sentence_index": 6, "correct_answer": "流速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的工作流速很高。", "explanation": "这里应该用〈效率〉。流速只指流体流动的快慢，说机器工作的高低要用效率。"}, {"text": "运动后他的心跳流速明显加快。", "explanation": "这里应该用〈速率〉。流速只用于流体，心跳的快慢要用速率。"}, {"text": "这项工程的流速比计划快。", "explanation": "这里应该用〈进度〉。流速只指流体的快慢，工程推进的快慢要用进度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12146, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "水流过狭窄的地方时，流速会变了快。", "corrected_sentence": "水流过狭窄的地方时，流速会变快。", "error_description": "“了”位置错误：“变快”是“变”加结果补语，中间不能插入“了”，应说“流速会变快”。错误位于目标词“流速”的谓语部分。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12146, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "河道变窄的地方，水的流速明显加强。", "corrected_sentence": "河道变窄的地方，水的流速明显加快。", "error_description": "搭配错误：流速变快应说“加快”，“加强”用于力量、力度，不能用于流速。错误位于目标词“流速”的谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12148, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "动力", "is_correct": true, "explanation": "动力：指推动事物前进的力量，与承受的负担相对，是“压力”在这一义项上的反义词。"}, {"text": "睡眠", "is_correct": false, "explanation": "睡眠：指人的休息状态，与“压力”没有反义关系。"}, {"text": "花园", "is_correct": false, "explanation": "花园：指种植花草的地方，与“压力”没有反义关系。"}, {"text": "书架", "is_correct": false, "explanation": "书架：放书的家具，与“压力”没有反义关系。"}], "correct_answer": "动力", "explanations": {"动力": "动力：指推动事物前进的力量，与承受的负担相对，是“压力”在这一义项上的反义词。", "睡眠": "睡眠：指人的休息状态，与“压力”没有反义关系。", "花园": "花园：指种植花草的地方，与“压力”没有反义关系。", "书架": "书架：放书的家具，与“压力”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12148, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "动力", "is_correct": true, "explanation": "动力：指推动事物前进的力量，与承受的负担相对，是“压力”在这一义项上的反义词。"}, {"text": "海洋", "is_correct": false, "explanation": "海洋：指广阔的咸水区域，与“压力”没有反义关系。"}, {"text": "树叶", "is_correct": false, "explanation": "树叶：指树上长出的扁平器官，与“压力”没有反义关系。"}, {"text": "课本", "is_correct": false, "explanation": "课本：指供学习用的书，与“压力”没有反义关系。"}], "correct_answer": "动力", "explanations": {"动力": "动力：指推动事物前进的力量，与承受的负担相对，是“压力”在这一义项上的反义词。", "海洋": "海洋：指广阔的咸水区域，与“压力”没有反义关系。", "树叶": "树叶：指树上长出的扁平器官，与“压力”没有反义关系。", "课本": "课本：指供学习用的书，与“压力”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12148, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指承受的负担或紧张状态。", "primary_collocate": null, "pronunciation": "yā lì", "ipa": "ja˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "长期的压力会影响健康。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作压力太大，他晚上睡不好。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试以前，同学们的压力都很大。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天都要面对很多压力。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动可以帮你减轻压力。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没有给我们压力，只是鼓励我们。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在压力下做出了决定。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸最近压力很大，常常叹气。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对压力，要学会放松自己。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听音乐能缓解压力。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "壓力", "label": "繁体"}], "register": "中性", "sense_fingerprint": "承受的负担、紧张状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814f0f11-8914-4749-b4fd-b94e137a1f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12148, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "压力", "is_correct": true, "explanation": "压力：指长期承受的负担或紧张状态，与“影响健康”相符。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“长期的速度”不成立，速度不是会影响健康的事物。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不会长期影响健康，与句意不符。"}, {"text": "面积", "is_correct": false, "explanation": "语义：面积不会长期影响健康，与句意不符。"}], "explanations": {"压力": "压力：指长期承受的负担或紧张状态，与“影响健康”相符。", "速度": "搭配：“长期的速度”不成立，速度不是会影响健康的事物。", "颜色": "语义：颜色不会长期影响健康，与句意不符。", "面积": "语义：面积不会长期影响健康，与句意不符。"}, "sentence_index": 0, "correct_answer": "压力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今天的压力很好，一口气跑了十公里。", "explanation": "这里应该用〈体力〉。“压力”指承受的负担或紧张状态，不指身体的力气；说身体的力气要用“体力”。"}, {"text": "这道菜的压力太咸了，几乎没法吃。", "explanation": "这里应该用〈味道〉。“压力”指承受的负担或紧张状态，不指食物的口味；说口味要用“味道”。"}, {"text": "这辆车的压力很快，一下子就超过了前车。", "explanation": "这里应该用〈速度〉。“压力”指承受的负担或紧张状态，不指车的快慢；说车的快慢要用“速度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12148, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "压力", "is_correct": true, "explanation": "压力：指人在紧张或负担之下的状态，与“做出决定”的语境相符。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：“在…下”后接的是状态或条件，“音量”不能作为做决定的条件。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不能作为做决定的条件，与句中的心理状态不符。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包与“做出决定”无关，不能作为条件。"}], "explanations": {"压力": "压力：指人在紧张或负担之下的状态，与“做出决定”的语境相符。", "音量": "搭配：“在…下”后接的是状态或条件，“音量”不能作为做决定的条件。", "花朵": "语义：花朵不能作为做决定的条件，与句中的心理状态不符。", "面包": "语义：面包与“做出决定”无关，不能作为条件。"}, "sentence_index": 6, "correct_answer": "压力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把压力从书架上搬了下来，放在桌子上。", "explanation": "这里应该用〈书〉。“压力”指承受的负担或紧张状态，是抽象的，不是能搬动的实物；要说搬东西，应该换成“书”。"}, {"text": "这块布的压力很厚，可以做冬衣。", "explanation": "这里应该用〈厚度〉。“压力”指承受的负担或紧张状态，不指布的厚薄；说布的厚薄要用“厚度”。"}, {"text": "这首歌的压力很优美，我反复听了好几遍。", "explanation": "这里应该用〈旋律〉。“压力”指承受的负担或紧张状态，不指歌曲的旋律；说歌曲的好听之处要用“旋律”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12148, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他感到一只很大的压力。", "corrected_sentence": "他感到一股很大的压力。", "error_description": "量词错误：“压力”是抽象名词，应该用“股”（一股压力），不能用“只”（“只”多用于动物或成对的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12148, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有很压力，常常睡不好。", "corrected_sentence": "他有很大的压力，常常睡不好。", "error_description": "错误：“很”是副词，不能直接修饰名词“压力”，应加形容词“大”，写作“很大的压力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
