INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12149, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "表示通过对比来显示两者之间的差异或优劣。", "primary_collocate": null, "pronunciation": "xiāng bǐ zhī xià", "ipa": "ɕiaŋ˥ pi˨˩ ʈʂɻ̩˥ ɕia˥˩", "syllable_count": 4, "sentences": [{"text": "这一过程的核心在于升力的生成机制——机翼上表面的气流因曲率较大而流速加快，导致压力降低；相比之下，下表面的气流流速较慢，压力相对较高。", "target_word": "相比之下", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "哥哥很爱说话，相比之下，弟弟安静多了。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜很贵，相比之下，那家便宜多了。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京的冬天很冷，相比之下，广州暖和得多。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家离学校很远，相比之下，他家近多了。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐火车要八个小时，相比之下，坐飞机只要两个小时。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王每天跑步，相比之下，我运动得太少了。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机很旧，相比之下，那个新多了。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年夏天很热，相比之下，今年凉快一些。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩一般，相比之下，姐姐的成绩好得多。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "放在后一分句开头，通过对比显示两者的差异或优劣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814f0f11-8914-4749-b4fd-b94e137a1f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12149, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相比之下", "is_correct": true, "explanation": "相比之下：引出后一分句，与前面的内容对比，指出上下表面压力的差异。"}, {"text": "首先", "is_correct": false, "explanation": "语义：“首先”表示先后次序的开端，句中是两种气流的对比，不是次序。"}, {"text": "例如", "is_correct": false, "explanation": "语义：“例如”引出举例说明，句中并非举例。"}, {"text": "总之", "is_correct": false, "explanation": "语义：“总之”用于总结前文，句中是在对比两侧的流速与压力，并非总结。"}], "explanations": {"相比之下": "相比之下：引出后一分句，与前面的内容对比，指出上下表面压力的差异。", "首先": "语义：“首先”表示先后次序的开端，句中是两种气流的对比，不是次序。", "例如": "语义：“例如”引出举例说明，句中并非举例。", "总之": "语义：“总之”用于总结前文，句中是在对比两侧的流速与压力，并非总结。"}, "sentence_index": 0, "correct_answer": "相比之下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我先去超市，相比之下，再去书店。", "explanation": "这里应该用〈然后〉。前后只是先后顺序，没有可以比较的两者，不用“相比之下”。"}, {"text": "天气突然变冷，相比之下，我们取消了郊游。", "explanation": "这里应该用〈因此〉。前后是因果关系，不是比较两者的差异。"}, {"text": "我买了苹果，相比之下，还买了香蕉。", "explanation": "这里应该用〈此外〉。前后是并列补充，没有可以比较的两者，不用“相比之下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12149, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相比之下", "is_correct": true, "explanation": "相比之下：引出后一分句，与前面的小王和我的情况对比，指出运动量的差别。"}, {"text": "因而", "is_correct": false, "explanation": "语义：“因而”表示因果，句中前后是对比，不是结果。"}, {"text": "从而", "is_correct": false, "explanation": "语义：“从而”表示由此达到的结果，与前后的对比关系不符。"}, {"text": "由此", "is_correct": false, "explanation": "语域：“由此”偏书面，表示推断，与口语叙述不符，也不表示对比。"}], "explanations": {"相比之下": "相比之下：引出后一分句，与前面的小王和我的情况对比，指出运动量的差别。", "因而": "语义：“因而”表示因果，句中前后是对比，不是结果。", "从而": "语义：“从而”表示由此达到的结果，与前后的对比关系不符。", "由此": "语域：“由此”偏书面，表示推断，与口语叙述不符，也不表示对比。"}, "sentence_index": 6, "correct_answer": "相比之下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "相比之下，他先去了银行。", "explanation": "这里应该用〈首先〉。句首没有可以比较的前文，这里只是先后顺序。"}, {"text": "我们吃完午饭，相比之下，去看了电影。", "explanation": "这里应该用〈接着〉。前后是先后动作，不是比较两件事。"}, {"text": "他每天练琴，相比之下，手指都起了茧。", "explanation": "这里应该用〈结果〉。前后是因果关系，不是比较两者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12149, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影很长，相比之下了，那部短得多。", "corrected_sentence": "这部电影很长，相比之下，那部短得多。", "error_description": "词语后附错误：“相比之下”是连词，后面不能加“了”，应去掉“了”，写作“相比之下，”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12149, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天早起，相比之下的，我起得太晚了。", "corrected_sentence": "他每天早起，相比之下，我起得太晚了。", "error_description": "词语后附错误：“相比之下”是连词，后面不能加“的”，应去掉“的”，写作“相比之下，”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12150, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "较快", "is_correct": true, "explanation": "「较快」与「较慢」在速度义项上互为反义。"}, {"text": "明亮", "is_correct": false, "explanation": "「明亮」形容光线，与「较慢」的速度义无关，不构成反义。"}, {"text": "温暖", "is_correct": false, "explanation": "「温暖」形容温度或感受，与「较慢」的速度义无关，不构成反义。"}, {"text": "宽大", "is_correct": false, "explanation": "「宽大」形容面积或空间，与「较慢」的速度义无关，不构成反义。"}], "correct_answer": "较快", "explanations": {"较快": "「较快」与「较慢」在速度义项上互为反义。", "明亮": "「明亮」形容光线，与「较慢」的速度义无关，不构成反义。", "温暖": "「温暖」形容温度或感受，与「较慢」的速度义无关，不构成反义。", "宽大": "「宽大」形容面积或空间，与「较慢」的速度义无关，不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12150, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "较快", "is_correct": true, "explanation": "「较快」与「较慢」在速度义项上互为反义。"}, {"text": "坚硬", "is_correct": false, "explanation": "「坚硬」形容物体质地，与「较慢」的速度义无关，不构成反义。"}, {"text": "粗糙", "is_correct": false, "explanation": "「粗糙」形容表面质地，与「较慢」的速度义无关，不构成反义。"}, {"text": "严厉", "is_correct": false, "explanation": "「严厉」形容态度，与「较慢」的速度义无关，不构成反义。"}], "correct_answer": "较快", "explanations": {"较快": "「较快」与「较慢」在速度义项上互为反义。", "坚硬": "「坚硬」形容物体质地，与「较慢」的速度义无关，不构成反义。", "粗糙": "「粗糙」形容表面质地，与「较慢」的速度义无关，不构成反义。", "严厉": "「严厉」形容态度，与「较慢」的速度义无关，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12150, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示速度或频率低于一般水平，即不快。", "primary_collocate": null, "pronunciation": "jiào màn", "ipa": "tɕjɑʊ˥˩ man˥˩", "syllable_count": 2, "sentences": [{"text": "这一过程的核心在于升力的生成机制——机翼上表面的气流因曲率较大而流速加快，导致压力降低；相比之下，下表面的气流流速较慢，压力相对较高。", "target_word": "较慢", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这条路上车很多，车速较慢。", "target_word": "较慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人走路的速度较慢。", "target_word": "较慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的网速较慢，看视频要等很久。", "target_word": "较慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话的语速较慢，我听得懂。", "target_word": "较慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共汽车的速度较慢，但是票价便宜。", "target_word": "较慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学骑车的进度较慢，要多练习。", "target_word": "较慢", "complexity_tier": "T3", "furigana": "tā xué qí chē de jìndù jiào màn, yào duō liànxí。", "sentence_source": "generated"}, {"text": "下雨天，路上的车速都较慢。", "target_word": "较慢", "complexity_tier": "T3", "furigana": "xià yǔ tiān, lù shang de chēsù dōu jiào màn。", "sentence_source": "generated"}, {"text": "这种植物的生长速度较慢，一年只长几厘米。", "target_word": "较慢", "complexity_tier": "T3", "furigana": "zhè zhǒng zhíwù de shēngzhǎng sùdù jiào màn, yì nián zhǐ zhǎng jǐ lí mǐ。", "sentence_source": "generated"}, {"text": "今天的电脑运行较慢，可能需要重新开机。", "target_word": "较慢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "速度或频率比一般水平低，不快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814f0f11-8914-4749-b4fd-b94e137a1f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12150, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "较慢", "is_correct": true, "explanation": "较慢（jiào màn）指速度或频率低于一般水平，即不快。"}, {"text": "叫卖", "is_correct": false, "explanation": "mài（第四声）与 màn（第四声）韵母不同，意思是沿街吆喝着卖东西。"}, {"text": "叫骂", "is_correct": false, "explanation": "mà 比 màn 少了鼻音 n，意思是大声骂人。"}, {"text": "浇满", "is_correct": false, "explanation": "jiāo（第一声）与 jiào（第四声）、mǎn（第三声）与 màn（第四声）声调不同，意思是把东西倒到满。"}, {"text": "娇蛮", "is_correct": false, "explanation": "jiāo 与 jiào、mán 与 màn 声调不同，意思是娇惯而蛮横。"}], "explanations": {"较慢": "较慢（jiào màn）指速度或频率低于一般水平，即不快。", "叫卖": "mài（第四声）与 màn（第四声）韵母不同，意思是沿街吆喝着卖东西。", "叫骂": "mà 比 màn 少了鼻音 n，意思是大声骂人。", "浇满": "jiāo（第一声）与 jiào（第四声）、mǎn（第三声）与 màn（第四声）声调不同，意思是把东西倒到满。", "娇蛮": "jiāo 与 jiào、mán 与 màn 声调不同，意思是娇惯而蛮横。"}, "sentence_index": null, "correct_answer": "较慢"}, "level_3": {"options": [{"text": "较慢", "is_correct": true, "explanation": "「较慢」指下表面流速低于上表面，与「加快」形成对比，才能推出压力较高的结论。"}, {"text": "较快", "is_correct": false, "explanation": "语义：「较快」与上表面「流速加快」同向，无法与「相比之下」构成对比，也与压力较高的结论矛盾。"}, {"text": "猛烈", "is_correct": false, "explanation": "搭配：「猛烈」多用于风、火等，不说「流速猛烈」，描述流速用快、慢。"}, {"text": "急促", "is_correct": false, "explanation": "搭配：「急促」形容呼吸、节奏，不用于描述气流的速度。"}], "explanations": {"较慢": "「较慢」指下表面流速低于上表面，与「加快」形成对比，才能推出压力较高的结论。", "较快": "语义：「较快」与上表面「流速加快」同向，无法与「相比之下」构成对比，也与压力较高的结论矛盾。", "猛烈": "搭配：「猛烈」多用于风、火等，不说「流速猛烈」，描述流速用快、慢。", "急促": "搭配：「急促」形容呼吸、节奏，不用于描述气流的速度。"}, "sentence_index": 0, "correct_answer": "较慢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间的温度较慢，需要多开一会儿空调。", "explanation": "这里应该用〈较低〉。「较慢」只说速度或频率，温度高低要用「较低」。"}, {"text": "参加活动的人数较慢，只有几个同学来。", "explanation": "这里应该用〈较少〉。「较慢」不能形容人数，人数多少要用「较少」。"}, {"text": "他到达会场的时间较慢，错过了开幕式。", "explanation": "这里应该用〈较晚〉。「较慢」形容速度，到达早晚要用「较晚」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12150, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "较慢", "is_correct": true, "explanation": "「较慢」说学习进度比一般慢，与「要多练习」前后呼应。"}, {"text": "熟练", "is_correct": false, "explanation": "搭配：「熟练」形容技能，不用来修饰「进度」。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：「轻松」与「要多练习」相矛盾，学骑车的进度不会是轻松的。"}, {"text": "高超", "is_correct": false, "explanation": "搭配：「高超」形容技艺水平，不说「进度高超」。"}], "explanations": {"较慢": "「较慢」说学习进度比一般慢，与「要多练习」前后呼应。", "熟练": "搭配：「熟练」形容技能，不用来修饰「进度」。", "轻松": "语义：「轻松」与「要多练习」相矛盾，学骑车的进度不会是轻松的。", "高超": "搭配：「高超」形容技艺水平，不说「进度高超」。"}, "sentence_index": 6, "correct_answer": "较慢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个城市之间的距离较慢，坐高铁要两个小时。", "explanation": "这里应该用〈较远〉。「较慢」形容速度，距离远近要用「较远」。"}, {"text": "这件衣服的价格较慢，我买不起。", "explanation": "这里应该用〈较高〉。「较慢」不能形容价格，价格高低要用「较高」。"}, {"text": "我的体重较慢，应该多运动。", "explanation": "这里应该用〈较重〉。「较慢」只说速度或频率，体重轻重要用「较重」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12150, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次行军的速度很较慢，大家都很累。", "corrected_sentence": "这次行军的速度较慢，大家都很累。", "error_description": "「较慢」已含「较」表示比较程度，不能再受「很」修饰，应去掉「很」，写作「速度较慢」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12150, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师讲较慢，同学们都能跟上。", "corrected_sentence": "老师讲得较慢，同学们都能跟上。", "error_description": "动词「讲」后面带补语「较慢」时，要用「得」连接，应写作「讲得较慢」，不能省略「得」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
