INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12155, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12155, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "定理是指经过数学或逻辑推理证明为正确的命题或公式，通常作为进一步推理的基础。", "primary_collocate": null, "pronunciation": "dìng lǐ", "ipa": "tiŋ˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "根据伯努利定理，流体速度的增加必然伴随着静压的减小，这为升力提供了经典物理解释。", "target_word": "定理", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "数学家花了十年才证明这条定理。", "target_word": "定理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个定理的证明很长，学生看不懂。", "target_word": "定理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师先讲定理，再讲怎么用它做题。", "target_word": "定理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "数学书里有很多定理，要一个一个记住。", "target_word": "定理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个定理可以用来算三角形的边长。", "target_word": "定理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用已经证明的定理，一步一步推出了答案。", "target_word": "定理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有经过证明，一个命题才能成为定理。", "target_word": "定理", "complexity_tier": "T3", "furigana": "zhǐ yǒu jīng guò zhèng míng, yí gè mìng tí cái néng chéng wéi dìng lǐ。", "sentence_source": "generated"}, {"text": "课上老师让我们自己证明这条定理。", "target_word": "定理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位数学家发现了一条很有名的定理。", "target_word": "定理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "书面语", "sense_fingerprint": "数学或逻辑中经证明为正确、可作推理基础的命题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4770717-0209-4e9c-bf03-9225dfd413b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12155, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "定理", "is_correct": true, "explanation": "正确答案：定理（dìng lǐ），指经证明为正确的命题。"}, {"text": "地理", "is_correct": false, "explanation": "dì lǐ 与 dìng lǐ 的第一个音节不同：dì 没有韵尾 ng，意思是地理。"}, {"text": "病理", "is_correct": false, "explanation": "bìng lǐ 与 dìng lǐ 的第一个音节声母不同：b 与 d，意思是病理。"}, {"text": "定力", "is_correct": false, "explanation": "dìng lì 与 dìng lǐ 的第二个音节声调不同：lì（第四声）与 lǐ（第三声），意思是定力。"}], "explanations": {"定理": "正确答案：定理（dìng lǐ），指经证明为正确的命题。", "地理": "dì lǐ 与 dìng lǐ 的第一个音节不同：dì 没有韵尾 ng，意思是地理。", "病理": "bìng lǐ 与 dìng lǐ 的第一个音节声母不同：b 与 d，意思是病理。", "定力": "dìng lì 与 dìng lǐ 的第二个音节声调不同：lì（第四声）与 lǐ（第三声），意思是定力。"}, "sentence_index": null, "correct_answer": "定理"}, "level_3": {"options": [{"text": "定理", "is_correct": true, "explanation": "正确答案：定理。伯努利定理是经证明的物理规律，与后文流速和静压的关系相合。"}, {"text": "材料", "is_correct": false, "explanation": "语义：材料指制作物品的原料，“伯努利材料”不是可作为推理依据的道理。"}, {"text": "口号", "is_correct": false, "explanation": "语义：口号是宣传用的标语，不能作为以伯努利命名的科学规律。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“根据”后接的应是可推出结论的道理，“伯努利的名字”无法推出流速与静压的关系。"}], "explanations": {"定理": "正确答案：定理。伯努利定理是经证明的物理规律，与后文流速和静压的关系相合。", "材料": "语义：材料指制作物品的原料，“伯努利材料”不是可作为推理依据的道理。", "口号": "语义：口号是宣传用的标语，不能作为以伯努利命名的科学规律。", "名字": "搭配：“根据”后接的应是可推出结论的道理，“伯努利的名字”无法推出流速与静压的关系。"}, "sentence_index": 0, "correct_answer": "定理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的定理很好听。", "explanation": "这里应该用〈旋律〉。定理是经证明的数学或逻辑命题；乐曲的音调进行应说旋律。"}, {"text": "这些是数学的定理，不需要证明。", "explanation": "这里应该用〈公理〉。公理是不需证明即被接受的起点，定理必须经过证明，所以不能说不需要证明。"}, {"text": "他做了很多次实验，最后得出了一个定理，却没有任何推导过程。", "explanation": "这里应该用〈结论〉。定理必须经过推理证明；只凭实验得出、没有推导的判断应说结论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12155, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "定理", "is_correct": true, "explanation": "正确答案：定理（dìng lǐ），指经证明为正确的命题。"}, {"text": "命理", "is_correct": false, "explanation": "mìng lǐ 与 dìng lǐ 的第一个音节声母不同：m 与 d，意思是命理。"}, {"text": "地里", "is_correct": false, "explanation": "dì lǐ 与 dìng lǐ 的第一个音节韵尾不同：dì 没有 ng，意思是地里。"}, {"text": "订立", "is_correct": false, "explanation": "dìng lì 与 dìng lǐ 的第二个音节声调不同：lì（第四声）与 lǐ（第三声），意思是订立。"}], "explanations": {"定理": "正确答案：定理（dìng lǐ），指经证明为正确的命题。", "命理": "mìng lǐ 与 dìng lǐ 的第一个音节声母不同：m 与 d，意思是命理。", "地里": "dì lǐ 与 dìng lǐ 的第一个音节韵尾不同：dì 没有 ng，意思是地里。", "订立": "dìng lì 与 dìng lǐ 的第二个音节声调不同：lì（第四声）与 lǐ（第三声），意思是订立。"}, "sentence_index": null, "correct_answer": "定理"}, "level_3": {"options": [{"text": "定理", "is_correct": true, "explanation": "正确答案：定理。“已经证明的定理”可以用来一步步推出答案。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是用具，不是可以被证明的命题，无法作为推导的依据。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“证明的”只修饰命题、结论等，不能修饰乐器。"}, {"text": "盘子", "is_correct": false, "explanation": "语义：盘子是器皿，与“证明”和“推出答案”毫无关系。"}], "explanations": {"定理": "正确答案：定理。“已经证明的定理”可以用来一步步推出答案。", "雨伞": "语义：雨伞是用具，不是可以被证明的命题，无法作为推导的依据。", "乐器": "搭配：“证明的”只修饰命题、结论等，不能修饰乐器。", "盘子": "语义：盘子是器皿，与“证明”和“推出答案”毫无关系。"}, "sentence_index": 6, "correct_answer": "定理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "科学家提出了一个新的定理，这个定理后来被证明是错的。", "explanation": "这里应该用〈假说〉。定理经证明必定正确；后来被推翻的设想应说假说。"}, {"text": "这本词典给出了“数学”的一个很清楚的定理。", "explanation": "这里应该用〈定义〉。定义是解释词语含义的文字，定理是经证明的命题。"}, {"text": "这盆花的定理很香，大家都喜欢闻。", "explanation": "这里应该用〈香气〉。定理是经证明的命题，花的香味不能说成定理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12155, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们今天证明了一本新的定理。", "corrected_sentence": "我们今天证明了一条新的定理。", "error_description": "“一本定理”错，应为“一条定理”。定理不是书，量词用“条”或“个”，不用“本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12155, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师讲了这块定理。", "corrected_sentence": "老师讲了这条定理。", "error_description": "“这块定理”错，应为“这条定理”。定理不是块状物，量词用“条”或“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
