INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12156, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "液体和气体的统称，没有固定形状，容易流动。", "primary_collocate": null, "pronunciation": "liú tǐ", "ipa": "ljou˧˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "根据伯努利定理，流体速度的增加必然伴随着静压的减小，这为升力提供了经典物理解释。", "target_word": "流体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "水和空气都是流体。", "target_word": "流体", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "流体可以流动，也没有固定的形状。", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "液体和气体合起来叫流体。", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空气是一种看不见的流体。", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机在流体里飞行，会受到力的影响。", "target_word": "流体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "流体流得越快，压力就越小。", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学物理时，我们先学流体的特点。", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜂蜜是流动得很慢的流体。", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管子里的流体从左边流到右边。", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "流體", "label": "繁体"}], "register": "书面", "sense_fingerprint": "流体：液体和气体的统称，没有固定形状", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7412a05a-d680-454d-90b7-9bb1efc71a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12156, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "固体", "is_correct": false, "explanation": "语义：固体没有流动性，伯努利定理只适用于流动的流体，“固体速度”无法与静压联系。"}, {"text": "流体", "is_correct": true, "explanation": "正确。伯努利定理描述的是液体和气体的流动，流体速度与静压的关系只对流体成立。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度与流速无关，“温度速度”说不通，也无法与静压建立伯努利式的联系。"}, {"text": "电流", "is_correct": false, "explanation": "搭配：“静压”是流体内部压力的概念，电流不与之搭配，电流的大小说“强度”。"}], "explanations": {"固体": "语义：固体没有流动性，伯努利定理只适用于流动的流体，“固体速度”无法与静压联系。", "流体": "正确。伯努利定理描述的是液体和气体的流动，流体速度与静压的关系只对流体成立。", "温度": "语义：温度与流速无关，“温度速度”说不通，也无法与静压建立伯努利式的联系。", "电流": "搭配：“静压”是流体内部压力的概念，电流不与之搭配，电流的大小说“强度”。"}, "sentence_index": 0, "correct_answer": "流体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天要喝够两升流体。", "explanation": "这里应该用〈液体〉。流体指液体和气体的统称，说“喝”的时候只用〈液体〉或〈水〉。"}, {"text": "这张桌子是用流体做的，可以放很多书。", "explanation": "这里应该用〈木头〉。流体能流动、没有固定形状，做桌子的材料要用〈木头〉这类固体。"}, {"text": "妈妈在厨房里把流体切成了小块。", "explanation": "这里应该用〈豆腐〉。流体没有固定形状，不能切成小块；能切的食材要用〈豆腐〉这类固体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12156, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头是固体，不会流动，“石头流得越快”说不通。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁是固态金属，不能说“流得越快”，与压力的变化也无关。"}, {"text": "光线", "is_correct": false, "explanation": "搭配：光线说“传播”，不说“流得越快”，与“压力就越小”也不搭配。"}, {"text": "流体", "is_correct": true, "explanation": "正确。流体能够流动，流速越快，静压越小，这正是伯努利原理的内容。"}], "explanations": {"石头": "语义：石头是固体，不会流动，“石头流得越快”说不通。", "钢铁": "语义：钢铁是固态金属，不能说“流得越快”，与压力的变化也无关。", "光线": "搭配：光线说“传播”，不说“流得越快”，与“压力就越小”也不搭配。", "流体": "正确。流体能够流动，流速越快，静压越小，这正是伯努利原理的内容。"}, "sentence_index": 6, "correct_answer": "流体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种流体很硬，能做成锋利的刀。", "explanation": "这里应该用〈金属〉。流体能流动、没有固定形状，不能说“很硬”，也做不成有固定形状的刀，这类材料要用〈金属〉。"}, {"text": "他用剪刀把流体剪成了两段。", "explanation": "这里应该用〈绳子〉。流体没有固定形状，不能用剪刀剪断；能剪断的东西要用〈绳子〉这类有形的材料。"}, {"text": "我用手能抓起流体，堆成一座小沙堆。", "explanation": "这里应该用〈沙子〉。流体会流动，抓不起来，能堆成沙堆的颗粒要用〈沙子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个锅里的糖浆是一种流动得很慢流体。", "corrected_sentence": "那个锅里的糖浆是一种流动得很慢的流体。", "error_description": "错误：“流动得很慢”修饰“流体”时，中间要加结构助词“的”，应说“流动得很慢的流体”。漏掉“的”，定语与中心词之间没有连接，句子不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "实验室的架子上放着几种流体们，都能流动。", "corrected_sentence": "实验室的架子上放着几种流体，都能流动。", "error_description": "错误：“几种”已经表示数量，“流体”是物质名词，后面不能再加“们”，应说“几种流体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12158, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12158, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12158, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "指事物发展确定不移，不可避免。", "primary_collocate": null, "pronunciation": "bì rán", "ipa": "pi˥˩ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "根据伯努利定理，流体速度的增加必然伴随着静压的减小，这为升力提供了经典物理解释。", "target_word": "必然", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "努力学习，必然会有好成绩。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气越来越冷，树叶必然会掉下来。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不吃早饭，上午必然会觉得饿。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济发展必然带来环境问题。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一直不锻炼，身体必然会变差。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人越多，声音必然越大。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车越来越多，路上必然会堵车。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天熬夜，第二天必然没有精神。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天过后，夏天必然会来。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "必然性", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物发展确定不移，一定会出现某种结果，无法避免", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814f0f11-8914-4749-b4fd-b94e137a1f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12158, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必然", "is_correct": true, "explanation": "「必然」表示事物发展确定不移，符合伯努利定理的结论。"}, {"text": "偶然", "is_correct": false, "explanation": "语义：「偶然」指偶尔发生，与定理所说的必然关系相矛盾。"}, {"text": "或许", "is_correct": false, "explanation": "语义：「或许」表示不确定，与「经典物理解释」的确定结论矛盾。"}, {"text": "断然", "is_correct": false, "explanation": "搭配：「断然」多用于拒绝、否定等决断语境，不修饰「伴随」这类客观关系。"}], "explanations": {"必然": "「必然」表示事物发展确定不移，符合伯努利定理的结论。", "偶然": "语义：「偶然」指偶尔发生，与定理所说的必然关系相矛盾。", "或许": "语义：「或许」表示不确定，与「经典物理解释」的确定结论矛盾。", "断然": "搭配：「断然」多用于拒绝、否定等决断语境，不修饰「伴随」这类客观关系。"}, "sentence_index": 0, "correct_answer": "必然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你必然早点回家，不要在外面玩。", "explanation": "这里应该用〈必须〉。「必然」说客观规律的必定，不表示对人的要求或命令。"}, {"text": "我希望你必然通过这次考试。", "explanation": "这里应该用〈一定〉。「必然」说不以人的意志为转移的结果，不能用来表达愿望。"}, {"text": "我们在街上必然遇见了老同学。", "explanation": "这里应该用〈偶然〉。「必然」指必定会发生，偶然相遇是意外，不能说「必然遇见」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "必然", "is_correct": true, "explanation": "「必然」表示必定如此，符合「人越多，声音越大」的规律。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔」表示不常发生，与「越……越」所说的规律性相矛盾。"}, {"text": "猛然", "is_correct": false, "explanation": "搭配：「猛然」表示突然发生，不用于「越……越」这类渐变句式。"}, {"text": "顺便", "is_correct": false, "explanation": "搭配：「顺便」表示附带做事，不能修饰「声音越大」的变化。"}], "explanations": {"必然": "「必然」表示必定如此，符合「人越多，声音越大」的规律。", "偶尔": "语义：「偶尔」表示不常发生，与「越……越」所说的规律性相矛盾。", "猛然": "搭配：「猛然」表示突然发生，不用于「越……越」这类渐变句式。", "顺便": "搭配：「顺便」表示附带做事，不能修饰「声音越大」的变化。"}, "sentence_index": 6, "correct_answer": "必然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他也许必然会来。", "explanation": "这里应该用〈可能〉。「必然」表示事理上确定不移，不能用于说不确定的情况，表示可能性要用「可能」。"}, {"text": "我必然喜欢这个颜色。", "explanation": "这里应该用〈肯定〉。「必然」说客观规律的必然，不用于表达个人喜好。"}, {"text": "我们每个星期必然打一次球。", "explanation": "这里应该用〈经常〉。「必然」表示必定发生的结果，不表示次数或习惯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "只要每天练习，你的发音会必然进步。", "corrected_sentence": "只要每天练习，你的发音必然进步。", "error_description": "「会」不能放在副词「必然」之前，应写作「发音必然进步」（或「必然会进步」，此时「会」在「必然」之后），不能写成「会必然进步」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "不遵守交通规则，事故很必然会发生。", "corrected_sentence": "不遵守交通规则，事故必然会发生。", "error_description": "副词「必然」不能受「很」修饰，应去掉「很」，写作「事故必然会发生」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
