INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12160, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12160, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "静压指流体在静止状态下施加的压力，即单位面积上受到的垂直作用力。", "primary_collocate": null, "pronunciation": "jìng yā", "ipa": "tɕiŋ˥˩ ja˥˥", "syllable_count": 2, "sentences": [{"text": "根据伯努利定理，流体速度的增加必然伴随着静压的减小，这为升力提供了经典物理解释。", "target_word": "静压", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "管道里水的静压是用压力表测出来的。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "流体静止时，静压等于单位面积上受的力。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水越深，底部的静压越大。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "静压和动压加起来叫总压。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师在管壁上测量流体的静压。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气流得快，静压就会变小。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根水管的静压是两个大气压。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "静压的大小和水的深度有关。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机机翼上方的静压比下方低。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "静压力", "label": "复合"}], "register": "书面", "sense_fingerprint": "流体静止时单位面积上的垂直压力（物理术语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7412a05a-d680-454d-90b7-9bb1efc71a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12160, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "静压", "is_correct": true, "explanation": "正确：静压指流体静止时单位面积上的垂直压力。"}, {"text": "静雅", "is_correct": false, "explanation": "jìng yǎ（第三声）与 jìng yā（第一声）末字声调不同，意思是安静文雅。"}, {"text": "惊讶", "is_correct": false, "explanation": "jīng yà 与 jìng yā 两字声调都不同，意思是对意外的事感到吃惊。"}, {"text": "精雅", "is_correct": false, "explanation": "jīng yǎ 与 jìng yā 两字声调都不同，意思是精致优雅。"}, {"text": "惊呀", "is_correct": false, "explanation": "jīng yā（第一声）与 jìng yā（第四声）首字声调不同，意思是惊叹的声音。"}], "explanations": {"静压": "正确：静压指流体静止时单位面积上的垂直压力。", "静雅": "jìng yǎ（第三声）与 jìng yā（第一声）末字声调不同，意思是安静文雅。", "惊讶": "jīng yà 与 jìng yā 两字声调都不同，意思是对意外的事感到吃惊。", "精雅": "jīng yǎ 与 jìng yā 两字声调都不同，意思是精致优雅。", "惊呀": "jīng yā（第一声）与 jìng yā（第四声）首字声调不同，意思是惊叹的声音。"}, "sentence_index": null, "correct_answer": "静压"}, "level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与流体的速度和压力无关，无法解释升力。"}, {"text": "静压", "is_correct": true, "explanation": "正确：静压是流体的压力，速度增加时随之减小，符合伯努利定理。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”是人，不是流体的物理量，不能“减小”。"}, {"text": "屁股", "is_correct": false, "explanation": "语域：“屁股”是口语，与书面的物理说明不协调，也不指流体的量。"}], "explanations": {"颜色": "语义：“颜色”与流体的速度和压力无关，无法解释升力。", "静压": "正确：静压是流体的压力，速度增加时随之减小，符合伯努利定理。", "老师": "语义：“老师”是人，不是流体的物理量，不能“减小”。", "屁股": "语域：“屁股”是口语，与书面的物理说明不协调，也不指流体的量。"}, "sentence_index": 0, "correct_answer": "静压"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这阵大风的静压很猛。", "explanation": "这里应该用〈动压〉。动压指流动的空气或液体产生的冲击压力，风吹来的猛劲属于动压；静压指流体静止时的压力，不能形容冲击的猛烈。"}, {"text": "他心里感到很大的静压。", "explanation": "这里应该用〈压力〉。静压是流体物理学上的压力，不能用来指人的心理压力。"}, {"text": "这根管子里的水的静压很烫。", "explanation": "这里应该用〈温度〉。静压是流体静止时的压力，不能用来说冷热；水的冷热要用温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "白天", "is_correct": false, "explanation": "语义：白天与空气流速无关，句意不通。"}, {"text": "静压", "is_correct": true, "explanation": "正确：空气流得快，流体的静压就会减小。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木不是流体的物理量，空气流得快不会使树木“变小”。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，与书面的物理叙述不符，也不指压力。"}], "explanations": {"白天": "语义：白天与空气流速无关，句意不通。", "静压": "正确：空气流得快，流体的静压就会减小。", "树木": "语义：树木不是流体的物理量，空气流得快不会使树木“变小”。", "玩意儿": "语域：“玩意儿”是口语，与书面的物理叙述不符，也不指压力。"}, "sentence_index": 6, "correct_answer": "静压"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个螺丝钉的静压很大。", "explanation": "这里应该用〈压强〉。静压只指流体静止时的压力，固体螺丝钉受到的压力用压强。"}, {"text": "这块石头的静压很大。", "explanation": "这里应该用〈重量〉。静压是流体的压力，石头是固体，不能用静压说它的分量。"}, {"text": "这辆车的静压很快。", "explanation": "这里应该用〈速度〉。静压是压力，不能用来描述快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工程师测出了一根静压值。", "corrected_sentence": "工程师测出了一个静压值。", "error_description": "量词错误：“静压值”是一个数值，应用“个”；“根”指条状的东西，不能修饰静压值。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "管子里的静压降起来了。", "corrected_sentence": "管子里的静压降下来了。", "error_description": "补语错误：压力下降应说“降下来”；“起来”表示向上，不能与“降”搭配，应改为“降下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12161, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保留", "is_correct": false, "explanation": "与“减小”不是反义关系，指保存下来，不改变数量。"}, {"text": "增大", "is_correct": true, "explanation": "正确：“增大”与“减小”反义，指数量或程度由小变大。"}, {"text": "锁定", "is_correct": false, "explanation": "与“减小”不是反义关系，指固定住，不表示数量变化。"}, {"text": "检查", "is_correct": false, "explanation": "与“减小”不是反义关系，指查看是否正确。"}], "correct_answer": "增大", "explanations": {"保留": "与“减小”不是反义关系，指保存下来，不改变数量。", "增大": "正确：“增大”与“减小”反义，指数量或程度由小变大。", "锁定": "与“减小”不是反义关系，指固定住，不表示数量变化。", "检查": "与“减小”不是反义关系，指查看是否正确。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12161, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安装", "is_correct": false, "explanation": "与“减小”不是反义关系，指把设备装好。"}, {"text": "增大", "is_correct": true, "explanation": "正确：“增大”与“减小”反义，指数量或程度由小变大。"}, {"text": "清洗", "is_correct": false, "explanation": "与“减小”不是反义关系，指把东西弄干净。"}, {"text": "翻译", "is_correct": false, "explanation": "与“减小”不是反义关系，指把一种语言转换成另一种。"}], "correct_answer": "增大", "explanations": {"安装": "与“减小”不是反义关系，指把设备装好。", "增大": "正确：“增大”与“减小”反义，指数量或程度由小变大。", "清洗": "与“减小”不是反义关系，指把东西弄干净。", "翻译": "与“减小”不是反义关系，指把一种语言转换成另一种。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12161, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使数量、程度等从大变小。", "primary_collocate": null, "pronunciation": "jiǎn xiǎo", "ipa": "tɕjɛn˨˩˦ ɕjɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "根据伯努利定理，流体速度的增加必然伴随着静压的减小，这为升力提供了经典物理解释。", "target_word": "减小", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "光滑的路面能减小轮胎的摩擦。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要想办法减小实验的误差。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机的形状可以减小空气阻力。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把角度减小一点，图就好看了。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个城市的差距在慢慢减小。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种包装减小了盒子的体积。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车速减小以后，刹车距离也短了。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把电视的音量减小一点。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压力减小时，气球会慢慢变大。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "减小了", "label": "体标"}, {"form": "减小过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使数量、程度（如速度、误差、阻力）由大变小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7412a05a-d680-454d-90b7-9bb1efc71a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12161, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "固定", "is_correct": false, "explanation": "语义：“固定”表示不变，与前句“速度增加伴随的变化”矛盾。"}, {"text": "减小", "is_correct": true, "explanation": "正确：速度增加时，静压随之减小，“减小”表示数量从大变小。"}, {"text": "测量", "is_correct": false, "explanation": "语义：“测量”是动作，不表示数量变小，句意不通。"}, {"text": "呼吸", "is_correct": false, "explanation": "搭配：“静压”是物理量，不能“呼吸”，搭配不当。"}], "explanations": {"固定": "语义：“固定”表示不变，与前句“速度增加伴随的变化”矛盾。", "减小": "正确：速度增加时，静压随之减小，“减小”表示数量从大变小。", "测量": "语义：“测量”是动作，不表示数量变小，句意不通。", "呼吸": "搭配：“静压”是物理量，不能“呼吸”，搭配不当。"}, "sentence_index": 0, "correct_answer": "减小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们一起减小了这道数学题。", "explanation": "这里应该用〈解〉。“减小”表示数量或程度变小，不能用于解题；解题要用〈解〉。"}, {"text": "他的思想减小了很多。", "explanation": "这里应该用〈转变〉。减小指东西变小或数量、程度变少，思想不能这样计量；思想的变化要说“转变”。"}, {"text": "他把椅子往后减小了一点。", "explanation": "这里应该用〈挪〉。移动位置用“挪”，“减小”不能说椅子向后减小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12161, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是作品、风景，不能带“体积”作宾语。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：包装可以装饰盒子，但不能“装饰”体积，句意不通。"}, {"text": "减小", "is_correct": true, "explanation": "正确：这种包装使盒子的体积变小，“减小”表示体积从大变小。"}, {"text": "搞定", "is_correct": false, "explanation": "语域：“搞定”是口语，与书面的说明语境不符，也不表示体积变小。"}], "explanations": {"欣赏": "搭配：“欣赏”的对象是作品、风景，不能带“体积”作宾语。", "装饰": "语义：包装可以装饰盒子，但不能“装饰”体积，句意不通。", "减小": "正确：这种包装使盒子的体积变小，“减小”表示体积从大变小。", "搞定": "语域：“搞定”是口语，与书面的说明语境不符，也不表示体积变小。"}, "sentence_index": 6, "correct_answer": "减小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "十减小三等于七。", "explanation": "这里应该用〈减〉。算术中的减去用“减”；“减小”表示数量变小，不用于计算。"}, {"text": "工资里减小了五百元社保。", "explanation": "这里应该用〈扣除〉。从工资里去掉款项用“扣除”；“减小”指数量或程度变小。"}, {"text": "他的年龄减小了三岁。", "explanation": "这里应该用〈增长〉。年龄只会增加，不能说“减小”；年龄的变化要说“增长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12161, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新的设计把机器的噪音减小。", "corrected_sentence": "新的设计把机器的噪音减小了。", "error_description": "“了”缺失：把字句需要动词后有补语或“了”等成分才完整，完成的变化应说“把机器的噪音减小了”，不能只说“减小”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12161, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把音量减小了一个。", "corrected_sentence": "我把音量减小了一点。", "error_description": "量词错误：表示“减小”的程度要用“一点”，“一个”不能用来修饰程度变化，应说“减小了一点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
