INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12167, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指将各种事物、部分或方面组合起来，形成一个整体。", "primary_collocate": null, "pronunciation": "zōng hé", "ipa": "tsʊŋ˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "老师综合大家的意见，写了一份报告。", "target_word": "综合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这些资料综合起来，写成一份报告。", "target_word": "综合", "complexity_tier": "T3", "furigana": "zōng hé", "sentence_source": "generated"}, {"text": "医生综合各项检查结果，做出了判断。", "target_word": "综合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理综合了三个部门的建议。", "target_word": "综合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要综合考虑价格和质量。", "target_word": "综合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把两份计划综合成一份新计划。", "target_word": "综合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把大家的答案综合了一下。", "target_word": "综合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章综合了很多人的看法。", "target_word": "综合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家综合各地的数据，提出了办法。", "target_word": "综合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她综合过几种方法，最后选了一种。", "target_word": "综合", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "综合了", "label": "体标（了）"}, {"form": "综合过", "label": "体标（过）"}, {"form": "綜合", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把各种意见、资料等组合成整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f461eef-2cb1-401c-a5d5-34b0f63eba4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12167, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "综合", "is_correct": true, "explanation": "“综合”表示把大家的意见合成一个整体，与后面“写了一份报告”相符。"}, {"text": "分开", "is_correct": false, "explanation": "语义：“分开”是拆散，与“写了一份报告”所需的合成整体相反。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕掉意见，就无法据此写报告。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：打碎意见与后面写报告的前提相矛盾。"}], "explanations": {"综合": "“综合”表示把大家的意见合成一个整体，与后面“写了一份报告”相符。", "分开": "语义：“分开”是拆散，与“写了一份报告”所需的合成整体相反。", "撕": "语义：撕掉意见，就无法据此写报告。", "打碎": "语义：打碎意见与后面写报告的前提相矛盾。"}, "sentence_index": 0, "correct_answer": "综合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议综合到明天才结束。", "explanation": "这里应该用〈延长〉。综合指把多个部分合成整体，会议时间拖长应用延长。"}, {"text": "妈妈给孩子综合了一碗饭。", "explanation": "这里应该用〈盛〉。综合指把多个部分合成整体，给碗里装饭应用盛。"}, {"text": "他把一根绳子综合了一下。", "explanation": "这里应该用〈系〉。综合要把多个部分合成整体，给一根绳子打结要用系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12167, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "综合", "is_correct": true, "explanation": "“综合了一下”表示把大家的答案整理合并，与句意相符。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧掉答案就无法再整理或合并，与“综合”的含义相反。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔掉答案，谈不上对答案进行综合。"}, {"text": "涂抹", "is_correct": false, "explanation": "搭配：“涂抹”指改动痕迹，不能用来描述对答案的整理。"}], "explanations": {"综合": "“综合了一下”表示把大家的答案整理合并，与句意相符。", "烧": "语义：烧掉答案就无法再整理或合并，与“综合”的含义相反。", "扔": "语义：扔掉答案，谈不上对答案进行综合。", "涂抹": "搭配：“涂抹”指改动痕迹，不能用来描述对答案的整理。"}, "sentence_index": 6, "correct_answer": "综合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她综合了一种方法。", "explanation": "这里应该用〈挑选〉。综合要把多个部分合成整体，只选一种方法不能用综合，选择一种应用挑选。"}, {"text": "他们综合了房子。", "explanation": "这里应该用〈装修〉。综合用于意见、方法等抽象内容，房屋的装修不能用综合。"}, {"text": "这次比赛，他综合了第一名的奖杯。", "explanation": "这里应该用〈获得〉。综合指把多个部分合成整体，拿到一个奖杯应用获得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12167, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要把这些资料综合起去。", "corrected_sentence": "我们要把这些资料综合起来。", "error_description": "错误：“综合起去”；正确：“综合起来”。“起来”是结果补语，表示合在一起形成整体，“起去”不能这样用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12167, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她综合了过各家的经验。", "corrected_sentence": "她综合过各家的经验。", "error_description": "“了”和“过”不能同时用在同一个动词后面，应说“综合过”，不能说“综合了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
