INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12179, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个物体接触并相对运动时，产生的阻碍运动的力。", "primary_collocate": null, "pronunciation": "mó cā zǔ lì", "ipa": "mwo˧˥ tsʰa˥ tsu˨˩ li˥˩", "syllable_count": 4, "sentences": [{"text": "与之同时存在的还有阻力，这是空气对飞机前进运动施加的反向力，可细分为压差阻力、摩擦阻力以及诱导阻力等多种类型。", "target_word": "摩擦阻力", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "压差阻力源于飞机前后方的压力不平衡，尤其在机身截面剧烈变化处尤为显著；摩擦阻力则来源于空气分子与飞机表面之间的黏性剪切作用，受表面粗糙度和雷诺数影响极大；而诱导阻力则是升力的副产品，由翼尖涡流引起局部下洗气流所致，其强度随升力增大而增强。", "target_word": "摩擦阻力", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "冰面很滑，摩擦阻力很小。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鞋底有花纹，能增大摩擦阻力。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轮胎和地面之间有摩擦阻力。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在水里游泳，也要克服摩擦阻力。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "给机器加油可以减小摩擦阻力。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机表面光滑，摩擦阻力就小。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摩擦阻力会让滑动的木箱慢慢停下。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "表面越粗糙，摩擦阻力越大。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "两物体接触并相对运动时产生的阻碍运动的力（名词，科技术语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b8a7d8d-7ee2-4ed2-a67d-1e712f561b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12179, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摩擦阻力", "is_correct": true, "explanation": "正确：摩擦阻力是阻力的一种，与压差阻力、诱导阻力并列。"}, {"text": "重力", "is_correct": false, "explanation": "语义：重力是地球对物体的吸引力，不是空气对飞机施加的阻力。"}, {"text": "推力", "is_correct": false, "explanation": "语义：推力使飞机前进，与阻碍运动的阻力方向相反，不能并列在阻力的类型之下。"}, {"text": "升力", "is_correct": false, "explanation": "搭配：“细分为”后接的是阻力的类型，升力与阻力相对，不能与阻力类型并列。"}], "explanations": {"摩擦阻力": "正确：摩擦阻力是阻力的一种，与压差阻力、诱导阻力并列。", "重力": "语义：重力是地球对物体的吸引力，不是空气对飞机施加的阻力。", "推力": "语义：推力使飞机前进，与阻碍运动的阻力方向相反，不能并列在阻力的类型之下。", "升力": "搭配：“细分为”后接的是阻力的类型，升力与阻力相对，不能与阻力类型并列。"}, "sentence_index": 0, "correct_answer": "摩擦阻力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "月亮绕着地球转，是因为两者之间有摩擦阻力。", "explanation": "这里应该用〈引力〉。摩擦阻力是接触时阻碍运动的力，月地相隔遥远且并不接触，维系其运行的力要用引力。"}, {"text": "两家公司之间的摩擦阻力越来越大。", "explanation": "这里应该用〈矛盾〉。摩擦阻力是物理上的力，公司之间的冲突要用矛盾。"}, {"text": "木头能浮在水面上，是因为受到了摩擦阻力。", "explanation": "这里应该用〈浮力〉。摩擦阻力是接触时阻碍运动的力，把木头托起来的力要用浮力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12179, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摩擦阻力", "is_correct": true, "explanation": "正确：给机器加油可以减小的，正是两个接触面之间的摩擦阻力。"}, {"text": "体积", "is_correct": false, "explanation": "语义：加油不能使机器的体积变小，“减小体积”与加油的作用无关。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：机器的年龄不能通过加油减小，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：颜色属于外观，加油不会改变机器的颜色，“减小颜色”搭配不通。"}], "explanations": {"摩擦阻力": "正确：给机器加油可以减小的，正是两个接触面之间的摩擦阻力。", "体积": "语义：加油不能使机器的体积变小，“减小体积”与加油的作用无关。", "年龄": "语义：机器的年龄不能通过加油减小，句意不通。", "颜色": "体貌：颜色属于外观，加油不会改变机器的颜色，“减小颜色”搭配不通。"}, "sentence_index": 6, "correct_answer": "摩擦阻力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子的摩擦阻力越大，人就越容易把它推走。", "explanation": "这里应该用〈推力〉。摩擦阻力是阻碍运动的力，摩擦阻力越大，椅子越难推动，“越容易”不成立；推动椅子的力要用推力。"}, {"text": "苹果落到地上，是因为它受到的摩擦阻力太大。", "explanation": "这里应该用〈重力〉。摩擦阻力是阻碍运动的力，使苹果下落的力要用重力。"}, {"text": "用绳子拉车时，车前进的力来自摩擦阻力。", "explanation": "这里应该用〈拉力〉。摩擦阻力是阻碍运动的力，绳子拉动物体的力要用拉力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12179, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种鞋底的摩擦阻力小很。", "corrected_sentence": "这种鞋底的摩擦阻力很小。", "error_description": "错误：副词“很”应放在形容词“小”之前，写作“很小”，不能放在“小”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12179, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车轮轴承换了新油后，摩擦阻力减了小。", "corrected_sentence": "车轮轴承换了新油后，摩擦阻力减小了。", "error_description": "错误：“了”应放在补语“小”之后，写作“减小了”，不能写成“减了小”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12180, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12180, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12180, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用某种方法引导别人做某事，有时是好的，有时是坏的。", "primary_collocate": null, "pronunciation": "yòu dǎo", "ipa": "jou̯˥˩ tau̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "这条广告的标题很夸张，就是为了诱导人们点进去。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用有趣的问题诱导学生思考。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生耐心诱导病人说出心里的想法。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈诱导弟弟说出了真话。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没有直接说答案，而是诱导大家自己找。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商家用打折诱导顾客买更多东西。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人常常诱导孩子说出家里的地址。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想诱导我把钱借给他，我没有答应。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的故事能诱导孩子爱上读书。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骗子诱导老人在手机上输入密码。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "诱导了", "label": "体标"}, {"form": "诱导过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用方法引导别人去做某事，可好可坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b8a7d8d-7ee2-4ed2-a67d-1e712f561b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12180, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "诱导", "is_correct": true, "explanation": "正确：诱导，用某种方法引导别人做某事。"}, {"text": "游到", "is_correct": false, "explanation": "声调不同：游到 yóu dào 的两个音节声调都与 yòu dǎo 不同，意思是游水抵达。"}, {"text": "有道", "is_correct": false, "explanation": "声调不同：有道 yǒu dào 与 yòu dǎo 的声调都不同，意思是有道理。"}, {"text": "右脑", "is_correct": false, "explanation": "声母不同：nǎo 与 dǎo 只差声母 n 与 d，意思是右半边的大脑。"}, {"text": "油道", "is_correct": false, "explanation": "声调不同：油道 yóu dào 的两个音节声调都与 yòu dǎo 不同，指输送润滑油的通道。"}], "explanations": {"诱导": "正确：诱导，用某种方法引导别人做某事。", "游到": "声调不同：游到 yóu dào 的两个音节声调都与 yòu dǎo 不同，意思是游水抵达。", "有道": "声调不同：有道 yǒu dào 与 yòu dǎo 的声调都不同，意思是有道理。", "右脑": "声母不同：nǎo 与 dǎo 只差声母 n 与 d，意思是右半边的大脑。", "油道": "声调不同：油道 yóu dào 的两个音节声调都与 yòu dǎo 不同，指输送润滑油的通道。"}, "sentence_index": null, "correct_answer": "诱导"}, "level_3": {"options": [{"text": "诱导", "is_correct": true, "explanation": "正确：“为了诱导人们点进去”指用夸张的标题引导人去点击，符合诱导的义项。"}, {"text": "加热", "is_correct": false, "explanation": "语义：加热是给物体升温，不能用来引导人点进去。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：冷却是降温，与引导人的行为无关。"}, {"text": "膨胀", "is_correct": false, "explanation": "语义：膨胀指体积变大，不能用来表示引导人的行为。"}], "explanations": {"诱导": "正确：“为了诱导人们点进去”指用夸张的标题引导人去点击，符合诱导的义项。", "加热": "语义：加热是给物体升温，不能用来引导人点进去。", "冷却": "语义：冷却是降温，与引导人的行为无关。", "膨胀": "语义：膨胀指体积变大，不能用来表示引导人的行为。"}, "sentence_index": 0, "correct_answer": "诱导"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吸烟会诱导肺癌。", "explanation": "这里应该用〈诱发〉。诱导指用方法引导人做事，疾病的引起要用诱发。"}, {"text": "这次地震诱导了山体滑坡。", "explanation": "这里应该用〈引发〉。诱导的对象是人，自然灾害引起的后果要用引发。"}, {"text": "这次事故诱导了大量损失。", "explanation": "这里应该用〈导致〉。诱导指引导人的行为，事故造成的损失要用导致。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诱导", "is_correct": true, "explanation": "正确：“坏人常常诱导孩子说出地址”，诱导指用方法引导人，带有隐蔽的意味，与坏人的身份相合。"}, {"text": "帮助", "is_correct": false, "explanation": "语义：帮助是善意的行为，与坏人引出孩子地址的意图相矛盾。"}, {"text": "保护", "is_correct": false, "explanation": "语义：保护是防止伤害，句子却是让孩子说出地址，与坏人的身份不符。"}, {"text": "表扬", "is_correct": false, "explanation": "搭配：表扬的对象应是值得称赞的行为，“说出家里的地址”不是可以表扬的事，搭配不成立。"}], "explanations": {"诱导": "正确：“坏人常常诱导孩子说出地址”，诱导指用方法引导人，带有隐蔽的意味，与坏人的身份相合。", "帮助": "语义：帮助是善意的行为，与坏人引出孩子地址的意图相矛盾。", "保护": "语义：保护是防止伤害，句子却是让孩子说出地址，与坏人的身份不符。", "表扬": "搭配：表扬的对象应是值得称赞的行为，“说出家里的地址”不是可以表扬的事，搭配不成立。"}, "sentence_index": 6, "correct_answer": "诱导"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这项政策能诱导经济快速增长。", "explanation": "这里应该用〈推动〉。诱导的对象是人的行为，经济快速增长要用推动。"}, {"text": "这条规定诱导了学生的自由。", "explanation": "这里应该用〈限制〉。诱导指用方法引导人做事，限制学生的自由要用限制。"}, {"text": "坚持运动能诱导身体健康。", "explanation": "这里应该用〈促进〉。诱导指用方法引导人做事，身体健康的改善要用促进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师曾经诱导了学生多次思考。", "corrected_sentence": "这位老师曾经诱导过学生多次思考。", "error_description": "错误：“曾经……诱导了”。表示曾有过的经历，体标应用“过”，写作“诱导过学生”；“了”表示已经完成，与“曾经”的经历语义不合。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师诱导学生们了思考。", "corrected_sentence": "老师诱导学生们思考。", "error_description": "错误：“学生们了思考”。“了”不能插在兼语“学生们”与动词“思考”之间，应删去；正确为“老师诱导学生们思考”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
