INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12186, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12186, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示某事物出自某处、某人或某事，即其出处或由来。", "primary_collocate": null, "pronunciation": "lái yuán yú", "ipa": "lai˧˥ ɥɛn˧˥ y˧˥", "syllable_count": 3, "sentences": [{"text": "这个故事的灵感来源于作者的童年。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的自信来源于多年的努力。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多新词来源于网络。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种习惯来源于小时候的生活。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的快乐常常来源于小事。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日来源于一个古老的传说。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的好成绩来源于每天认真复习。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些知识来源于书本，也来源于生活。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的名字来源于一个地名。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的很多成语来源于历史故事。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "抽象事物（灵感、习惯、词语、自信等）的出处或由来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dde6a0-6292-4664-9a19-16fa7c1d359e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12186, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "来源于", "is_correct": true, "explanation": "来源于表示灵感的出处，符合语境，可以填入空格。"}, {"text": "高于", "is_correct": false, "explanation": "语义：高于表示超过、比较高低，灵感不能拿来与童年比高低。"}, {"text": "位于", "is_correct": false, "explanation": "搭配：位于指处于某个处所，灵感不能“位于”某处。"}, {"text": "等于", "is_correct": false, "explanation": "语义：等于表示相同，与灵感的来处不符。"}], "explanations": {"来源于": "来源于表示灵感的出处，符合语境，可以填入空格。", "高于": "语义：高于表示超过、比较高低，灵感不能拿来与童年比高低。", "位于": "搭配：位于指处于某个处所，灵感不能“位于”某处。", "等于": "语义：等于表示相同，与灵感的来处不符。"}, "sentence_index": 0, "correct_answer": "来源于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书来源于我。", "explanation": "这里应该用〈属于〉。来源于说事物从何而来，书归谁所有要用属于，不能用来源于。"}, {"text": "这次会议来源于下午三点。", "explanation": "这里应该用〈在〉。来源于指事物的出处，不指时间点；表示时间要用在下午三点。"}, {"text": "这座公园来源于城市的北边。", "explanation": "这里应该用〈位于〉。来源于说事物从何而来，公园的方位要用位于，不能用来源于。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12186, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "来源于", "is_correct": true, "explanation": "来源于表示好成绩的原因，符合语境，可以填入空格。"}, {"text": "超过", "is_correct": false, "explanation": "语义：超过表示数量或程度的比较，与成绩和复习的因果关系不符。"}, {"text": "违背", "is_correct": false, "explanation": "语义：违背指不遵守，与好成绩的原因相反。"}, {"text": "缺乏", "is_correct": false, "explanation": "配价：缺乏后面要接名词宾语，不能接“每天认真复习”这样的动词短语。"}], "explanations": {"来源于": "来源于表示好成绩的原因，符合语境，可以填入空格。", "超过": "语义：超过表示数量或程度的比较，与成绩和复习的因果关系不符。", "违背": "语义：违背指不遵守，与好成绩的原因相反。", "缺乏": "配价：缺乏后面要接名词宾语，不能接“每天认真复习”这样的动词短语。"}, "sentence_index": 6, "correct_answer": "来源于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我来源于学校走回家。", "explanation": "这里应该用〈从〉。来源于只说事物的出处，不能表示人从某处出发的动作；“从学校走回家”的起点要用从。"}, {"text": "他来源于好心帮了我。", "explanation": "这里应该用〈出于〉。来源于说事物的出处，不表示行为的动机；“出于好心”要用出于，不能用来源于。"}, {"text": "这辆汽车来源于交通工具。", "explanation": "这里应该用〈属于〉。来源于说事物的出处，不表示类别归属；“汽车属于交通工具”才是类别关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个想法来源于了一个故事。", "corrected_sentence": "这个想法来源于一个故事。", "error_description": "“来源于”是表示出处的动词，后面不能加“了”。写成“来源于了”是误用，正确形式为“来源于一个故事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12186, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把灵感来源于一本旧书。", "corrected_sentence": "我的灵感来源于一本旧书。", "error_description": "“来源于”不是处置动词，不能用“把”把“灵感”提到动词前；“灵感”是主语，应用“的”连接。正确形式为“我的灵感来源于一本旧书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12187, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de4db2d-b451-4256-9725-b5daa27bb953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12187, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de4db2d-b451-4256-9725-b5daa27bb953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12187, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在数学中，分数由分子和分母组成，分子表示所取的份数。", "primary_collocate": null, "pronunciation": "fēn zǐ", "ipa": "fən˥ tsɨ˨˩", "syllable_count": 2, "sentences": [{"text": "分数五分之二的分子是二。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在分数四分之三里，分子是三。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分子比分母大的分数叫假分数。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个分数的分子是五，分母是八。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分母不变，分子越大，分数就越大。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把分子和分母都除以二。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分数线上面的数是分子。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分子是零，这个分数就是零。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把分子写成了七，应该是九。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分子和分母之间有一条横线。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "分子：分数线上面的数，表示所取的份数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea56e5e-7c24-45c0-acbd-cd48719e98b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12187, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分子", "is_correct": true, "explanation": "正确：五分之二的分子是二，“分子”指分数线上面的数。"}, {"text": "分母", "is_correct": false, "explanation": "语义：分母是分数线下面的数，五分之二的分母是五，“分母是二”与分数的结构相反。"}, {"text": "分数", "is_correct": false, "explanation": "语义：句中已说“分数五分之二”，“分数”本身是整个数，不能指分数线上面的数。"}, {"text": "整数", "is_correct": false, "explanation": "搭配：“……的整数是二”不成立，“整数”不能作为分数中的一部分。"}], "explanations": {"分子": "正确：五分之二的分子是二，“分子”指分数线上面的数。", "分母": "语义：分母是分数线下面的数，五分之二的分母是五，“分母是二”与分数的结构相反。", "分数": "语义：句中已说“分数五分之二”，“分数”本身是整个数，不能指分数线上面的数。", "整数": "搭配：“……的整数是二”不成立，“整数”不能作为分数中的一部分。"}, "sentence_index": 0, "correct_answer": "分子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "八分之五的分子是八。", "explanation": "这里应该用〈分母〉。八分之五的分母是八，分子是五，分子不能写成八。"}, {"text": "这个分数有一只分子。", "explanation": "这里应该用〈个〉。〈只〉不用来计量分数的组成部分，应说“一个分子”。"}, {"text": "这个分子的分数是五。", "explanation": "这里把〈分子〉当成了整体，分子只是分数线上面表示所取份数的那个数，它不代表整体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de4db2d-b451-4256-9725-b5daa27bb953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12187, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分子", "is_correct": true, "explanation": "正确：分数线上面的数就是分子。"}, {"text": "小数", "is_correct": false, "explanation": "语义：小数是带小数点的数，不指分数线上面的数，句子读起来不成立。"}, {"text": "算式", "is_correct": false, "explanation": "搭配：“分数线上面的数是”后面接的应是一个数，不能说“算式”。"}, {"text": "余数", "is_correct": false, "explanation": "语义：余数是除法中剩下的数，与分数线的位置无关，句子读起来不成立。"}], "explanations": {"分子": "正确：分数线上面的数就是分子。", "小数": "语义：小数是带小数点的数，不指分数线上面的数，句子读起来不成立。", "算式": "搭配：“分数线上面的数是”后面接的应是一个数，不能说“算式”。", "余数": "语义：余数是除法中剩下的数，与分数线的位置无关，句子读起来不成立。"}, "sentence_index": 6, "correct_answer": "分子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "分子写在分数线下面，分母写在上面。", "explanation": "分子应写在分数线上面，这里把它的位置写到了线下面，位置说反了。"}, {"text": "这个分数有一张分子。", "explanation": "这里应该用〈个〉。〈张〉用于纸张等扁平的东西，分子是表示份数的数，不用“张”计量。"}, {"text": "老师在黑板上写了一本分子。", "explanation": "这里应该用〈个〉。〈本〉用于书籍、本子，分子是一个数，不用“本”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de4db2d-b451-4256-9725-b5daa27bb953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12187, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学分子填错了。", "corrected_sentence": "同学把分子填错了。", "error_description": "处置式错误：“分子”作“填错”的受事，需用“把”引出并放在“分子”之前，省略“把”后句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de4db2d-b451-4256-9725-b5daa27bb953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12187, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师分子改成了五。", "corrected_sentence": "老师把分子改成了五。", "error_description": "处置式错误：“分子”作“改成”的受事，需用“把”引出，省略“把”后句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de4db2d-b451-4256-9725-b5daa27bb953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
