INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12194, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在主要产品之外附带生产或产生的东西。", "primary_collocate": null, "pronunciation": "fù chǎn pǐn", "ipa": "fu˥˩ ʈʂʰan˨˩˦ pʰin˨˩˦", "syllable_count": 3, "sentences": [{"text": "压差阻力源于飞机前后方的压力不平衡，尤其在机身截面剧烈变化处尤为显著；摩擦阻力则来源于空气分子与飞机表面之间的黏性剪切作用，受表面粗糙度和雷诺数影响极大；而诱导阻力则是升力的副产品，由翼尖涡流引起局部下洗气流所致，其强度随升力增大而增强。", "target_word": "副产品", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家工厂的副产品也能卖钱。", "target_word": "副产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酿酒时会产生很多副产品。", "target_word": "副产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "豆腐的副产品是豆渣。", "target_word": "副产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种塑料是石油加工的副产品。", "target_word": "副产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把副产品做成了饲料。", "target_word": "副产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "噪音是这台机器的副产品。", "target_word": "副产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糖厂用副产品生产酒精。", "target_word": "副产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种气体是炼铁时的副产品。", "target_word": "副产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热量是发电过程的副产品。", "target_word": "副产品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种副产品", "label": "量词"}, {"form": "副产物", "label": "复合"}, {"form": "副產品", "label": "繁体"}], "register": "书面", "sense_fingerprint": "主要产品之外附带产生的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0df9f5e-58ee-462e-824d-40cfef81d3d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12194, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "副产品", "is_correct": true, "explanation": "正确：句中说诱导阻力是升力之外附带产生的，由翼尖涡流引起，与“副产品”的意思相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“升力的……”不能接“颜色”，颜色与升力之间没有这种关系。"}, {"text": "速度", "is_correct": false, "explanation": "语义：速度是运动的快慢，不是升力附带产生的东西，与句中“由翼尖涡流引起”的说明矛盾。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度与诱导阻力的产生无关，句中说明它是附带产生的，温度不符合。"}], "explanations": {"副产品": "正确：句中说诱导阻力是升力之外附带产生的，由翼尖涡流引起，与“副产品”的意思相符。", "颜色": "搭配：“升力的……”不能接“颜色”，颜色与升力之间没有这种关系。", "速度": "语义：速度是运动的快慢，不是升力附带产生的东西，与句中“由翼尖涡流引起”的说明矛盾。", "温度": "语义：温度与诱导阻力的产生无关，句中说明它是附带产生的，温度不符合。"}, "sentence_index": 0, "correct_answer": "副产品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "做豆腐需要准备不少副产品。", "explanation": "这里应该用〈原料〉。副产品是生产主产品时附带得到的东西，不能作为做豆腐投入的材料。"}, {"text": "这种药的副产品是头痛。", "explanation": "这里应该用〈副作用〉。副作用指药物在治疗作用之外产生的不良反应；副产品是生产过程中附带得到的东西，不能指药物的不良反应。"}, {"text": "他是我们工厂的副产品。", "explanation": "这里应该用〈职工〉。副产品指生产时附带得到的物品，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12194, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "副产品", "is_correct": true, "explanation": "正确：噪音是这台机器运转时附带产生的东西，与“副产品”的意思相合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”是事物的性质，不能与“是……的”这种判断搭配来指噪音。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是经济概念，噪音不是可以标价的东西，句子语义不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指存在的时长，噪音不属于这一概念，与“附带产生”的意思无关。"}], "explanations": {"副产品": "正确：噪音是这台机器运转时附带产生的东西，与“副产品”的意思相合。", "颜色": "搭配：“颜色”是事物的性质，不能与“是……的”这种判断搭配来指噪音。", "价格": "语义：价格是经济概念，噪音不是可以标价的东西，句子语义不通。", "年龄": "语义：年龄指存在的时长，噪音不属于这一概念，与“附带产生”的意思无关。"}, "sentence_index": 6, "correct_answer": "副产品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的副产品是晴天。", "explanation": "这里应该用〈天气〉。副产品是生产附带得到的物品，不能用来说天气。"}, {"text": "这台机器的副产品已经三个月大了。", "explanation": "这里应该用〈使用时间〉。“几个月大”只用来说生物，副产品是物品，不能这样描述。"}, {"text": "这家公司的会议决定让副产品担任经理。", "explanation": "这里应该用〈员工〉。副产品是生产附带得到的物品，不能担任职务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只副产品可以做饲料。", "corrected_sentence": "这种副产品可以做饲料。", "error_description": "错误在于量词：“副产品”应用“种”计量，“只”用于动物或成对的东西，不能用来计量副产品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们统计过这台机器得副产品了。", "corrected_sentence": "他们统计过这台机器的副产品了。", "error_description": "错误在于目标词“副产品”前的修饰标记用了“得”，应为结构助词“的”；“得”不能用在名词前作定语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
