INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12195, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "翅膀的尖端，指鸟或飞机翅膀的最末端。", "primary_collocate": null, "pronunciation": "yì jiān", "ipa": "i˥˩ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "压差阻力源于飞机前后方的压力不平衡，尤其在机身截面剧烈变化处尤为显著；摩擦阻力则来源于空气分子与飞机表面之间的黏性剪切作用，受表面粗糙度和雷诺数影响极大；而诱导阻力则是升力的副产品，由翼尖涡流引起局部下洗气流所致，其强度随升力增大而增强。", "target_word": "翼尖", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "飞机的翼尖向上弯着。", "target_word": "翼尖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟的翼尖是黑色的。", "target_word": "翼尖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机飞行时，翼尖会产生涡流。", "target_word": "翼尖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师在翼尖装了小翼。", "target_word": "翼尖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鹰飞过时，翼尖几乎碰到树。", "target_word": "翼尖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架飞机的翼尖有一盏灯。", "target_word": "翼尖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风吹过翼尖，发出轻轻的声音。", "target_word": "翼尖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白鹭的翼尖沾着水。", "target_word": "翼尖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机停好后，他检查了左边的翼尖。", "target_word": "翼尖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个翼尖", "label": "量词"}, {"form": "翼尖涡流", "label": "复合"}], "register": "书面", "sense_fingerprint": "鸟或飞机翅膀的最末端", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0df9f5e-58ee-462e-824d-40cfef81d3d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12195, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "翼尖", "is_correct": true, "explanation": "翼尖：翅膀的最末端，即本题目标词。"}, {"text": "意见", "is_correct": false, "explanation": "jiàn（第四声）与 jiān（第一声）声调不同，意思是看法。"}, {"text": "一间", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，一间指一个房间。"}, {"text": "议价", "is_correct": false, "explanation": "jià（第四声）与 jiān（第一声）声调不同，意思是讨价还价。"}], "explanations": {"翼尖": "翼尖：翅膀的最末端，即本题目标词。", "意见": "jiàn（第四声）与 jiān（第一声）声调不同，意思是看法。", "一间": "yī（第一声）与 yì（第四声）声调不同，一间指一个房间。", "议价": "jià（第四声）与 jiān（第一声）声调不同，意思是讨价还价。"}, "sentence_index": null, "correct_answer": "翼尖"}, "level_3": {"options": [{"text": "翼尖", "is_correct": true, "explanation": "翼尖：翅膀的最末端，诱导阻力的涡流由翼端产生，与句中的升力关系相符。"}, {"text": "油箱", "is_correct": false, "explanation": "语义：油箱不产生升力，与诱导阻力的来源无关。"}, {"text": "机身", "is_correct": false, "explanation": "语义：诱导阻力来自机翼升力，不是机身截面变化造成的。"}, {"text": "发动机", "is_correct": false, "explanation": "搭配：说“发动机涡流”不符合常见说法，句中讲的是翼端涡流。"}], "explanations": {"翼尖": "翼尖：翅膀的最末端，诱导阻力的涡流由翼端产生，与句中的升力关系相符。", "油箱": "语义：油箱不产生升力，与诱导阻力的来源无关。", "机身": "语义：诱导阻力来自机翼升力，不是机身截面变化造成的。", "发动机": "搭配：说“发动机涡流”不符合常见说法，句中讲的是翼端涡流。"}, "sentence_index": 0, "correct_answer": "翼尖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小鸟张开翼尖飞走了。", "explanation": "这里应该用〈翅膀〉。翼尖只指翅膀的末端，张开、飞行要用整对翅膀。"}, {"text": "这把剑的翼尖很锋利。", "explanation": "这里应该用〈尖端〉。翼尖只用于鸟或飞机的翅膀，剑的尖端不能说翼尖。"}, {"text": "飞机的翼尖很宽。", "explanation": "这里应该用〈机翼〉。翼尖只是翅膀的末端，很窄，形容宽度应说机翼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12195, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "翼尖", "is_correct": true, "explanation": "翼尖：翅膀的最末端，即本题目标词。"}, {"text": "一肩", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，一肩指一边肩膀，不常用。"}, {"text": "一件", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）、jiàn（第四声）与 jiān（第一声）声调都不同，一件指一个物品。"}, {"text": "异见", "is_correct": false, "explanation": "jiàn（第四声）与 jiān（第一声）声调不同，意思是不同的看法。"}], "explanations": {"翼尖": "翼尖：翅膀的最末端，即本题目标词。", "一肩": "yī（第一声）与 yì（第四声）声调不同，一肩指一边肩膀，不常用。", "一件": "yī（第一声）与 yì（第四声）、jiàn（第四声）与 jiān（第一声）声调都不同，一件指一个物品。", "异见": "jiàn（第四声）与 jiān（第一声）声调不同，意思是不同的看法。"}, "sentence_index": null, "correct_answer": "翼尖"}, "level_3": {"options": [{"text": "翼尖", "is_correct": true, "explanation": "翼尖：飞机翼端装有灯，与句意相符。"}, {"text": "螺旋桨", "is_correct": false, "explanation": "语义：螺旋桨不是装灯的部位，句子不合常理。"}, {"text": "机轮", "is_correct": false, "explanation": "语义：机轮是起落装置，一般不说它上面有一盏灯。"}, {"text": "座椅", "is_correct": false, "explanation": "搭配：说座椅“有一盏灯”不符合常规，灯一般装在翼端或机身。"}], "explanations": {"翼尖": "翼尖：飞机翼端装有灯，与句意相符。", "螺旋桨": "语义：螺旋桨不是装灯的部位，句子不合常理。", "机轮": "语义：机轮是起落装置，一般不说它上面有一盏灯。", "座椅": "搭配：说座椅“有一盏灯”不符合常规，灯一般装在翼端或机身。"}, "sentence_index": 6, "correct_answer": "翼尖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "飞机停好后，他检查了一把翼尖。", "explanation": "这里应该用〈个〉。“把”用于有柄的器物，不能用来计量翼尖。"}, {"text": "飞机停好后，他检查了一根翼尖。", "explanation": "这里应该用〈个〉。“根”用于细长的东西，翼尖不能用“根”计量。"}, {"text": "飞机停好后，他检查了一条翼尖。", "explanation": "这里应该用〈个〉。“条”用于长条形物件，翼尖不能用“条”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12195, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风吹过后，一根翼尖上沾着一片羽毛。", "corrected_sentence": "风吹过后，一个翼尖上沾着一片羽毛。", "error_description": "量词错误：翼尖应用“个”计量，“根”用于细长的东西，不能用来计量翼尖，应说“一个翼尖上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12195, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老鹰飞过时，一颗翼尖碰到了树枝。", "corrected_sentence": "老鹰飞过时，一个翼尖碰到了树枝。", "error_description": "量词错误：翼尖应用“个”计量，“颗”用于圆粒状的东西，不能用来计量翼尖。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
