INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12196, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "流体在流动中形成的旋转运动，比如水或空气打转。", "primary_collocate": null, "pronunciation": "wō liú", "ipa": "uo˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "压差阻力源于飞机前后方的压力不平衡，尤其在机身截面剧烈变化处尤为显著；摩擦阻力则来源于空气分子与飞机表面之间的黏性剪切作用，受表面粗糙度和雷诺数影响极大；而诱导阻力则是升力的副产品，由翼尖涡流引起局部下洗气流所致，其强度随升力增大而增强。", "target_word": "涡流", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "飞机飞过后，空气中会留下涡流。", "target_word": "涡流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水遇到桥墩时会形成涡流。", "target_word": "涡流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "涡流会让船晃得很厉害。", "target_word": "涡流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "翼尖涡流对后面的飞机有影响。", "target_word": "涡流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管道拐弯的地方容易出现涡流。", "target_word": "涡流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师想办法减少涡流。", "target_word": "涡流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水在岛边打转，形成涡流。", "target_word": "涡流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "涡流消耗了不少能量。", "target_word": "涡流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车后面的空气里也有涡流。", "target_word": "涡流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股涡流", "label": "量词"}, {"form": "翼尖涡流", "label": "复合"}, {"form": "渦流", "label": "繁体"}], "register": "书面", "sense_fingerprint": "流体流动中形成的旋转运动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0df9f5e-58ee-462e-824d-40cfef81d3d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12196, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "涡流", "is_correct": true, "explanation": "涡流：流体打转形成的旋转运动，翼尖涡流引起下洗气流，与句意相符。"}, {"text": "机身", "is_correct": false, "explanation": "语义：诱导阻力的涡流由翼端产生，机身不是升力副产品的来源。"}, {"text": "尾翼", "is_correct": false, "explanation": "语义：尾翼位于机尾，与升力产生的翼端无关。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“翼尖空气”不是常见组合，翼尖产生的是涡流。"}], "explanations": {"涡流": "涡流：流体打转形成的旋转运动，翼尖涡流引起下洗气流，与句意相符。", "机身": "语义：诱导阻力的涡流由翼端产生，机身不是升力副产品的来源。", "尾翼": "语义：尾翼位于机尾，与升力产生的翼端无关。", "空气": "搭配：“翼尖空气”不是常见组合，翼尖产生的是涡流。"}, "sentence_index": 0, "correct_answer": "涡流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "高空的涡流很平稳。", "explanation": "这里应该用〈气流〉。涡流是打转的旋动，形容平稳的流动要用气流。"}, {"text": "河水的涡流很平缓。", "explanation": "这里应该用〈水流〉。涡流本身是打转的，与“平缓”矛盾，描述水的平缓流动要用水流。"}, {"text": "涡流笔直地伸向远方，像铁轨一样。", "explanation": "这里应该用〈河道〉。涡流是打转的旋动，不能笔直地伸展，描述笔直延伸的水道要用河道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12196, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "涡流", "is_correct": true, "explanation": "涡流：汽车尾后或管道中的旋转水流或气流，减少它是工程的目标，与句意相符。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是地点，不能被“减少”，句子不合理。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能被工程师“减少”，句子不合理。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“减少”一般用于数量或程度，说“减少桌子”不符合常规。"}], "explanations": {"涡流": "涡流：汽车尾后或管道中的旋转水流或气流，减少它是工程的目标，与句意相符。", "花园": "语义：花园是地点，不能被“减少”，句子不合理。", "月亮": "语义：月亮不能被工程师“减少”，句子不合理。", "桌子": "搭配：“减少”一般用于数量或程度，说“减少桌子”不符合常规。"}, "sentence_index": 6, "correct_answer": "涡流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车后面的空气里也有一块涡流。", "explanation": "这里应该用〈股〉。“块”用于块状物，涡流不能用“块”计量。"}, {"text": "汽车后面的空气里也有一根涡流。", "explanation": "这里应该用〈股〉。“根”用于细长的东西，涡流不能用“根”计量。"}, {"text": "汽车后面的空气里也有一只涡流。", "explanation": "这里应该用〈股〉。“只”用于动物或成对的物件，涡流不能用“只”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12196, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "河水的一把涡流转得很快。", "corrected_sentence": "河水的一股涡流转得很快。", "error_description": "量词错误：涡流应用“股”计量（一股涡流），“把”用于有柄的器物，不能用来计量涡流。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工程师把一颗涡流减弱了。", "corrected_sentence": "工程师把一股涡流减弱了。", "error_description": "量词错误：涡流应用“股”计量，“颗”用于圆粒状的东西，不能用来计量涡流。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
