INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12200, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示跟从、顺从或任凭的意思。", "primary_collocate": null, "pronunciation": "suí", "ipa": "sweɪ˧˥", "syllable_count": 1, "sentences": [{"text": "你想吃什么就点，我都随你。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去公园还是去电影院，都随你。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师往前走，学生们随老师进了教室。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我不管，随他去吧。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不争吵，总是随大家的决定。", "target_word": "随", "complexity_tier": "T3", "furigana": "suí", "sentence_source": "generated"}, {"text": "爸爸出门，弟弟也随爸爸一起走了。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "颜色你选吧，我随你。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人走进大门，我们随他进了客厅。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花多少钱，随你，我不问。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说去哪儿，我就随她去哪儿。", "target_word": "随", "complexity_tier": "T3", "furigana": "suí", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "跟从、顺从，任凭对方决定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a01c2b4-5d6b-4e20-b907-6bc7d46b8ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12200, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "随", "is_correct": true, "explanation": "随（suí，第二声）：跟从、顺从的意思。"}, {"text": "岁", "is_correct": false, "explanation": "suì（第四声）与 suí（第二声）声调不同，意思是年岁。"}, {"text": "髓", "is_correct": false, "explanation": "suǐ（第三声）与 suí（第二声）声调不同，意思是骨髓。"}, {"text": "虽", "is_correct": false, "explanation": "suī（第一声）与 suí（第二声）声调不同，意思是虽然。"}, {"text": "碎", "is_correct": false, "explanation": "suì（第四声）与 suí（第二声）声调不同，意思是破碎。"}], "explanations": {"随": "随（suí，第二声）：跟从、顺从的意思。", "岁": "suì（第四声）与 suí（第二声）声调不同，意思是年岁。", "髓": "suǐ（第三声）与 suí（第二声）声调不同，意思是骨髓。", "虽": "suī（第一声）与 suí（第二声）声调不同，意思是虽然。", "碎": "suì（第四声）与 suí（第二声）声调不同，意思是破碎。"}, "sentence_index": null, "correct_answer": "随"}, "level_3": {"options": [{"text": "随", "is_correct": true, "explanation": "正确。“我都随你”表示任凭对方决定，符合前半句“你想吃什么就点”的语境。"}, {"text": "责怪", "is_correct": false, "explanation": "语义：前句说“你想吃什么就点”，“责怪你”与这种迁就的语气相反。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝你”与“你想吃什么就点”的语境冲突。"}, {"text": "挡", "is_correct": false, "explanation": "搭配：“挡你”不能表示任凭对方决定，这个动词不能这样搭配。"}], "explanations": {"随": "正确。“我都随你”表示任凭对方决定，符合前半句“你想吃什么就点”的语境。", "责怪": "语义：前句说“你想吃什么就点”，“责怪你”与这种迁就的语气相反。", "拒绝": "语义：“拒绝你”与“你想吃什么就点”的语境冲突。", "挡": "搭配：“挡你”不能表示任凭对方决定，这个动词不能这样搭配。"}, "sentence_index": 0, "correct_answer": "随"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们约定三年后随即见面。", "explanation": "这里应该用〈一段时间以后〉。“随即”表示紧接着、立刻发生，不能与“三年后”连用。"}, {"text": "他随身站起来，走到了门口。", "explanation": "这里应该用〈起身〉。“随身”指东西带在身上，不用于形容身体的动作。"}, {"text": "他随口拿出了钱包。", "explanation": "这里应该用〈随手〉。“随口”只用于说话，拿东西这类动作不能用随口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12200, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "随", "is_correct": true, "explanation": "随（suí，第二声）：跟从、顺从的意思。"}, {"text": "碎", "is_correct": false, "explanation": "suì（第四声）与 suí（第二声）声调不同，意思是破碎。"}, {"text": "髓", "is_correct": false, "explanation": "suǐ（第三声）与 suí（第二声）声调不同，意思是骨髓。"}, {"text": "穗", "is_correct": false, "explanation": "suì（第四声）与 suí（第二声）声调不同，意思是谷穗。"}, {"text": "隧", "is_correct": false, "explanation": "suì（第四声）与 suí（第二声）声调不同，意思是隧道。"}], "explanations": {"随": "随（suí，第二声）：跟从、顺从的意思。", "碎": "suì（第四声）与 suí（第二声）声调不同，意思是破碎。", "髓": "suǐ（第三声）与 suí（第二声）声调不同，意思是骨髓。", "穗": "suì（第四声）与 suí（第二声）声调不同，意思是谷穗。", "隧": "suì（第四声）与 suí（第二声）声调不同，意思是隧道。"}, "sentence_index": null, "correct_answer": "随"}, "level_3": {"options": [{"text": "随", "is_correct": true, "explanation": "正确。“我随你”表示听从对方的选择，与“颜色你选吧”的语境一致。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“颜色你选吧”表示交给对方决定，“反对你”与这一语境冲突。"}, {"text": "瞒", "is_correct": false, "explanation": "语义：“瞒你”表示隐瞒对方，与让对方自由选择的语境不符。"}, {"text": "怕", "is_correct": false, "explanation": "搭配：“怕你”表示畏惧对方，与“颜色你选吧，我……你”的语境不搭。"}], "explanations": {"随": "正确。“我随你”表示听从对方的选择，与“颜色你选吧”的语境一致。", "反对": "语义：“颜色你选吧”表示交给对方决定，“反对你”与这一语境冲突。", "瞒": "语义：“瞒你”表示隐瞒对方，与让对方自由选择的语境不符。", "怕": "搭配：“怕你”表示畏惧对方，与“颜色你选吧，我……你”的语境不搭。"}, "sentence_index": 6, "correct_answer": "随"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一边吃饭，随后一边看书。", "explanation": "这里应该用〈同时〉。“随后”表示在某事之后接着发生，不能用于两件事同时进行。"}, {"text": "他随时在去年就到了这里。", "explanation": "这里应该用〈早在〉。“随时”指任何时候都可以，不能与“去年”这样确定的时间连用。"}, {"text": "她随手哭了起来，大家都很惊讶。", "explanation": "这里应该用〈忽然〉。“随手”指顺着手边的动作，不能用来形容哭这类情绪反应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我都你随，你定吧。", "corrected_sentence": "我都随你，你定吧。", "error_description": "位置错误：“随”的宾语应放在它后面，应说“我都随你”，不能把“你”放在“随”前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他随父母去着北京。", "corrected_sentence": "他随父母去了北京。", "error_description": "体标错误：表示动作完成应用“了”，应说“随父母去了北京”；“着”表示持续，不能用于这里，说“去着北京”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12201, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减小", "is_correct": true, "explanation": "减小与增大是反义词，指使大小、数量或程度变小。"}, {"text": "保持", "is_correct": false, "explanation": "保持表示维持原状，与增大没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论是言语交流，与增大没有反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "研究是探求事理，与增大没有反义关系。"}], "correct_answer": "减小", "explanations": {"减小": "减小与增大是反义词，指使大小、数量或程度变小。", "保持": "保持表示维持原状，与增大没有反义关系。", "讨论": "讨论是言语交流，与增大没有反义关系。", "研究": "研究是探求事理，与增大没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12201, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减小", "is_correct": true, "explanation": "减小与增大是反义词，指使大小、数量或程度变小。"}, {"text": "建立", "is_correct": false, "explanation": "建立表示创设，与增大没有反义关系。"}, {"text": "通过", "is_correct": false, "explanation": "通过表示经过或批准，与增大没有反义关系。"}, {"text": "组织", "is_correct": false, "explanation": "组织表示安排、集合，与增大没有反义关系。"}], "correct_answer": "减小", "explanations": {"减小": "减小与增大是反义词，指使大小、数量或程度变小。", "建立": "建立表示创设，与增大没有反义关系。", "通过": "通过表示经过或批准，与增大没有反义关系。", "组织": "组织表示安排、集合，与增大没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12201, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "增加大小、数量或程度。", "primary_collocate": null, "pronunciation": "zēng dà", "ipa": "tsəŋ˥ ta˥˩", "syllable_count": 2, "sentences": [{"text": "我们要增大练习的量。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂增大了生产力度。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "增大桌子的面积，才能放下这些书。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员增大了发动机的功率。", "target_word": "增大", "complexity_tier": "T3", "furigana": "zēng dà", "sentence_source": "generated"}, {"text": "老师增大了作业的难度。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想增大音量，就按右边的键。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把照片增大了一倍。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生建议不要增大药的用量。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想增大这个城市的销量。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "增大压力后，水流得更快了。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "增大了", "label": "完成体"}, {"form": "增大过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "使大小、数量或程度变大（及物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a01c2b4-5d6b-4e20-b907-6bc7d46b8ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12201, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "增大", "is_correct": true, "explanation": "增大：使练习的量变多，与「练习的量」相合，符合句意。"}, {"text": "减少", "is_correct": false, "explanation": "语义：“减少”与“增大”意思相反，不符合“我们要增大练习的量”的意图。"}, {"text": "扩展", "is_correct": false, "explanation": "搭配：“扩展”用于范围、领域，不说练习的量。"}, {"text": "延长", "is_correct": false, "explanation": "语义：“延长”说时间或长度的拉长，与练习的量不相合。"}], "explanations": {"增大": "增大：使练习的量变多，与「练习的量」相合，符合句意。", "减少": "语义：“减少”与“增大”意思相反，不符合“我们要增大练习的量”的意图。", "扩展": "搭配：“扩展”用于范围、领域，不说练习的量。", "延长": "语义：“延长”说时间或长度的拉长，与练习的量不相合。"}, "sentence_index": 0, "correct_answer": "增大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂增大了产品的质量。", "explanation": "这里应该用〈提高〉。质量、水平的上升用提高，增大只说大小、数量或程度的变大。"}, {"text": "他增大了身体的抵抗力。", "explanation": "这里应该用〈增强〉。抵抗力、能力等抽象的强弱用增强，增大不用于能力。"}, {"text": "节日增大了热闹的气氛。", "explanation": "这里应该用〈增添〉。气氛、乐趣等要用增添，增大只用于具体事物的变大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12201, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "增大", "is_correct": true, "explanation": "增大：使照片变大一倍，与「把照片」和「一倍」相合。"}, {"text": "复印", "is_correct": false, "explanation": "语义：“复印”是复制，不会按倍数改变照片的大小。"}, {"text": "装裱", "is_correct": false, "explanation": "语义：“装裱”是裱糊装框，不改变照片的大小。"}, {"text": "扩充", "is_correct": false, "explanation": "搭配：“扩充”多用于人员、设备、内容，不说照片的大小变化。"}], "explanations": {"增大": "增大：使照片变大一倍，与「把照片」和「一倍」相合。", "复印": "语义：“复印”是复制，不会按倍数改变照片的大小。", "装裱": "语义：“装裱”是裱糊装框，不改变照片的大小。", "扩充": "搭配：“扩充”多用于人员、设备、内容，不说照片的大小变化。"}, "sentence_index": 6, "correct_answer": "增大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校增大了一个新的专业。", "explanation": "这里应该用〈增设〉。新设立的专业要用增设，增大只说原有事物的变大。"}, {"text": "这次事故增大了他的伤势。", "explanation": "这里应该用〈加重〉。伤势、病情的加重要用加重，增大只说大小的变大。"}, {"text": "这几年，他的职位增大很快。", "explanation": "这里应该用〈提升〉。职位的上升用提升，增大不用于职位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12201, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次试验把温度增大了到八十度。", "corrected_sentence": "这次试验把温度增大到了八十度。", "error_description": "错误：“了”放在了补语“到”之前。正确：“增大到了八十度”。表示结果的补语“到”要紧跟“增大”，“了”放在“到”的后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12201, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂去年把产量增大得三成。", "corrected_sentence": "工厂去年把产量增大了三成。", "error_description": "错误：补语标记“得”用错。正确：“增大了三成”。“得”后接形容词或程度短语，表示增加的幅度要用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
