INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12202, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指舰船或飞机在海上或空中按照一定路线或速度持续行驶，通常用于巡逻、执行任务或长距离飞行。", "primary_collocate": null, "pronunciation": "xún háng", "ipa": "/ɕyn˧˥ xɑŋ˧˥/", "syllable_count": 2, "sentences": [{"text": "飞机在高空匀速巡航，可以省下不少燃油。", "target_word": "巡航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机起飞、巡航、降落时，机翼的状态都不一样。", "target_word": "巡航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海军舰艇每天沿着固定路线在海上巡航。", "target_word": "巡航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架飞机正在边境上空巡航。", "target_word": "巡航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海警船按照计划在这片海域巡航。", "target_word": "巡航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天有两架战机在空中巡航了三个小时。", "target_word": "巡航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军舰执行任务时，会沿着航线巡航。", "target_word": "巡航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巡逻机每周都要在海上巡航几次。", "target_word": "巡航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两艘护卫舰奉命在海峡一带巡航。", "target_word": "巡航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支舰队曾在南海巡航过一个月。", "target_word": "巡航", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "巡航了", "label": "完成体"}, {"form": "巡航过", "label": "经历体"}, {"form": "巡航着", "label": "持续体"}, {"form": "巡航导弹", "label": "复合词"}, {"form": "巡航速度", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "巡航|动词|舰船或飞机按路线或稳定速度持续行驶，用于巡逻、执行任务或长距离飞行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a01c2b4-5d6b-4e20-b907-6bc7d46b8ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12202, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巡航", "is_correct": true, "explanation": "正确。巡航指飞机在空中按固定速度稳定飞行，与“匀速”和“省下燃油”的语境相合。"}, {"text": "失速", "is_correct": false, "explanation": "语义：失速指飞机失去升力，与“匀速”的平稳飞行正相反，不能省油。"}, {"text": "休眠", "is_correct": false, "explanation": "语义：休眠指停止活动，飞机在高空飞行时不能休眠。"}, {"text": "停放", "is_correct": false, "explanation": "语义：停放指停下放置，与飞机在高空匀速飞行相反。"}], "explanations": {"巡航": "正确。巡航指飞机在空中按固定速度稳定飞行，与“匀速”和“省下燃油”的语境相合。", "失速": "语义：失速指飞机失去升力，与“匀速”的平稳飞行正相反，不能省油。", "休眠": "语义：休眠指停止活动，飞机在高空飞行时不能休眠。", "停放": "语义：停放指停下放置，与飞机在高空匀速飞行相反。"}, "sentence_index": 0, "correct_answer": "巡航"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "校长每天在校园里巡航，检查卫生。", "explanation": "这里应该用〈巡视〉。巡航只说舰船、飞机在海上或空中按路线行驶，人在校园里走动要用巡视。"}, {"text": "木筏顺着河水巡航。", "explanation": "这里应该用〈漂流〉。巡航只用于舰船或飞机，木筏随水漂流不能说巡航。"}, {"text": "一条小狗在街上巡航。", "explanation": "这里应该用〈游荡〉。巡航只用于舰船或飞机，小狗在街上走动不能说巡航。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12202, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巡航", "is_correct": true, "explanation": "巡航：军舰沿航线行驶，与「执行任务」和「航线」的语境相合。"}, {"text": "停泊", "is_correct": false, "explanation": "语义：“停泊”指停靠不动，与“沿着航线”的行进相反。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：军舰不能游泳，与任务和航线无关。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”的主语应为人，军舰不说散步。"}], "explanations": {"巡航": "巡航：军舰沿航线行驶，与「执行任务」和「航线」的语境相合。", "停泊": "语义：“停泊”指停靠不动，与“沿着航线”的行进相反。", "游泳": "语义：军舰不能游泳，与任务和航线无关。", "散步": "搭配：“散步”的主语应为人，军舰不说散步。"}, "sentence_index": 6, "correct_answer": "巡航"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这艘军舰在港口巡航，等着下一步命令。", "explanation": "这里应该用〈停泊〉。巡航指沿路线行驶，停在港口等待时不说巡航。"}, {"text": "客轮在码头巡航，等待旅客上船。", "explanation": "这里应该用〈停靠〉。码头停留不是行驶，巡航不用于停着的船。"}, {"text": "一只风筝在空中巡航，飘来飘去。", "explanation": "这里应该用〈飘动〉。风筝随风飘荡，不按路线行驶，巡航只用于舰船、飞机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12202, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这架战斗机海峡上空巡航。", "corrected_sentence": "这架战斗机在海峡上空巡航。", "error_description": "错误：“海峡上空”前缺少介词“在”。正确：“在海峡上空巡航”。表示地点的词语放在动词前时要用“在”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12202, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支编队每年都在西太平洋巡航一个。", "corrected_sentence": "这支编队每年都在西太平洋巡航一次。", "error_description": "错误：计次的量词用错。正确：“巡航一次”。巡航是动作，计次要用“次”，“个”用于指称具体事物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
