INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12203, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12203, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指利用飞机等航空器在空中飞行的活动，也指与之相关的行业。", "primary_collocate": null, "pronunciation": "háng kōng", "ipa": "/xɑŋ˧˥ kʰʊŋ˥/", "syllable_count": 2, "sentences": [{"text": "他在航空领域工作了十年。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航空安全对每位乘客都很重要。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代航空技术发展得非常快。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了中国航空的历史。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航空知识能帮我们了解飞机怎么飞。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有很多航空方面的展品。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就喜欢航空，想当飞行员。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航空运输比火车运输快得多。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学里新开了一门航空课程。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次航空表演吸引了很多游客。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "航空公司", "label": "复合词"}, {"form": "航空母舰", "label": "复合词"}, {"form": "航空邮件", "label": "复合词"}], "register": "中性", "sense_fingerprint": "航空|名词|航空器在空中飞行的活动或相关行业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a01c2b4-5d6b-4e20-b907-6bc7d46b8ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12203, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "航空", "is_correct": true, "explanation": "航空指飞行活动或相关行业，可以修饰“领域”，“航空领域”是常见说法。"}, {"text": "皮鞋", "is_correct": false, "explanation": "语义：皮鞋是物品，不是可以工作的领域，“在……领域工作”不成立。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“领域”指学科或行业，不能用具体家电来修饰。"}, {"text": "饭碗", "is_correct": false, "explanation": "语域：“饭碗”是口语说法，指谋生的职业，与书面语“领域”不搭配，也不指工作的领域。"}], "explanations": {"航空": "航空指飞行活动或相关行业，可以修饰“领域”，“航空领域”是常见说法。", "皮鞋": "语义：皮鞋是物品，不是可以工作的领域，“在……领域工作”不成立。", "冰箱": "搭配：“领域”指学科或行业，不能用具体家电来修饰。", "饭碗": "语域：“饭碗”是口语说法，指谋生的职业，与书面语“领域”不搭配，也不指工作的领域。"}, "sentence_index": 0, "correct_answer": "航空"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这架航空真大，能坐三百人。", "explanation": "这里应该用〈飞机〉。航空指飞行这件事或这一行业，不是可以用“架”计数、能载人的实物。"}, {"text": "我们这次航空玩了三天，很开心。", "explanation": "这里应该用〈旅行〉。“旅行”指出去玩的整个过程，可以说“玩了三天”；航空只指在空中飞行，不能指一次出游。"}, {"text": "宇宙飞船要进行一次航空，前往月球。", "explanation": "这里应该用〈航天〉。前往月球属于太空飞行，航空指大气层中的飞行，不包括太空。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12203, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "航空", "is_correct": true, "explanation": "“从小就喜欢航空”指对飞行行业或活动感兴趣，与“想当飞行员”前后一致。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“喜欢”后接兴趣对象，厨房是场所，不能作为兴趣，句子不通。"}, {"text": "江湖", "is_correct": false, "explanation": "语域：“江湖”带文学色彩，与口语叙述“从小就喜欢”不协调，也不指常见的爱好对象。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：菜市场是地点，与“想当飞行员”的志向毫无关联，句子不成立。"}], "explanations": {"航空": "“从小就喜欢航空”指对飞行行业或活动感兴趣，与“想当飞行员”前后一致。", "厨房": "搭配：“喜欢”后接兴趣对象，厨房是场所，不能作为兴趣，句子不通。", "江湖": "语域：“江湖”带文学色彩，与口语叙述“从小就喜欢”不协调，也不指常见的爱好对象。", "菜市场": "语义：菜市场是地点，与“想当飞行员”的志向毫无关联，句子不成立。"}, "sentence_index": 6, "correct_answer": "航空"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的航空晚点了三个小时。", "explanation": "这里应该用〈航班〉。航班是具体的一趟飞行，可以晚点；航空是抽象的飞行活动或行业，不能晚点。"}, {"text": "我在网上订了航空，明天去北京。", "explanation": "这里应该用〈机票〉。预订的是机票，航空不是可以订的凭证。"}, {"text": "这个航空很大，每天有很多航班。", "explanation": "这里应该用〈机场〉。机场是场所，可以很大、有很多航班；航空不指场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12203, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想去航空的公司工作。", "corrected_sentence": "我想去航空公司工作。", "error_description": "错误：“航空的公司”；正确：“航空公司”。“航空”修饰“公司”时直接连用，复合词之间不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12203, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "现在很多年轻人想学航空公司。", "corrected_sentence": "现在很多年轻人想学航空专业。", "error_description": "错误：“学航空公司”；正确：“学航空专业”。“学”的对象是专业或知识，“公司”是企业，不能用来学。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12205, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
