INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12205, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物（特别是分子）中各个部分的排列方式或结构形式。", "primary_collocate": null, "pronunciation": "gòu xíng", "ipa": "kou˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "为了实现高效巡航，航空工程师必须在气动构型上进行精细权衡，以最大化升阻比——即单位阻力下所能产生的升力，这是衡量飞行效率的关键指标。", "target_word": "构型", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种分子的构型很特别。", "target_word": "构型", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水分子的构型是弯曲的。", "target_word": "构型", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "化学家正在研究这个分子的构型。", "target_word": "构型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "改变构型以后，药的性质也变了。", "target_word": "构型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在黑板上画出了分子构型。", "target_word": "构型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两种药的构型不同，作用也不同。", "target_word": "构型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家用仪器测定了蛋白质的构型。", "target_word": "构型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个化合物有两种不同的构型。", "target_word": "构型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果构型变了，它的功能就会改变。", "target_word": "构型", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种构型", "label": "量词"}, {"form": "分子构型", "label": "复合"}, {"form": "气动构型", "label": "复合"}, {"form": "構型", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "分子或结构中各部分的排列方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c52c201-a9c6-4f97-a07d-ccfe566aedfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12205, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "构型", "is_correct": true, "explanation": "正确：听到的是“构型”（gòu xíng），指分子等物体各部分的排列方式。"}, {"text": "钩形", "is_correct": false, "explanation": "gōu（第一声）与 gòu（第四声）声调不同，钩形指像钩子的形状。"}, {"text": "厚型", "is_correct": false, "explanation": "hòu 与 gòu 声母不同（h 与 g），厚型指厚的类型。"}, {"text": "各型", "is_correct": false, "explanation": "gè 与 gòu 韵母不同（e 与 ou），各型指各种类型。"}, {"text": "豆形", "is_correct": false, "explanation": "dòu 与 gòu 声母不同（d 与 g），豆形指像豆子的形状。"}], "explanations": {"构型": "正确：听到的是“构型”（gòu xíng），指分子等物体各部分的排列方式。", "钩形": "gōu（第一声）与 gòu（第四声）声调不同，钩形指像钩子的形状。", "厚型": "hòu 与 gòu 声母不同（h 与 g），厚型指厚的类型。", "各型": "gè 与 gòu 韵母不同（e 与 ou），各型指各种类型。", "豆形": "dòu 与 gòu 声母不同（d 与 g），豆形指像豆子的形状。"}, "sentence_index": null, "correct_answer": "构型"}, "level_3": {"options": [{"text": "构型", "is_correct": true, "explanation": "正确：“气动构型”指飞行器的外形布局，与“精细权衡”“升阻比”的语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与气动布局、升阻比无关，句子不成立。"}, {"text": "价格", "is_correct": false, "explanation": "语义：升阻比是空气动力指标，不能拿价格去权衡。"}, {"text": "燃料", "is_correct": false, "explanation": "搭配：“气动”修饰外形与布局，不修饰燃料，不说“气动燃料”。"}], "explanations": {"构型": "正确：“气动构型”指飞行器的外形布局，与“精细权衡”“升阻比”的语境相符。", "颜色": "语义：颜色与气动布局、升阻比无关，句子不成立。", "价格": "语义：升阻比是空气动力指标，不能拿价格去权衡。", "燃料": "搭配：“气动”修饰外形与布局，不修饰燃料，不说“气动燃料”。"}, "sentence_index": 0, "correct_answer": "构型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家的构型很稳定。", "explanation": "这里应该用〈结构〉。构型指分子或物体中各部分的具体排列，国家这类抽象组织的组成方式要用结构。"}, {"text": "这部小说的构型很巧妙。", "explanation": "这里应该用〈构思〉。构型指具体物体的排列形式，小说的情节安排要用构思。"}, {"text": "今年的构型很突出。", "explanation": "这里应该用〈特点〉。构型指事物内部各部分的排列结构，年份不具备这种结构，要说特点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12205, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "构型", "is_correct": true, "explanation": "正确：“构型不同”说明两种药的分子排列不同，与“作用也不同”相呼应。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：药物没有年龄，“年龄不同”不能用于两种药。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：药物没有脾气，“脾气不同”在这里不成立。"}, {"text": "容貌", "is_correct": false, "explanation": "体貌：“容貌”指人或动物的外貌，不能用于药物。"}], "explanations": {"构型": "正确：“构型不同”说明两种药的分子排列不同，与“作用也不同”相呼应。", "年龄": "语义：药物没有年龄，“年龄不同”不能用于两种药。", "脾气": "语义：药物没有脾气，“脾气不同”在这里不成立。", "容貌": "体貌：“容貌”指人或动物的外貌，不能用于药物。"}, "sentence_index": 6, "correct_answer": "构型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的构型很清楚，大家都听懂了。", "explanation": "这里应该用〈论证〉。构型指物体的排列结构，不能用来评价人的论证是否清楚。"}, {"text": "这个运动员的构型很有名。", "explanation": "这里应该用〈名气〉。构型指物体的排列结构，人的名声不能用构型，要说名气。"}, {"text": "这次比赛的构型很紧张。", "explanation": "这里应该用〈形势〉。构型指事物各部分的排列结构，比赛的局面状况要用形势。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12205, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个药物有一只稳定的构型。", "corrected_sentence": "这个药物有一种稳定的构型。", "error_description": "量词错误：“构型”前应用量词“种”，“只”用于动物或个体物件，不能用于构型。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12205, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种药构型跟旧的不同。", "corrected_sentence": "这种药的构型跟旧的不同。", "error_description": "“的”遗漏：修饰语“药”与“构型”之间需要“的”，应说“这种药的构型”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
