INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12206, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "权衡指对两个或更多选项进行比较，评估它们的优缺点，从而做出决定。", "primary_collocate": null, "pronunciation": "quán héng", "ipa": "tɕʰɥɛn³⁵ xɤŋ³⁵", "syllable_count": 2, "sentences": [{"text": "为了实现高效巡航，航空工程师必须在气动构型上进行精细权衡，以最大化升阻比——即单位阻力下所能产生的升力，这是衡量飞行效率的关键指标。", "target_word": "权衡", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "其环境影响必须置于整个资源循环系统中权衡——从原料提取、生产能耗、使用性能到终端处理。", "target_word": "权衡", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "买房子以前，我们要仔细权衡利弊。", "target_word": "权衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他权衡了很久，最后选择留在北京。", "target_word": "权衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找工作时，你应该权衡工资和发展机会。", "target_word": "权衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生帮病人权衡了两种治疗方法的好处和风险。", "target_word": "权衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她权衡过时间和费用，才决定去旅行。", "target_word": "权衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司需要权衡成本和质量。", "target_word": "权衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做重要决定前，请先权衡一下。", "target_word": "权衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我权衡再三，还是拒绝了这份工作。", "target_word": "权衡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "权衡了", "label": "体标"}, {"form": "权衡过", "label": "体标"}, {"form": "权衡着", "label": "体标"}, {"form": "權衡", "label": "繁体"}], "register": "书面", "sense_fingerprint": "比较多个选项的优缺点后再做决定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7833e8da-174d-473c-8fad-ba990596ff35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12206, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "权衡", "is_correct": true, "explanation": "正确。“精细权衡”指仔细比较各方案的利弊，与“以最大化升阻比”的目的相符。"}, {"text": "忽视", "is_correct": false, "explanation": "搭配：“忽视”的宾语是事情或意见，不能与“进行精细”连用。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：给气动构型“装饰”与“最大化升阻比”的目的毫不相关。"}, {"text": "损坏", "is_correct": false, "explanation": "语义：“精细损坏”与“以最大化升阻比”的目的相互矛盾。"}], "explanations": {"权衡": "正确。“精细权衡”指仔细比较各方案的利弊，与“以最大化升阻比”的目的相符。", "忽视": "搭配：“忽视”的宾语是事情或意见，不能与“进行精细”连用。", "装饰": "语义：给气动构型“装饰”与“最大化升阻比”的目的毫不相关。", "损坏": "语义：“精细损坏”与“以最大化升阻比”的目的相互矛盾。"}, "sentence_index": 0, "correct_answer": "权衡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人权衡了那堵墙。", "explanation": "这里应该用〈粉刷〉。权衡是比较利弊后做决定的活动，不用于粉刷墙面这类动作。"}, {"text": "他权衡了眼泪。", "explanation": "这里应该用〈擦干〉。权衡的对象是方案或利弊，不能用于眼泪等具体事物。"}, {"text": "这个孩子权衡了一只小猫。", "explanation": "这里应该用〈抚摸〉。权衡指比较选项的利弊，不用于抚摸动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12206, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "权衡", "is_correct": true, "explanation": "正确。“权衡过时间和费用”指比较之后再做决定，与“才决定去旅行”相符。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”的宾语是房屋、道路等，不能说“修建时间和费用”。"}, {"text": "惩罚", "is_correct": false, "explanation": "搭配：“惩罚”的对象是人或行为，不能说“惩罚时间和费用”。"}, {"text": "忘却", "is_correct": false, "explanation": "语义：“忘却”指不再记得，与“经过比较后才决定”的审慎语义相矛盾。"}], "explanations": {"权衡": "正确。“权衡过时间和费用”指比较之后再做决定，与“才决定去旅行”相符。", "修建": "搭配：“修建”的宾语是房屋、道路等，不能说“修建时间和费用”。", "惩罚": "搭配：“惩罚”的对象是人或行为，不能说“惩罚时间和费用”。", "忘却": "语义：“忘却”指不再记得，与“经过比较后才决定”的审慎语义相矛盾。"}, "sentence_index": 6, "correct_answer": "权衡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他权衡了那道污渍。", "explanation": "这里应该用〈擦掉〉。权衡指比较利弊后做决定，不用于擦去污渍这类清除动作。"}, {"text": "这个学生权衡了教室。", "explanation": "这里应该用〈打扫〉。权衡的对象是方案或利弊，不用于打扫场所。"}, {"text": "她权衡了一首歌。", "explanation": "这里应该用〈唱〉。权衡是比较利弊的思考活动，不用于演唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们先权衡一个利弊。", "corrected_sentence": "我们先权衡一下利弊。", "error_description": "量词误用。“一个”不能用于“利弊”，动词“权衡”后的动量补语应为“一下”，即“权衡一下利弊”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们已经权衡得这个方案的风险。", "corrected_sentence": "我们已经权衡过这个方案的风险。", "error_description": "补语与体标混淆。“得”不能直接接在“权衡”后带宾语，表示完成经历的体标应为“过”，即“权衡过这个方案的风险”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12207, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最小化", "is_correct": true, "explanation": "与“最大化”构成反义：一个指达到最大程度，一个指达到最小程度。"}, {"text": "保持", "is_correct": false, "explanation": "无反义关系：“保持”指维持原状，与“使某事达到最大程度”不构成相反。"}, {"text": "研究", "is_correct": false, "explanation": "无反义关系：“研究”指探究事理，与“使某事达到最大程度”无相反关系。"}, {"text": "收集", "is_correct": false, "explanation": "无反义关系：“收集”指聚拢事物，与“使某事达到最大程度”无相反关系。"}], "correct_answer": "最小化", "explanations": {"最小化": "与“最大化”构成反义：一个指达到最大程度，一个指达到最小程度。", "保持": "无反义关系：“保持”指维持原状，与“使某事达到最大程度”不构成相反。", "研究": "无反义关系：“研究”指探究事理，与“使某事达到最大程度”无相反关系。", "收集": "无反义关系：“收集”指聚拢事物，与“使某事达到最大程度”无相反关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12207, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最小化", "is_correct": true, "explanation": "与“最大化”构成反义：一个指达到最大程度，一个指达到最小程度。"}, {"text": "讨论", "is_correct": false, "explanation": "无反义关系：“讨论”指交换意见，与“使某事达到最大程度”无相反关系。"}, {"text": "喜欢", "is_correct": false, "explanation": "无反义关系：“喜欢”指心理态度，与“使某事达到最大程度”无相反关系。"}, {"text": "整理", "is_correct": false, "explanation": "无反义关系：“整理”指使有秩序，与“使某事达到最大程度”无相反关系。"}], "correct_answer": "最小化", "explanations": {"最小化": "与“最大化”构成反义：一个指达到最大程度，一个指达到最小程度。", "讨论": "无反义关系：“讨论”指交换意见，与“使某事达到最大程度”无相反关系。", "喜欢": "无反义关系：“喜欢”指心理态度，与“使某事达到最大程度”无相反关系。", "整理": "无反义关系：“整理”指使有秩序，与“使某事达到最大程度”无相反关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12207, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使某事物达到最大程度或极限。", "primary_collocate": null, "pronunciation": "zuì dà huà", "ipa": "tsweɪ˥˩ ta˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "此类传统实践往往植根于长期的环境观察与代际传承，其核心在于最大化水分利用效率，同时维持生态系统的可持续性。", "target_word": "最大化", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "为了实现高效巡航，航空工程师必须在气动构型上进行精细权衡，以最大化升阻比——即单位阻力下所能产生的升力，这是衡量飞行效率的关键指标。", "target_word": "最大化", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "老板想最大化公司的利润。", "target_word": "最大化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要最大化利用这块空地。", "target_word": "最大化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把学习时间最大化了。", "target_word": "最大化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想最大化客户的满意度。", "target_word": "最大化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理希望最大化工厂的产量。", "target_word": "最大化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用新方法最大化土地的收成。", "target_word": "最大化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生要最大化每天的学习效果。", "target_word": "最大化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划能最大化我们的收益。", "target_word": "最大化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "最大化了", "label": "体标"}], "register": "书面", "sense_fingerprint": "使某事物达到最大程度或极限", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e003bea1-9a51-40cb-91ca-bdd0a7fd19d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12207, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最大化", "is_correct": true, "explanation": "与“核心在于”搭配，指使水分利用效率达到最大程度，与后文“维持生态系统的可持续性”的语境一致。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：“忽视”与“核心在于”所指的主动优化方向相反，句意不通。"}, {"text": "节约", "is_correct": false, "explanation": "搭配：“节约”用于水、金钱等资源，不能说节约“效率”。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”意为不再进行，与“核心在于”后的效率优化之意相反。"}], "explanations": {"最大化": "与“核心在于”搭配，指使水分利用效率达到最大程度，与后文“维持生态系统的可持续性”的语境一致。", "忽视": "语义：“忽视”与“核心在于”所指的主动优化方向相反，句意不通。", "节约": "搭配：“节约”用于水、金钱等资源，不能说节约“效率”。", "放弃": "语义：“放弃”意为不再进行，与“核心在于”后的效率优化之意相反。"}, "sentence_index": 0, "correct_answer": "最大化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司的收入最大化了一点点。", "explanation": "这里应该用〈增加〉。最大化指达到最高限度，不能与“一点点”这类小幅度搭配；收入小幅上升应说〈增加〉。"}, {"text": "我们把假期最大化到三天。", "explanation": "这里应该用〈延长〉。最大化指达到极限，不用来指定某个具体数值；把假期定为三天应说〈延长〉。"}, {"text": "工人们把产量最大化了一倍。", "explanation": "这里应该用〈提高〉。最大化表示达到最大值，不表示按倍数增长；产量翻倍应说〈提高〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12207, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最大化", "is_correct": true, "explanation": "与“希望”搭配，指使工厂的产量达到最大，符合经理的期望。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是风景、作品等，不说欣赏“产量”。"}, {"text": "感谢", "is_correct": false, "explanation": "搭配：“感谢”的对象是人或行为，不能说感谢“产量”。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：“回忆”指向过去，与“希望”所指的将来愿望相矛盾。"}], "explanations": {"最大化": "与“希望”搭配，指使工厂的产量达到最大，符合经理的期望。", "欣赏": "搭配：“欣赏”的对象是风景、作品等，不说欣赏“产量”。", "感谢": "搭配：“感谢”的对象是人或行为，不能说感谢“产量”。", "回忆": "语义：“回忆”指向过去，与“希望”所指的将来愿望相矛盾。"}, "sentence_index": 6, "correct_answer": "最大化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子这一年最大化了很多。", "explanation": "这里应该用〈长高〉。最大化用于可以人为达到极限的事物，身高是自然增长，不能说最大化。"}, {"text": "他把复习时间最大化了一半。", "explanation": "这里应该用〈缩短〉。最大化表示达到最大程度，不表示减少一半；时间减少应说〈缩短〉。"}, {"text": "奶奶的病终于最大化了。", "explanation": "这里应该用〈痊愈〉。最大化不用于疾病康复，病好了应说〈痊愈〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12207, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天要最大化了效率。", "corrected_sentence": "我明天要最大化效率。", "error_description": "错误：“要”表示将来，动词后又加“了”，与将来时间词“明天”矛盾；应去掉“了”，写作“我明天要最大化效率”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12207, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有最大化了收益。", "corrected_sentence": "他没有最大化收益。", "error_description": "错误：否定句“没有”后的动词不能再加“了”，应去掉“了”，写作“他没有最大化收益”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
