INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12208, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "升力与阻力的合称，是空气动力学中的一对拮抗作用。", "primary_collocate": null, "pronunciation": "shēng zǔ", "ipa": "ʂɤŋ˥ tsu˨˩˦", "syllable_count": 2, "sentences": [{"text": "在空气动力学中，升力与阻力合起来称为升阻，两者相互拮抗。", "target_word": "升阻", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "机翼的形状会影响升阻。", "target_word": "升阻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "风洞实验可以测出升阻。", "target_word": "升阻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "飞机的升阻会随速度改变。", "target_word": "升阻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师正在计算飞机的升阻。", "target_word": "升阻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机起飞时，升阻很重要。", "target_word": "升阻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机翼变长以后，升阻也变了。", "target_word": "升阻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在课上讲了升阻的变化。", "target_word": "升阻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞行员要了解飞机的升阻。", "target_word": "升阻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果升阻不平衡，飞机就会不稳。", "target_word": "升阻", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "升阻比", "label": "复合"}, {"form": "升阻特性", "label": "复合"}], "register": "书面语", "sense_fingerprint": "空气动力学中升力与阻力的合称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c52c201-a9c6-4f97-a07d-ccfe566aedfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12208, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "升阻", "is_correct": true, "explanation": "正确：“升阻”是升力与阻力的合称，句中正是这样定义的。"}, {"text": "升力", "is_correct": false, "explanation": "语义：升力只是两者之一，不能单独作为二者的合称。"}, {"text": "速度", "is_correct": false, "explanation": "语义：速度不属于升力与阻力，句中的合称与速度无关。"}, {"text": "阻力", "is_correct": false, "explanation": "语义：阻力也只是两者之一，不能单独作为二者的合称。"}], "explanations": {"升阻": "正确：“升阻”是升力与阻力的合称，句中正是这样定义的。", "升力": "语义：升力只是两者之一，不能单独作为二者的合称。", "速度": "语义：速度不属于升力与阻力，句中的合称与速度无关。", "阻力": "语义：阻力也只是两者之一，不能单独作为二者的合称。"}, "sentence_index": 0, "correct_answer": "升阻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只气球的升阻很大，飘得很慢。", "explanation": "这里应该用〈阻力〉。升阻是飞机飞行时升力与阻力的合称，气球靠浮力升空，减慢飘动的是阻力。"}, {"text": "空气中的升阻很大，车子减速很快。", "explanation": "这里应该用〈阻力〉。升阻包含向上的升力，说减速只能用阻力。"}, {"text": "这台发动机的升阻很高，所以加速很快。", "explanation": "这里应该用〈推力〉。升阻是飞机飞行时的升力与阻力，发动机的加速靠推力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12208, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "升阻", "is_correct": true, "explanation": "正确：机翼变长会改变升力与阻力，所以升阻也跟着变。"}, {"text": "味道", "is_correct": false, "explanation": "语义：机翼变长不会改变味道，句子不成立。"}, {"text": "性别", "is_correct": false, "explanation": "语义：机翼没有性别，“性别也变了”不成立。"}, {"text": "相貌", "is_correct": false, "explanation": "体貌：“相貌”指人或动物的外貌，不能用于机翼。"}], "explanations": {"升阻": "正确：机翼变长会改变升力与阻力，所以升阻也跟着变。", "味道": "语义：机翼变长不会改变味道，句子不成立。", "性别": "语义：机翼没有性别，“性别也变了”不成立。", "相貌": "体貌：“相貌”指人或动物的外貌，不能用于机翼。"}, "sentence_index": 6, "correct_answer": "升阻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的升阻增加了五公斤。", "explanation": "这里应该用〈重量〉。升阻是力的合称，不以公斤计量，也不能说增加了多少公斤。"}, {"text": "这块布的升阻很大，拉起来很费劲。", "explanation": "这里应该用〈摩擦力〉。升阻只指飞机飞行时的升力与阻力，布料之间的阻碍不用升阻。"}, {"text": "这根绳子的升阻很大，很难松开。", "explanation": "这里应该用〈拉力〉。升阻只指飞机飞行时的升力与阻力，绳子受到的拉力要说拉力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机翼的一本升阻变大了。", "corrected_sentence": "机翼的升阻变大了。", "error_description": "量词错误：“本”用于书籍、册子，不能修饰升阻；直接说“机翼的升阻”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次改装后，升阻的也变大了。", "corrected_sentence": "这次改装后，升阻也变大了。", "error_description": "“的”位置错误：“升阻”后不能直接加“的”，应说“升阻也变大了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
