INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12209, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一个人能力范围内能够做到的最大限度；常用于‘尽自己所能’等固定搭配。", "primary_collocate": null, "pronunciation": "suǒ néng", "ipa": "swo˨˩˦ nəŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我会尽自己所能帮助你。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他尽自己所能照顾老人。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都尽自己所能去帮忙。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师尽其所能教好每个学生。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要尽我们所能保护环境。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她尽自己所能完成了工作。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生尽他所能救那个孩子。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了家人，他做了他所能做的一切。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你尽你所能，把事情做好。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈尽她所能给孩子最好的。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "自己能力范围内能做到的最大限度，多用于尽……所能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecb8803a-6dd5-492a-a974-71a190af6a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12209, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所能", "is_correct": true, "explanation": "正确：所能指自己能力范围内能做到的最大限度，与“尽自己”搭配。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：钱包是装钱的物件，不是能力范围，不能与“尽”构成这一意义。"}, {"text": "方向", "is_correct": false, "explanation": "语义：方向指朝向或目标，不指能力所能达到的程度。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“尽”一般接“力”“能”等表示能力的词，不接“时间”。"}], "explanations": {"所能": "正确：所能指自己能力范围内能做到的最大限度，与“尽自己”搭配。", "钱包": "语义：钱包是装钱的物件，不是能力范围，不能与“尽”构成这一意义。", "方向": "语义：方向指朝向或目标，不指能力所能达到的程度。", "时间": "搭配：“尽”一般接“力”“能”等表示能力的词，不接“时间”。"}, "sentence_index": 0, "correct_answer": "所能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的所能很强。", "explanation": "这里应该用〈能力〉。所能只用于“尽……所能”等说法，指能力所及的最大限度，不用来形容人的能力强弱。"}, {"text": "他下定了所能，要把书读完。", "explanation": "这里应该用〈决心〉。所能指能力所及的最大限度，不能表示意志和决心。"}, {"text": "他的汉语所能很高。", "explanation": "这里应该用〈水平〉。所能指在某事上能做到的最大限度，不能用来说明语言水平的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12209, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所能", "is_correct": true, "explanation": "正确：尽他所能，即尽他能力范围内的最大限度去救人。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装物品的袋子，不是能力范围，不能与“尽”构成这一意义。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，不指能力所能达到的程度。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“尽”不与“体温”搭配，不能说“尽他体温”。"}], "explanations": {"所能": "正确：尽他所能，即尽他能力范围内的最大限度去救人。", "书包": "语义：书包是装物品的袋子，不是能力范围，不能与“尽”构成这一意义。", "钥匙": "语义：钥匙是开锁的工具，不指能力所能达到的程度。", "体温": "搭配：“尽”不与“体温”搭配，不能说“尽他体温”。"}, "sentence_index": 6, "correct_answer": "所能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的所能很好。", "explanation": "这里应该用〈天气〉。所能指能力所及的最大限度，不能用来描述天气的好坏。"}, {"text": "她的所能很好听。", "explanation": "这里应该用〈声音〉。所能不用来形容声音好听与否，只指能力所及的最大限度。"}, {"text": "这幅画的所能很鲜艳。", "explanation": "这里应该用〈颜色〉。所能不能用来描述事物的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12209, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她决定自己所能去学习。", "corrected_sentence": "她决定尽自己所能去学习。", "error_description": "“所能”前应加“尽”，构成“尽……所能”；这里漏了“尽”，应为“尽自己所能”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12209, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她自己所能陪伴家人。", "corrected_sentence": "她尽自己所能陪伴家人。", "error_description": "错误：漏了“尽”。“尽……所能”是固定说法，应说“尽自己所能”，不能只说“自己所能”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12210, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff4da09-972d-4400-b83f-a50f503e9442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12210, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff4da09-972d-4400-b83f-a50f503e9442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12210, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比较、评定事物的大小、多少、轻重、长短、高低等。", "primary_collocate": null, "pronunciation": "héng liáng", "ipa": "xɤŋ³⁵ ljɑŋ³⁵", "syllable_count": 2, "sentences": [{"text": "为了实现高效巡航，航空工程师必须在气动构型上进行精细权衡，以最大化升阻比——即单位阻力下所能产生的升力，这是衡量飞行效率的关键指标。", "target_word": "衡量", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种潜在的技术异化，迫使我们必须重新审视图灵测试之后的智能评估体系：是否应建立“自主性-责任性”双轴评价框架，以衡量代理在自由决策与社会嵌入之间的平衡能力？", "target_word": "衡量", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们不能只用钱来衡量一个人的价值。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用考试成绩来衡量学生的进步。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衡量一家餐厅好不好，要看菜的味道。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在衡量这两份工作哪一个更适合自己。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要先衡量一下自己的能力，再答应他。", "target_word": "衡量", "complexity_tier": "T3", "furigana": "nǐ yào xiān héng liáng yí xià zì jǐ de néng lì, zài dā yìng tā.", "sentence_source": "generated"}, {"text": "衡量一座城市是否发达，不能只看楼有多高。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用销售额衡量每个员工的工作成绩。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把得失都衡量过了，才做出这个决定。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "衡量了", "label": "完成体"}, {"form": "衡量过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "用标准评定事物的价值或好坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15509b16-687f-4575-9b2c-b1c6ed693810') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "衡量", "is_correct": true, "explanation": "正确。衡量指依标准评定事物的好坏高低，与“这是……飞行效率的关键指标”相符。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”的施事须是有审美感受的人，指标不能欣赏飞行效率。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”的施事须是人，关键指标不能表扬飞行效率。"}, {"text": "伤害", "is_correct": false, "explanation": "搭配：“伤害”的宾语多是人、身体或感情，不能接“飞行效率”。"}], "explanations": {"衡量": "正确。衡量指依标准评定事物的好坏高低，与“这是……飞行效率的关键指标”相符。", "欣赏": "语义：“欣赏”的施事须是有审美感受的人，指标不能欣赏飞行效率。", "表扬": "语义：“表扬”的施事须是人，关键指标不能表扬飞行效率。", "伤害": "搭配：“伤害”的宾语多是人、身体或感情，不能接“飞行效率”。"}, "sentence_index": 0, "correct_answer": "衡量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我衡量今天会下雨。", "explanation": "这里应该用〈估计〉。衡量是依据标准比较、评定已有事物，对未来会不会发生的推测要说估计。"}, {"text": "他一眼就衡量出那是他的朋友。", "explanation": "这里应该用〈辨认〉。衡量是比较、评定事物的大小、多少等，认出某人是谁要说辨认。"}, {"text": "他衡量了三加五的结果。", "explanation": "这里应该用〈计算〉。衡量是比较评定事物的数量或价值，求算术结果要说计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff4da09-972d-4400-b83f-a50f503e9442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "衡量", "is_correct": true, "explanation": "正确。衡量指先比较评定，与“你要先衡量一下自己的能力，再答应他”相符。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”的对象是场所或物品，不能打扫能力。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”的宾语是食物，不能接“能力”。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”多接机器、房屋等具体物件，不能接“能力”。"}], "explanations": {"衡量": "正确。衡量指先比较评定，与“你要先衡量一下自己的能力，再答应他”相符。", "打扫": "语义：“打扫”的对象是场所或物品，不能打扫能力。", "吃掉": "搭配：“吃掉”的宾语是食物，不能接“能力”。", "修理": "搭配：“修理”多接机器、房屋等具体物件，不能接“能力”。"}, "sentence_index": 6, "correct_answer": "衡量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他衡量出了一阵笑声。", "explanation": "这里应该用〈发出〉。衡量是依标准比较、评定事物，笑声是发出的，应说发出。"}, {"text": "他一脚衡量了那个球，然后射进了球门。", "explanation": "这里应该用〈踢〉。衡量是比较、评定事物的大小等，用脚击打球要说踢。"}, {"text": "他把那一大片草原衡量成了一首诗。", "explanation": "这里应该用〈写〉。衡量是比较、评定事物，把景物写成诗要说写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff4da09-972d-4400-b83f-a50f503e9442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他衡量了出两种方案的差别。", "corrected_sentence": "他衡量出了两种方案的差别。", "error_description": "“出”是结果补语，应紧跟动词“衡量”，写作“衡量出了”，不能放在“了”的后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff4da09-972d-4400-b83f-a50f503e9442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在衡量了这些方案。", "corrected_sentence": "他正在衡量这些方案。", "error_description": "“正在”表示动作正在进行，不能与完成体“了”同用，应去掉“了”，写作“他正在衡量这些方案”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff4da09-972d-4400-b83f-a50f503e9442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
