INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12211, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12211, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "学科是按照知识性质划分的教学科目，如语文、数学、物理等。", "primary_collocate": null, "pronunciation": "xué kē", "ipa": "ɕɥɛ˧˥ kʰɤ˥", "syllable_count": 2, "sentences": [{"text": "从工程实现的角度看，飞机的设计是一场多学科耦合的优化博弈。", "target_word": "学科", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "你最喜欢哪门学科？", "target_word": "学科", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "物理是我最难的学科。", "target_word": "学科", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "数学是一门重要的学科。", "target_word": "学科", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大学里有很多不同的学科。", "target_word": "学科", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对每个学科都有兴趣。", "target_word": "学科", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "化学是一门很有用的学科。", "target_word": "学科", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子上了中学，学科多了很多。", "target_word": "学科", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想选一门新的学科来学。", "target_word": "学科", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果这个学科太难，你就换一个。", "target_word": "学科", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "一门学科", "label": "量词"}, {"form": "交叉学科", "label": "复合"}, {"form": "基础学科", "label": "复合"}, {"form": "學科", "label": "繁体"}], "register": "中性", "sense_fingerprint": "按知识性质划分的教学科目或知识领域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c52c201-a9c6-4f97-a07d-ccfe566aedfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12211, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：“学生”指人，不指知识门类，与“耦合的优化博弈”的技术语境不合。"}, {"text": "工人", "is_correct": false, "explanation": "搭配：“耦合”多与“因素、系统、学科”等搭配，不能与“工人”组成合理的说法。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料与工程设计无关，不能说“多饮料耦合”。"}, {"text": "学科", "is_correct": true, "explanation": "“学科”指按知识性质划分的领域，“多学科耦合”说的是多个学科相互关联，符合工程设计的语境。"}], "explanations": {"学生": "语义：“学生”指人，不指知识门类，与“耦合的优化博弈”的技术语境不合。", "工人": "搭配：“耦合”多与“因素、系统、学科”等搭配，不能与“工人”组成合理的说法。", "饮料": "语义：饮料与工程设计无关，不能说“多饮料耦合”。", "学科": "“学科”指按知识性质划分的领域，“多学科耦合”说的是多个学科相互关联，符合工程设计的语境。"}, "sentence_index": 0, "correct_answer": "学科"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老先生很有学科。", "explanation": "这里应该用〈学问〉。“学问”指一个人的知识修养，可以说“很有学问”；“学科”是知识的分类，不能用来形容人的修养。"}, {"text": "我买了一本学科。", "explanation": "这里应该用〈门〉。学科用量词“门”计量，如“一门学科”；“本”用于书籍，学科不是书，不能用“本”。"}, {"text": "今天上午我们上了两节学科。", "explanation": "这里应该用〈课〉。“上两节”指课时，学科是知识分类，不能按节计数，也不能说“上学科”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12211, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外语", "is_correct": false, "explanation": "语义：化学是一门学科，不是一门语言，“很有用的外语”与句中的主语不符。"}, {"text": "武艺", "is_correct": false, "explanation": "语义：“武艺”指武术技艺，与化学的性质不符。"}, {"text": "厨艺", "is_correct": false, "explanation": "搭配：“厨艺”只指烹饪技艺，不能以化学作为它的类别。"}, {"text": "学科", "is_correct": true, "explanation": "“学科”指一类知识，“化学是一门很有用的学科”符合句意。"}], "explanations": {"外语": "语义：化学是一门学科，不是一门语言，“很有用的外语”与句中的主语不符。", "武艺": "语义：“武艺”指武术技艺，与化学的性质不符。", "厨艺": "搭配：“厨艺”只指烹饪技艺，不能以化学作为它的类别。", "学科": "“学科”指一类知识，“化学是一门很有用的学科”符合句意。"}, "sentence_index": 6, "correct_answer": "学科"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把学科放进了书包。", "explanation": "这里应该用〈教材〉。教材是可以拿在手里的书，学科是抽象的知识分类，不能放进书包。"}, {"text": "她是一位很有名的学科。", "explanation": "这里应该用〈学者〉。“学者”指有学问的人，可以说“很有名的学者”；“学科”指知识分类，不能指人。"}, {"text": "这位同学写了一篇很好的学科。", "explanation": "这里应该用〈论文〉。论文可以写成“一篇”，学科是知识分类，不能被“写”，也不能用“篇”计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12211, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所大学开设了十几本学科。", "corrected_sentence": "这所大学开设了十几门学科。", "error_description": "量词错误：“学科”应使用量词“门”，“本”用于书籍，不能用于学科。正确说法是“十几门学科”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12211, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几门学科们都很难。", "corrected_sentence": "这几门学科都很难。", "error_description": "“们”只用于指人的名词，“学科”后面不能加“们”。正确说法是“这几门学科都很难”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12214, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12214, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12214, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "复合材料是由两种或两种以上不同性质的材料，通过物理或化学方法组合而成的新型材料，通常具有比单一材料更优越的性能。", "primary_collocate": null, "pronunciation": "fù hé cái liào", "ipa": "fu˥˩ xɤ˧˥ tsʰaɪ˧˥ ljaʊ˥˩", "syllable_count": 4, "sentences": [{"text": "传统风车的水平轴结构被保留，但空气动力学模拟与复合材料的应用，使叶片长度突破百米级，扫风面积呈几何倍数增长。", "target_word": "复合材料", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "材料科学的进步使得复合材料得以广泛应用，不仅减轻了结构重量，还增强了疲劳耐久性；计算流体动力学（CFD）的发展则使工程师能够在虚拟风洞中模拟极端工况下的气动性能，从而在原型制造前完成多轮迭代。", "target_word": "复合材料", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种飞机机身主要使用复合材料。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "复合材料比普通钢材轻得多。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "碳纤维增强树脂是一种常见的复合材料。", "target_word": "复合材料", "complexity_tier": "T3", "furigana": "fù hé cái liào", "sentence_source": "generated"}, {"text": "工程师用复合材料制造了新的叶片。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "复合材料由两种以上的材料组成。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自行车车架换成复合材料后更轻了。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的护栏采用了复合材料。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "复合材料的强度高，不容易生锈。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种复合材料", "label": "量词搭配"}, {"form": "碳纤维复合材料", "label": "复合词"}, {"form": "複合材料", "label": "繁体"}], "register": "书面", "sense_fingerprint": "由两种以上不同性质材料组合而成、性能更优的新型材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c6fe7c9-33e8-4c2f-b2e6-ccbf82b54954') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12214, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "复合材料", "is_correct": true, "explanation": "复合材料：由多种材料组合而成，符合句中关于叶片结构材料的语境。"}, {"text": "摄影", "is_correct": false, "explanation": "语义：摄影是拍照技术，与叶片结构和空气动力学无关，句意不通。"}, {"text": "饮食", "is_correct": false, "explanation": "语义：饮食指吃喝，不能用于风车叶片的结构设计。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：「应用」一般不与咖啡搭配，句中要的是可用于结构的材料。"}], "explanations": {"复合材料": "复合材料：由多种材料组合而成，符合句中关于叶片结构材料的语境。", "摄影": "语义：摄影是拍照技术，与叶片结构和空气动力学无关，句意不通。", "饮食": "语义：饮食指吃喝，不能用于风车叶片的结构设计。", "咖啡": "搭配：「应用」一般不与咖啡搭配，句中要的是可用于结构的材料。"}, "sentence_index": 0, "correct_answer": "复合材料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只复合材料。", "explanation": "这里应该用〈种〉。复合材料是一类物质，量词用种，「只」多用于动物。"}, {"text": "这家餐厅的菜里加了复合材料。", "explanation": "这里应该用〈调料〉。复合材料是工业用材料，不能用来调味。"}, {"text": "这包复合材料可以洗衣服。", "explanation": "这里应该用〈洗衣粉〉。复合材料不是清洁用品，不能用来洗衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12214, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "复合材料", "is_correct": true, "explanation": "复合材料：由两种以上材料组成，符合句中的定义。"}, {"text": "纯金属", "is_correct": false, "explanation": "语义：纯金属是单一成分，与「由两种以上的材料组成」的意思矛盾。"}, {"text": "单一材料", "is_correct": false, "explanation": "语义：单一材料只含一种成分，与句中「两种以上」的说法相反。"}, {"text": "金刚石", "is_correct": false, "explanation": "语义：金刚石是单一的碳晶体，不由两种以上材料组成，句意不符。"}], "explanations": {"复合材料": "复合材料：由两种以上材料组成，符合句中的定义。", "纯金属": "语义：纯金属是单一成分，与「由两种以上的材料组成」的意思矛盾。", "单一材料": "语义：单一材料只含一种成分，与句中「两种以上」的说法相反。", "金刚石": "语义：金刚石是单一的碳晶体，不由两种以上材料组成，句意不符。"}, "sentence_index": 6, "correct_answer": "复合材料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上喝一杯复合材料。", "explanation": "这里应该用〈牛奶〉。复合材料不能饮用，不能当作饮料。"}, {"text": "这个孩子在复合材料里睡觉。", "explanation": "这里应该用〈床〉。复合材料不是睡觉的地方，睡觉要在床上。"}, {"text": "我用复合材料写作业。", "explanation": "这里应该用〈铅笔〉。复合材料不能用来写字，写字要用笔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12214, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工程师复合材料做了一个外壳。", "corrected_sentence": "工程师用复合材料做了一个外壳。", "error_description": "错误形式：「工程师复合材料做了一个外壳」缺少介词「用」。正确形式：「工程师用复合材料做了一个外壳」。「用」引出所用的材料，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12214, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "机翼蒙皮用的是一颗复合材料。", "corrected_sentence": "机翼蒙皮用的是一块复合材料。", "error_description": "错误形式：「一颗复合材料」，量词错误。正确形式：「一块复合材料」。「颗」用于粒状物，「块」用于块状材料。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12215, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加重", "is_correct": true, "explanation": "“加重”指使负担、痛苦等程度变大，与“减轻”构成反义关系。"}, {"text": "赞成", "is_correct": false, "explanation": "与“减轻”没有反义关系，“赞成”的意思是同意某种意见。"}, {"text": "建立", "is_correct": false, "explanation": "与“减轻”没有反义关系，“建立”的意思是创立。"}, {"text": "保持", "is_correct": false, "explanation": "与“减轻”没有反义关系，“保持”的意思是维持原样。"}], "correct_answer": "加重", "explanations": {"加重": "“加重”指使负担、痛苦等程度变大，与“减轻”构成反义关系。", "赞成": "与“减轻”没有反义关系，“赞成”的意思是同意某种意见。", "建立": "与“减轻”没有反义关系，“建立”的意思是创立。", "保持": "与“减轻”没有反义关系，“保持”的意思是维持原样。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12215, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加重", "is_correct": true, "explanation": "“加重”指使负担变大，与“减轻”构成反义关系。"}, {"text": "完成", "is_correct": false, "explanation": "与“减轻”没有反义关系，“完成”的意思是做成某件事。"}, {"text": "观察", "is_correct": false, "explanation": "与“减轻”没有反义关系，“观察”的意思是仔细看。"}, {"text": "发展", "is_correct": false, "explanation": "与“减轻”没有反义关系，“发展”的意思是向前变化。"}], "correct_answer": "加重", "explanations": {"加重": "“加重”指使负担变大，与“减轻”构成反义关系。", "完成": "与“减轻”没有反义关系，“完成”的意思是做成某件事。", "观察": "与“减轻”没有反义关系，“观察”的意思是仔细看。", "发展": "与“减轻”没有反义关系，“发展”的意思是向前变化。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12215, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使重量、程度、负担等变小或变少。", "primary_collocate": null, "pronunciation": "jiǎn qīng", "ipa": "tɕjɛn˨˩ tɕʰiŋ˥˥", "syllable_count": 2, "sentences": [{"text": "医生给他开了药，减轻了他的痛苦。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法可以减轻我们的工作负担。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈想减轻孩子学习的压力。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府减轻了农民的税收负担。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药以后，他的头疼减轻了。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们帮忙做家务，减轻了妈妈的辛苦。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用笑话减轻大家的紧张。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱减轻了他家的经济困难。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的服务能减轻病人的担心。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校减轻了学生的作业负担。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "减轻了", "label": "完成体"}, {"form": "减轻过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "使负担、痛苦、压力等程度变小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c52c201-a9c6-4f97-a07d-ccfe566aedfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12215, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忍受", "is_correct": false, "explanation": "语义：“忍受”指自己承受，与“医生给他开了药”的治疗语境不合。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”的宾语多为愉快的事，不能与“痛苦”搭配。"}, {"text": "制造", "is_correct": false, "explanation": "语义：“制造”表示造成某种结果，医生开药却“制造痛苦”，与句意相反。"}, {"text": "减轻", "is_correct": true, "explanation": "“减轻”指使痛苦变少，与“医生给他开了药”的治疗语境一致。"}], "explanations": {"忍受": "语义：“忍受”指自己承受，与“医生给他开了药”的治疗语境不合。", "享受": "搭配：“享受”的宾语多为愉快的事，不能与“痛苦”搭配。", "制造": "语义：“制造”表示造成某种结果，医生开药却“制造痛苦”，与句意相反。", "减轻": "“减轻”指使痛苦变少，与“医生给他开了药”的治疗语境一致。"}, "sentence_index": 0, "correct_answer": "减轻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这学期班里减轻了三个学生。", "explanation": "这里应该用〈减少〉。减少用于人数、数量；减轻用于重量、负担、痛苦等，不用于人数。"}, {"text": "今天的气温减轻了五度。", "explanation": "这里应该用〈降低〉。气温的下降用“降低”；减轻只用于负担、痛苦等，不用于气温。"}, {"text": "这条新路减轻了三十分钟的路程。", "explanation": "这里应该用〈缩短〉。路程和时间的缩减用“缩短”；减轻不用于路程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12215, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加剧", "is_correct": false, "explanation": "语义：“加剧”指使程度更严重，与“想用笑话”的目的相反。"}, {"text": "分担", "is_correct": false, "explanation": "搭配：“分担”多接负担、任务，不接“紧张”。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指赞赏，与“紧张”这种情绪不符。"}, {"text": "减轻", "is_correct": true, "explanation": "“减轻”指使紧张的程度变小，与“想用笑话”的目的一致。"}], "explanations": {"加剧": "语义：“加剧”指使程度更严重，与“想用笑话”的目的相反。", "分担": "搭配：“分担”多接负担、任务，不接“紧张”。", "欣赏": "语义：“欣赏”指赞赏，与“紧张”这种情绪不符。", "减轻": "“减轻”指使紧张的程度变小，与“想用笑话”的目的一致。"}, "sentence_index": 6, "correct_answer": "减轻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的跑步速度减轻了一些。", "explanation": "这里应该用〈减慢〉。减慢指速度变慢，用于速度；减轻用于重量、负担、痛苦，不能用于速度。"}, {"text": "这次打击减轻了他的信心。", "explanation": "这里应该用〈削弱〉。削弱用于信心、力量等；减轻只用于负担、痛苦，不用于信心。"}, {"text": "这次旅行减轻了许多乐趣。", "explanation": "这里应该用〈减少〉。减少指变少，可以说减少乐趣；减轻只用于重量、负担、痛苦等，不用于乐趣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12215, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他曾经减轻了过我的压力。", "corrected_sentence": "他曾经减轻过我的压力。", "error_description": "助词错误：“减轻”后加“过”表示经历，不能再加“了”。正确说法是“减轻过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12215, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的压力减轻地很快。", "corrected_sentence": "他的压力减轻得很快。", "error_description": "结构错误：“减轻”作补语时用“得”，不用“地”；“地”用于动词前修饰动词。正确说法是“减轻得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
