INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12221, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指设备、机器或系统在实际运行或工作过程中所处的状态、条件及其表现。", "primary_collocate": null, "pronunciation": "gōng kuàng", "ipa": "kʊŋ⁵⁵ kʰwɑŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "材料科学的进步使得复合材料得以广泛应用，不仅减轻了结构重量，还增强了疲劳耐久性；计算流体动力学（CFD）的发展则使工程师能够在虚拟风洞中模拟极端工况下的气动性能，从而在原型制造前完成多轮迭代。", "target_word": "工况", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这台机器在不同工况下，声音也不一样。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在检查发动机的工况。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在高温工况下，机器很容易坏。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台水泵的工况很好，可以继续用。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先了解设备的工况，再决定怎么修。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑屏幕上显示着机器现在的工况。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车在不同工况下的油耗差别很大。", "target_word": "工况", "complexity_tier": "T3", "furigana": "gōng kuàng", "sentence_source": "generated"}, {"text": "工人每天都记录机器的工况。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的风机在各种工况下都很安静。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工況", "label": "繁体"}, {"form": "设计工况", "label": "复合"}, {"form": "额定工况", "label": "复合"}], "register": "专业", "sense_fingerprint": "工况：设备在实际运行中所处的状态、条件及其表现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24631489-7be5-43ad-b7ec-de458e1dff98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12221, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工况", "is_correct": true, "explanation": "正确：工况指设备的运行状态和条件，与“极端……下的气动性能”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“极端颜色下的气动性能”不通，颜色与气动性能无关。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口不能作为模拟的条件，与“模拟……下的气动性能”冲突。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“极端”修饰条件、环境，不修饰价格，与“下的气动性能”不搭配。"}], "explanations": {"工况": "正确：工况指设备的运行状态和条件，与“极端……下的气动性能”相符。", "颜色": "语义：“极端颜色下的气动性能”不通，颜色与气动性能无关。", "人口": "语义：人口不能作为模拟的条件，与“模拟……下的气动性能”冲突。", "价格": "搭配：“极端”修饰条件、环境，不修饰价格，与“下的气动性能”不搭配。"}, "sentence_index": 0, "correct_answer": "工况"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他最近的学习工况很好，成绩一直在提高。", "explanation": "这里应该用〈状况〉。“工况”只指机器、设备的运行状态，人的学习情况要用“状况”。"}, {"text": "他家的经济工况在这几年变好了。", "explanation": "这里应该用〈情况〉。“工况”只指设备运行状态，家庭经济情况要用“情况”。"}, {"text": "这部电影的工况很好，很多人去看。", "explanation": "这里应该用〈票房〉。“工况”指设备的运行状态，电影的卖座情况要用“票房”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12221, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工况", "is_correct": true, "explanation": "正确：工况指机器现在的运行状态，屏幕上显示的正是这一状态。"}, {"text": "味道", "is_correct": false, "explanation": "语义：机器没有可以被屏幕显示的味道，与显示的运行数据不符。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”指出生日期，不能用来表示机器当前的运行状态。"}, {"text": "作者", "is_correct": false, "explanation": "搭配：“显示着……的”后接状态或数值，“作者”不能与之搭配。"}], "explanations": {"工况": "正确：工况指机器现在的运行状态，屏幕上显示的正是这一状态。", "味道": "语义：机器没有可以被屏幕显示的味道，与显示的运行数据不符。", "生日": "语义：“生日”指出生日期，不能用来表示机器当前的运行状态。", "作者": "搭配：“显示着……的”后接状态或数值，“作者”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "工况"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "最近股市的工况很好，很多股票都在涨。", "explanation": "这里应该用〈行情〉。“工况”指设备运行状态，股市走势要用“行情”。"}, {"text": "现场的工况很热烈，大家都在唱歌。", "explanation": "这里应该用〈气氛〉。“工况”不能用来形容人群的情绪和现场氛围。"}, {"text": "病人的工况很稳定，医生说可以出院。", "explanation": "这里应该用〈病情〉。“工况”只用于设备，病人的病情要用“病情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12221, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机器在一只高温工况下运行。", "corrected_sentence": "机器在一种高温工况下运行。", "error_description": "错误：“一只”。正确：“一种”。“工况”是抽象名词，“只”用于有个体的具体事物，应用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12221, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台设备有很好工况。", "corrected_sentence": "这台设备有很好的工况。", "error_description": "错误：“很好工况”，漏了“的”。正确：“很好的工况”。“很好”作定语修饰名词时要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
