INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12223, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12223, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指最初、未改变过的形状或样式。", "primary_collocate": null, "pronunciation": "yuán xíng", "ipa": "ɥɛn˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "工匠修复这座古塔时，严格依照史料与遗存构件，力求还原它最初的原型，使修复后的外形与建成时基本一致。", "target_word": "原型", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这座老桥至今还保留着原型。", "target_word": "原型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人修好了这座塔，但还能看出原型。", "target_word": "原型", "complexity_tier": "T3", "furigana": "gōngrén xiū hǎo le zhè zuò tǎ, dàn hái néng kàn chū yuánxíng.", "sentence_source": "generated"}, {"text": "老街重建时，设计师尽量保持原型。", "target_word": "原型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座庙翻修后，完全看不出原型了。", "target_word": "原型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花瓶碎成几块，已经没有原型了。", "target_word": "原型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把旧椅子改了很多，已经不是原型了。", "target_word": "原型", "complexity_tier": "T3", "furigana": "tā bǎ jiù yǐzi gǎi le hěn duō, yǐjīng bú shì yuánxíng le.", "sentence_source": "generated"}, {"text": "这幅画修补以后，还能看出原型。", "target_word": "原型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道这座古塔的原型是什么样吗？", "target_word": "原型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修钟楼前，老师傅先弄清了它的原型。", "target_word": "原型", "complexity_tier": "T3", "furigana": "xiū zhōnglóu qián, lǎo shīfu xiān nòng qīng le tā de yuánxíng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "原型：事物最初、未改变过的形状或样式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f775cb0c-f64a-45de-b26d-fcb784c8d131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12223, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原型", "is_correct": true, "explanation": "原型：指最初未改变的形状，此处即要还原的最初样貌，符合句意。"}, {"text": "原野", "is_correct": false, "explanation": "语义：原野指空旷的土地，不能作为古塔最初的样貌，句意不通。"}, {"text": "原子", "is_correct": false, "explanation": "语义：原子是微观粒子，与古塔的外形无关，句意不通。"}, {"text": "原告", "is_correct": false, "explanation": "语义：原告指法律上提起诉讼的一方，与古塔的样貌无关，句意不通。"}], "explanations": {"原型": "原型：指最初未改变的形状，此处即要还原的最初样貌，符合句意。", "原野": "语义：原野指空旷的土地，不能作为古塔最初的样貌，句意不通。", "原子": "语义：原子是微观粒子，与古塔的外形无关，句意不通。", "原告": "语义：原告指法律上提起诉讼的一方，与古塔的样貌无关，句意不通。"}, "sentence_index": 0, "correct_answer": "原型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座老街经过改造，原型大变，已经认不出了。", "explanation": "这里应该用〈面貌〉。“面貌”指外观，可以说“面貌大变”；“原型”指最初未改变的形状，不能说“原型大变”。"}, {"text": "他买了一斤原型放进了锅里。", "explanation": "这里应该用〈食材〉。“原型”是抽象的形状或样式，不能称重，也不能放进锅里。"}, {"text": "工匠在废墟里找到了一条原型。", "explanation": "这里应该用〈个〉。“条”用于细长的物体，“原型”要用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12223, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原型", "is_correct": true, "explanation": "原型：指最初未改变的形状，与“改了很多”形成对照。"}, {"text": "原声", "is_correct": false, "explanation": "语义：原声指原本的声音或原唱，与椅子的样式无关，句意不通。"}, {"text": "原文", "is_correct": false, "explanation": "语义：原文指未经翻译或改写的文本，与椅子的样式无关，句意不通。"}, {"text": "原油", "is_correct": false, "explanation": "语义：原油是未加工的石油，与椅子的样式无关，句意不通。"}], "explanations": {"原型": "原型：指最初未改变的形状，与“改了很多”形成对照。", "原声": "语义：原声指原本的声音或原唱，与椅子的样式无关，句意不通。", "原文": "语义：原文指未经翻译或改写的文本，与椅子的样式无关，句意不通。", "原油": "语义：原油是未加工的石油，与椅子的样式无关，句意不通。"}, "sentence_index": 6, "correct_answer": "原型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店把门脸改成了新原型。", "explanation": "这里应该用〈样式〉。原型指最初未改变的形状，不能说“新原型”，改成新的形状要用“样式”。"}, {"text": "他用这个原型煮了一锅汤。", "explanation": "这里应该用〈食材〉。“原型”指最初未改变的形状或样式，是抽象的样式，不能用来煮汤，应指具体的食材。"}, {"text": "工人在墙角发现了一张原型。", "explanation": "这里应该用〈个〉。“张”用于纸张、桌面等平面物，原型用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12223, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "修复以后，这座老塔还能看出它的一只原型。", "corrected_sentence": "修复以后，这座老塔还能看出它的原型。", "error_description": "量词错误：“原型”不用“只”。错误形式：它的一只原型；正确形式：它的原型（若要加量词，用“个”）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12223, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师傅把钟的一条原型记下来了。", "corrected_sentence": "老师傅把钟的一个原型记下来了。", "error_description": "量词错误：“原型”用“个”，“条”用于细长的物体，不能用来计量原型。错误形式：一条原型；正确形式：一个原型。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
