INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12224, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指不断重复进行更新或改进的过程，用于描述技术、概念或方法的版本升级。", "primary_collocate": null, "pronunciation": "dié dài", "ipa": "tjɛ˧˥ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "此后四十年间，材料科学的迭代推动光伏技术进入指数级进化：多结叠层电池突破光谱响应极限，钙钛矿材料以其低廉成本与柔性特质颠覆传统制造逻辑，而双面组件设计更通过地面反射光捕获使发电量提升20%以上。", "target_word": "迭代", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "材料科学的进步使得复合材料得以广泛应用，不仅减轻了结构重量，还增强了疲劳耐久性；计算流体动力学（CFD）的发展则使工程师能够在虚拟风洞中模拟极端工况下的气动性能，从而在原型制造前完成多轮迭代。", "target_word": "迭代", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这款软件的每次迭代都修复了旧问题。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的迭代速度越来越快。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "团队经过三轮迭代，终于完成了设计。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产品迭代需要听取用户的意见。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "技术迭代让旧设备很快没人用了。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个模型经过多次迭代，效果好多了。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快速迭代是互联网公司的特点。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每一轮迭代之后，工程师都要做测试。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一轮迭代", "label": "量词搭配"}, {"form": "版本迭代", "label": "复合词"}, {"form": "快速迭代", "label": "复合词"}], "register": "书面", "sense_fingerprint": "技术、产品或方法不断更新改进的过程（版本升级）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c6fe7c9-33e8-4c2f-b2e6-ccbf82b54954') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12224, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迭代", "is_correct": true, "explanation": "正确：“迭代”指材料不断更新改进的过程，与“推动光伏技术进入指数级进化”相合。"}, {"text": "色彩", "is_correct": false, "explanation": "语义：色彩不能推动技术进化，与“指数级进化”的语境不合。"}, {"text": "尺寸", "is_correct": false, "explanation": "语义：尺寸大小不能推动光伏技术进步，与句中描述的技术突破不合。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这段书面化的科技叙述不符。"}], "explanations": {"迭代": "正确：“迭代”指材料不断更新改进的过程，与“推动光伏技术进入指数级进化”相合。", "色彩": "语义：色彩不能推动技术进化，与“指数级进化”的语境不合。", "尺寸": "语义：尺寸大小不能推动光伏技术进步，与句中描述的技术突破不合。", "玩意儿": "语域：“玩意儿”是口语说法，与这段书面化的科技叙述不符。"}, "sentence_index": 0, "correct_answer": "迭代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我们完成了一只迭代。", "explanation": "这里应该用〈轮〉。迭代的计量单位是“轮”，如“一轮迭代”；“只”多用于动物或成对的事物。"}, {"text": "公司今年的员工迭代了很多。", "explanation": "这里应该用〈增加〉。迭代指产品或技术反复更新，不能用来说人员数量变多，数量增长要用“增加”。"}, {"text": "这位工程师是公司的迭代。", "explanation": "迭代指更新改进的过程，不指人。这里要说人的身份，不能用“迭代”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12224, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迭代", "is_correct": true, "explanation": "正确：“迭代”指技术不断换新，与“旧设备很快没人用了”的因果相合。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料与设备是否被淘汰无关，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与设备被淘汰没有因果关系，句意不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：人的年龄与设备被淘汰无关，句意不通。"}], "explanations": {"迭代": "正确：“迭代”指技术不断换新，与“旧设备很快没人用了”的因果相合。", "饮料": "语义：饮料与设备是否被淘汰无关，句意不通。", "颜色": "语义：颜色与设备被淘汰没有因果关系，句意不通。", "年龄": "语义：人的年龄与设备被淘汰无关，句意不通。"}, "sentence_index": 6, "correct_answer": "迭代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们昨天发布了一台迭代。", "explanation": "这里应该用〈轮〉。迭代的计量用“轮”，“台”多用于机器，不用于更新的过程。"}, {"text": "他每天早上吃一碗迭代。", "explanation": "这里误用了词义：迭代指更新改进的过程，是抽象的，不能当作食物来吃。"}, {"text": "水的迭代让大地变得湿润。", "explanation": "这里应该用〈循环〉。迭代指技术、产品的版本更新，不用于自然界的水循环。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "团队经过两只迭代，终于完成了设计。", "corrected_sentence": "团队经过两轮迭代，终于完成了设计。", "error_description": "“迭代”的量词应为“轮”，应说“两轮迭代”。用“只”是错误的，“只”多用于动物或成对的事物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每一迭代之后，工程师都要做检查。", "corrected_sentence": "每一轮迭代之后，工程师都要做检查。", "error_description": "“每一”后面必须接量词，“迭代”前应加量词“轮”，应说“每一轮迭代”，不能省略量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
