INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12225, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "控制技术是指通过一定的手段和方法，使系统或设备按照预定目标运行的技术。", "primary_collocate": null, "pronunciation": "kòng zhì jì shù", "ipa": "kʰʊŋ˥˩ ʈʂʐ̩˥˩ tɕi˥˩ ʂu˥˩", "syllable_count": 4, "sentences": [{"text": "此外，主动流动控制技术，如边界层吸入或合成射流，正在被探索用于实时调节气流分离，进一步延展飞行包线。", "target_word": "控制技术", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "现代工厂的生产离不开控制技术。", "target_word": "控制技术", "complexity_tier": "T3", "furigana": "xiàn dài gōng chǎng de shēng chǎn lí bu kāi kòng zhì jì shù", "sentence_source": "generated"}, {"text": "这家公司研究飞机的控制技术。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "控制技术能让机器人准确地完成工作。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的控制技术使火车更安全。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学专门学习控制技术。", "target_word": "控制技术", "complexity_tier": "T3", "furigana": "tā zài dà xué zhuān mén xué xí kòng zhì jì shù", "sentence_source": "generated"}, {"text": "工程师用控制技术管理整个工厂的电力。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "控制技术的进步让生产更快。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个系统用了最新的控制技术。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人驾驶汽车需要先进的控制技术。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "使系统或设备按预定目标运行的技术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c52c201-a9c6-4f97-a07d-ccfe566aedfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
